/* global loadGameCatalogScript, ensureGameUi, settings, saveSettings, toast, esc, $ */
/* Catálogos + UI de cada juego. Se carga al abrir Juegos / Acciones (o en idle). */

/* ================= Acciones de Minecraft (RCON) ================= */

const gameCatOpenSecs = new Map();

function gameCatOpenSet(key) {
  if (!gameCatOpenSecs.has(key)) gameCatOpenSecs.set(key, new Set());
  return gameCatOpenSecs.get(key);
}

function gameActionFinger(a) {
  if (!a || typeof a !== 'object') return '';
  return [
    String(a.catId || ''),
    String(a.trigger || a.event || ''),
    String(a.giftId || ''),
    String(a.giftName || '').trim().toLowerCase(),
    String(a.cmd || a.command || a.thing || a.npcId || a.keys || ''),
    String(a.name || a.label || '').trim().toLowerCase(),
  ].join('|');
}

/** Al apagar: también apaga duplicados (mismo regalo/cmd) para que el live no dispare una copia ON. */
function disableMatchingGameActions(settingsKey, action) {
  const list = settings && Array.isArray(settings[settingsKey]) ? settings[settingsKey] : null;
  if (!list || !action) return 0;
  const finger = gameActionFinger(action);
  if (!finger || finger === '|||||') return 0;
  let n = 0;
  for (const x of list) {
    if (!x || x === action) continue;
    if (gameActionFinger(x) !== finger) continue;
    if (x.enabled === false) continue;
    x.enabled = false;
    n += 1;
  }
  return n;
}

function wireGameToggleAllButton(buttonId, getList, renderFn, settingsKey) {
  const toggleAll = document.getElementById(buttonId);
  if (!toggleAll || toggleAll._wired) return;
  toggleAll._wired = true;
  toggleAll.onclick = () => {
    const list = getList();
    if (!list.length) { toast && toast('Primero agrega acciones del catálogo.', 'warn'); return; }
    const anyOff = list.some((a) => a.enabled === false);
    list.forEach((a) => { a.enabled = anyOff; });
    lastGameActionEditAt = Date.now();
    // Solo enabled: no sync Editor Pro (rompe montaje / Live Studio).
    if (settingsKey) {
      saveSettingsKeysPatch(settingsKey, { skipErSync: true, flush: true });
    } else flushSaveSettings();
    renderFn();
    toast && toast(anyOff ? 'Todas las acciones encendidas.' : 'Todas las acciones apagadas.', 'ok');
  };
}

function gameCatListBtnHtml(id, label, iconHtml, title) {
  return `<button type="button" class="game-act-swap-item repo-cat-list-item" data-id="${esc(id)}" title="${esc(title || label)}">
    ${iconHtml || ''}
    <span class="game-act-swap-item-copy"><strong>${esc(label)}</strong></span>
  </button>`;
}

function buildCatalogSections(list, opts = {}) {
  const {
    sectionKey = 'section',
    order,
    labelMap,
    iconMap,
    descMap,
    searching,
    getSectionId,
  } = opts;
  const bySection = new Map();
  for (const c of list) {
    const sec = getSectionId ? getSectionId(c) : (c[sectionKey] || c.tipo || c.category || 'other');
    if (!bySection.has(sec)) bySection.set(sec, []);
    bySection.get(sec).push(c);
  }
  let keys;
  if (searching) {
    keys = [...bySection.keys()].sort((a, b) => {
      const ai = order?.indexOf(a) ?? 999;
      const bi = order?.indexOf(b) ?? 999;
      if (ai === bi) return String(a).localeCompare(String(b), 'es');
      return (ai < 0 ? 999 : ai) - (bi < 0 ? 999 : bi);
    });
  } else if (order?.length) {
    keys = order.filter((s) => bySection.has(s));
    // No omitir secciones fuera del order (p. ej. tipo nuevo).
    for (const s of bySection.keys()) if (!keys.includes(s)) keys.push(s);
  } else {
    keys = [...bySection.keys()];
  }
  return keys.map((id) => ({
    id,
    icon: iconMap?.[id] || '🎮',
    label: labelMap?.[id] || id,
    desc: descMap?.[id] || '',
    items: bySection.get(id) || [],
  }));
}

function catalogFoldBodyHtml(sec, rowHtml) {
  return `${sec.desc ? `<p class="repo-cat-sec-desc">${esc(sec.desc)}</p>` : ''}
          <div class="repo-cat-list">${(sec.items || []).map((item) => rowHtml(item)).join('')}</div>`;
}

function fillCatalogFoldBody(fold, grid) {
  const body = fold.querySelector('.repo-cat-fold-body');
  if (!body || body.dataset.filled === '1') return;
  const sec = (grid._catSections || []).find((s) => String(s.id) === String(fold.dataset.sec));
  if (!sec || typeof grid._catRowHtml !== 'function') return;
  body.dataset.filled = '1';
  body.innerHTML = catalogFoldBodyHtml(sec, grid._catRowHtml);
}

function scheduleCatalogFoldFills(grid, folds) {
  let i = 0;
  const step = () => {
    if (!grid?.isConnected) return;
    while (i < folds.length) {
      fillCatalogFoldBody(folds[i], grid);
      i += 1;
      if (i < folds.length) {
        requestAnimationFrame(step);
        return;
      }
    }
  };
  if (folds.length) requestAnimationFrame(step);
}

function renderGameCatalogFold(opts) {
  const grid = typeof opts.grid === 'string' ? document.getElementById(opts.grid) : opts.grid;
  if (!grid) return;
  bindGameCatalogFoldClicks();
  grid._catOnPick = typeof opts.onPick === 'function' ? opts.onPick : null;
  grid._catCloseModalId = opts.closeModalId || '';
  grid._catSearchId = opts.searchId || '';
  grid._catRerender = typeof opts.rerender === 'function' ? opts.rerender : null;
  grid._catStateKey = opts.stateKey || '';
  grid._catRowHtml = typeof opts.rowHtml === 'function' ? opts.rowHtml : null;
  const sections = (opts.sections || []).filter((s) => s.items?.length);
  grid._catSections = sections;
  grid.classList.add('game-act-swap-list', 'game-cat-thick-list');
  grid.classList.remove('repo-cat-fluid');
  const rowHtml = typeof opts.rowHtml === 'function' ? opts.rowHtml : () => '';
  if (!sections.length) {
    grid.innerHTML = `<div class="game-act-swap-empty">${esc(opts.emptyMsg || 'Sin resultados.')}</div>`;
    return;
  }
  // Todas las entradas, por sección (orden del catálogo). Cabeceras ligeras + filas gruesas.
  grid.innerHTML = sections.map((sec) => {
    const rows = (sec.items || []).map((item) => rowHtml(item)).join('');
    return `<div class="game-cat-sec" data-sec="${esc(sec.id)}">
      <div class="game-cat-sec-label">${esc(sec.label)} <span>(${sec.items.length})</span></div>
      ${rows}
    </div>`;
  }).join('');
}

function bindGameCatalogFoldClicks() {
  if (bindGameCatalogFoldClicks._on) return;
  bindGameCatalogFoldClicks._on = true;
  document.addEventListener('click', (e) => {
    const item = e.target?.closest?.('.repo-cat-list-item');
    if (item) {
      const grid = item.closest('.game-catalog-wrap');
      if (!grid || typeof grid._catOnPick !== 'function') return;
      e.preventDefault();
      e.stopPropagation();
      const id = item.getAttribute('data-id') || item.dataset.id || '';
      if (grid._catCloseModalId) closeGameCatalogModal(grid._catCloseModalId);
      try { grid._catOnPick(id); }
      catch (err) {
        console.warn('catalog onPick', err);
        toast && toast('No se pudo agregar la acción.', 'warn');
      }
      return;
    }
    const head = e.target?.closest?.('.repo-cat-fold-head');
    if (!head) return;
    const grid = head.closest('.game-catalog-wrap');
    const fold = head.closest('.repo-cat-fold');
    const sec = fold?.dataset?.sec;
    if (!grid || !sec) return;
    const openSecs = gameCatOpenSet(grid._catStateKey);
    const willOpen = !openSecs.has(sec);
    if (willOpen) {
      openSecs.add(sec);
      fold.classList.add('open');
      head.setAttribute('aria-expanded', 'true');
      requestAnimationFrame(() => fillCatalogFoldBody(fold, grid));
    } else {
      openSecs.delete(sec);
      fold.classList.remove('open');
      head.setAttribute('aria-expanded', 'false');
    }
  }, true);
}

function closeGameCatalogModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.classList.add('hidden');
}

function placeGameCatalogPop(modal, anchor) {
  if (!modal) return;
  const box = modal.querySelector('.game-cat-modal-box') || modal.querySelector('.modal-box');
  if (!box) return;
  const w = Math.min(320, window.innerWidth - 16);
  box.style.width = w + 'px';
  box.style.maxWidth = w + 'px';
  const h = box.offsetHeight || 340;
  let left = 8;
  let top = 8;
  if (anchor && typeof anchor.getBoundingClientRect === 'function') {
    const r = anchor.getBoundingClientRect();
    left = r.left;
    top = r.bottom + 6;
    if (left + w > window.innerWidth - 8) left = window.innerWidth - w - 8;
    if (left < 8) left = 8;
    if (top + h > window.innerHeight - 8) top = Math.max(8, r.top - h - 6);
  }
  box.style.left = left + 'px';
  box.style.top = top + 'px';
}

/** Misma piel DOM que #game-act-swap-pop (Cambiar elemento). */
function restyleCatalogModalAsSwap(cfg) {
  const modal = document.getElementById(cfg.modalId);
  if (!modal || modal._asSwap) return;
  modal._asSwap = true;
  const box = modal.querySelector('.modal-box');
  if (box) {
    box.classList.add('game-act-swap-pop', 'game-cat-modal-box');
    box.classList.remove('wide');
  }
  const head = modal.querySelector('.modal-head');
  const search = document.getElementById(`${cfg.prefix}-cat-search`);
  const closeBtn = document.getElementById(`${cfg.prefix}-cat-close`);
  const body = modal.querySelector('.modal-body');
  if (head) {
    head.className = 'game-act-swap-head';
    head.querySelectorAll('.vidlib-sub').forEach((n) => n.remove());
    const titleWrap = head.querySelector('div');
    const h2 = head.querySelector('h2');
    if (h2 || titleWrap) {
      const strong = document.createElement('strong');
      strong.id = `${cfg.prefix}-cat-title`;
      strong.textContent = 'Catálogo';
      if (titleWrap) titleWrap.replaceWith(strong);
      else if (h2) h2.replaceWith(strong);
    }
    // Buscador como hermano del head (igual que Cambiar elemento), no dentro del head.
    if (search && search.parentElement === head && box) {
      head.after(search);
    }
  }
  if (search) {
    search.className = 'game-act-swap-search';
    search.placeholder = 'Buscar elemento…';
  }
  if (closeBtn) {
    closeBtn.className = 'game-act-swap-x';
    closeBtn.textContent = '✕';
    if (head && closeBtn.parentElement !== head) head.appendChild(closeBtn);
  }
  if (body) {
    body.className = 'game-cat-modal-body';
    body.style.cssText = 'padding:0;margin:0;min-height:0;flex:1;overflow:hidden;display:flex;flex-direction:column;';
  }
}

async function openGameCatalogModal(cfg) {
  restyleCatalogModalAsSwap(cfg);
  const modal = document.getElementById(cfg.modalId);
  const search = document.getElementById(`${cfg.prefix}-cat-search`);
  const openBtn = document.getElementById(`${cfg.prefix}-open-catalog`);
  if (!modal) return;
  document.querySelectorAll('.game-catalog-modal:not(.hidden)').forEach((el) => {
    if (el.id !== cfg.modalId) el.classList.add('hidden');
  });
  closeGameActSwapPop();
  if (search) search.value = '';
  if (cfg.prefix === 'mk64' || cfg.prefix === 'mc') gameCatOpenSet(cfg.prefix).clear();
  modal.classList.remove('hidden');
  placeGameCatalogPop(modal, openBtn);
  const gameKey = CATALOG_PREFIX_TO_GAME[cfg.prefix] || cfg.prefix;
  const paint = () => {
    try { cfg.render(search?.value || ''); } catch (err) { console.warn('catalog render', err); }
    placeGameCatalogPop(modal, openBtn);
  };
  paint();
  try { await ensureGameUi(gameKey); } catch (e) { console.warn('catalog ensureGameUi', gameKey, e); }
  paint();
  requestAnimationFrame(() => {
    placeGameCatalogPop(modal, openBtn);
    search?.focus?.();
  });
}

function setupGameCatalogModal(cfg) {
  restyleCatalogModalAsSwap(cfg);
  const search = document.getElementById(`${cfg.prefix}-cat-search`);
  if (search && !search._wired) {
    search._wired = true;
    search.oninput = () => {
      clearTimeout(search._catDebounce);
      search._catDebounce = setTimeout(() => {
        cfg.render(search.value);
        const modal = document.getElementById(cfg.modalId);
        const openBtn = document.getElementById(`${cfg.prefix}-open-catalog`);
        placeGameCatalogPop(modal, openBtn);
      }, cfg.prefix === 'mk64' ? 140 : 80);
    };
  }
  const openBtn = document.getElementById(`${cfg.prefix}-open-catalog`);
  if (openBtn && !openBtn._wired) {
    openBtn._wired = true;
    openBtn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      openGameCatalogModal(cfg);
    };
  }
  const closeBtn = document.getElementById(`${cfg.prefix}-cat-close`);
  if (closeBtn && !closeBtn._wired) {
    closeBtn._wired = true;
    closeBtn.onclick = () => closeGameCatalogModal(cfg.modalId);
  }
  const modal = document.getElementById(cfg.modalId);
  if (modal && !modal._wired) {
    modal._wired = true;
    modal.addEventListener('click', (e) => {
      if (e.target.id === cfg.modalId) closeGameCatalogModal(cfg.modalId);
    });
    const box = modal.querySelector('.game-cat-modal-box') || modal.querySelector('.modal-box');
    if (box) {
      box.addEventListener('mousedown', (e) => e.stopPropagation());
      box.addEventListener('click', (e) => e.stopPropagation());
    }
  }
}

function initGameCatalogModals() {
  const specs = [
    { prefix: 'mario', modalId: 'marioCatalogModal', render: renderMarioCatalog },
    { prefix: 'smb3', modalId: 'smb3CatalogModal', render: renderSmb3Catalog },
    { prefix: 'mari0', modalId: 'mari0CatalogModal', render: renderMari0Catalog },
    { prefix: 'pvz', modalId: 'pvzCatalogModal', render: renderPvzCatalog },
    { prefix: 'pvzhybrid', modalId: 'pvzhybridCatalogModal', render: renderPvzHybridCatalog },
    { prefix: 'repo', modalId: 'repoCatalogModal', render: renderRepoCatalog },
    { prefix: 'l4d', modalId: 'l4dCatalogModal', render: renderL4dCatalog },
    { prefix: 'unturned', modalId: 'unturnedCatalogModal', render: renderUnturnedCatalog },
    { prefix: 'gtavkoth', modalId: 'gtavkothCatalogModal', render: renderGtavKothCatalog },
    { prefix: 'gtavchaos', modalId: 'gtavchaosCatalogModal', render: renderGtavChaosCatalog },
    { prefix: 'gtavchiliad', modalId: 'gtavchiliadCatalogModal', render: renderGtavChiliadCatalog },

    { prefix: 'ctr', modalId: 'ctrCatalogModal', render: renderCtrCatalog },
    { prefix: 'flappy', modalId: 'flappyCatalogModal', render: renderFlappyCatalog },
    { prefix: 'mk64', modalId: 'mk64CatalogModal', render: renderMk64Catalog },
    { prefix: 'stack', modalId: 'stackCatalogModal', render: renderStackCatalog },
    { prefix: 'crossy', modalId: 'crossyCatalogModal', render: renderCrossyCatalog },
    { prefix: 'bite', modalId: 'biteCatalogModal', render: renderBiteCatalog },
    { prefix: 'hill', modalId: 'hillCatalogModal', render: renderHillCatalog },
    { prefix: 'supermarket', modalId: 'supermarketCatalogModal', render: renderSupermarketCatalog },
    { prefix: 'peak', modalId: 'peakCatalogModal', render: renderPeakCatalog },
    { prefix: 'overcooked2', modalId: 'overcooked2CatalogModal', render: renderOvercooked2Catalog },
    { prefix: 'bottle', modalId: 'bottleCatalogModal', render: renderBottleCatalog },
    { prefix: 'pvzge', modalId: 'pvzgeCatalogModal', render: renderPvzgeCatalog },
    { prefix: 'pvzfusion', modalId: 'pvzfusionCatalogModal', render: renderPvzFusionCatalog },
    { prefix: 'smw', modalId: 'smwCatalogModal', render: renderSmwCatalog },
    { prefix: 'mslug', modalId: 'mslugCatalogModal', render: renderMslugCatalog },
    { prefix: 'gdash', modalId: 'gdashCatalogModal', render: renderGdashCatalog },
    { prefix: 'mc', modalId: 'mcCatalogModal', render: renderMcCatalog },
    { prefix: 'mcshooter', modalId: 'mcshooterCatalogModal', render: renderMcShooterCatalog },
    { prefix: 'bedrock', modalId: 'bedrockCatalogModal', render: renderBedrockCatalog },
    { prefix: 'mcparkour', modalId: 'mcparkourCatalogModal', render: renderParkourCatalog },
    { prefix: 'mconeblock', modalId: 'mconeblockCatalogModal', render: renderOneblockCatalog },
    { prefix: 'mcparadise', modalId: 'mcparadiseCatalogModal', render: renderParadiseCatalog },
    { prefix: 'mcsandwall', modalId: 'mcsandwallCatalogModal', render: renderSandwallCatalog },
    { prefix: 'mckoth', modalId: 'mckothCatalogModal', render: renderKothCatalog },
    { prefix: 'mcfarm', modalId: 'mcfarmCatalogModal', render: renderFarmCatalog },
    { prefix: 'sandbox', modalId: 'sandboxCatalogModal', render: renderSandboxCatalog },
  ];
  for (const cfg of specs) setupGameCatalogModal(cfg);
  if (!window._gameCatPopEsc) {
    window._gameCatPopEsc = true;
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      const open = document.querySelector('.game-catalog-modal:not(.hidden)');
      if (open) closeGameCatalogModal(open.id);
    });
    document.addEventListener('mousedown', (e) => {
      const open = document.querySelector('.game-catalog-modal:not(.hidden)');
      if (!open) return;
      const box = open.querySelector('.game-cat-modal-box') || open.querySelector('.modal-box');
      if (box && box.contains(e.target)) return;
      if (e.target.closest?.('[id$="-open-catalog"]')) return;
      closeGameCatalogModal(open.id);
    });
  }
}

