function gamePresetActionKeys() {
  return Object.values(GAME_PRESET_MAP).map((g) => g.key);
}

function mcPresetActionKeys() {
  return gamePresetActionKeys();
}

function mcPresetBanksPatchForTouched(touched) {
  if (!settings || !settings.mcPresetBanks) return null;
  const other = (typeof mcPresetActionKeys === 'function' ? mcPresetActionKeys() : []).filter((k) => k !== 'actions');
  if (other.some((k) => touched.includes(k))) return settings.mcPresetBanks;
  if (settings.mcPresetBanks.acciones) return { acciones: settings.mcPresetBanks.acciones };
  return settings.mcPresetBanks;
}

const mcPresetDirtyGames = new Set();
const mcPresetReconciledGames = new Set();
const _mcPresetBarRaf = new Map();
const _mcPresetRenderRaf = new Map();
const _gamePresetBarReady = new Set();
let _mcPresetMigrateTimer = null;

function runWhenIdle(fn, timeoutMs = 600) {
  if (typeof window.requestIdleCallback === 'function') {
    window.requestIdleCallback(() => { try { fn(); } catch {} }, { timeout: timeoutMs });
  } else {
    setTimeout(() => { try { fn(); } catch {} }, 0);
  }
}

function resetMcPresetSessionCaches() {
  mcPresetDirtyGames.clear();
  mcPresetReconciledGames.clear();
  _gamePresetBarReady.clear();
  accIxLiveReady = false;
  try { window.__accIxLiveReady = false; } catch {}
  for (const id of _mcPresetBarRaf.values()) cancelAnimationFrame(id);
  _mcPresetBarRaf.clear();
  for (const id of _mcPresetRenderRaf.values()) cancelAnimationFrame(id);
  _mcPresetRenderRaf.clear();
  clearTimeout(_mcPresetMigrateTimer);
  _mcPresetMigrateTimer = null;
}

function scheduleRefreshMcPresetBar(game) {
  if (_mcPresetBarRaf.has(game)) return;
  const id = requestAnimationFrame(() => {
    _mcPresetBarRaf.delete(game);
    refreshMcPresetBar(game);
  });
  _mcPresetBarRaf.set(game, id);
}

function scheduleGamePresetRender(game) {
  if (_mcPresetRenderRaf.has(game)) cancelAnimationFrame(_mcPresetRenderRaf.get(game));
  const id = requestAnimationFrame(() => {
    _mcPresetRenderRaf.delete(game);
    const meta = GAME_PRESET_MAP[game];
    if (meta) meta.render();
  });
  _mcPresetRenderRaf.set(game, id);
}

function flushMcPresetBankMigration() {
  clearTimeout(_mcPresetMigrateTimer);
  _mcPresetMigrateTimer = setTimeout(() => {
    _mcPresetMigrateTimer = null;
    try { saveSettingsKeysPatch('mcPresetBanks'); } catch {}
  }, 450);
}

function saveGamePresetState(game, opts = {}) {
  const meta = GAME_PRESET_MAP[game];
  if (!meta || !settings) return;
  if (opts.sync !== false) syncMcPresetFromActions(game);
  const patchOpts = {};
  if (opts.skipErSync) patchOpts.skipErSync = true;
  // Por defecto inmediato a disco (evitar perder acciones al cerrar/actualizar).
  patchOpts.flush = opts.flush !== false;
  if (game === 'acciones') saveSettingsKeysPatch(meta.key, 'actionEvents', 'mcPresetBanks', patchOpts);
  else saveSettingsKeysPatch(meta.key, 'mcPresetBanks', patchOpts);
}

function gamePresetFromSettingsKey(key) {
  for (const [game, g] of Object.entries(GAME_PRESET_MAP)) {
    if (g.key === key) return game;
  }
  return null;
}

function mcGameFromSettingsKey(key) {
  return gamePresetFromSettingsKey(key);
}

function markMcPresetDirty(game) {
  if (game && GAME_PRESET_MAP[game]) mcPresetDirtyGames.add(game);
}

function normalizeMcPresetShareCodeClient(raw) {
  const s = String(raw || '').trim().toUpperCase().replace(/\s+/g, '');
  if (!s) return '';
  const body = s.startsWith('MC-') ? s.slice(3) : s;
  if (!/^[A-Z2-9]{4,12}$/.test(body)) return '';
  return 'MC-' + body;
}

function gamePresetUiPrefix(game) {
  if (game === 'minecraft') return 'mc';
  if (game === 'roblox') return 'rbx';
  if (game === 'roblox3') return 'rbx3';
  return game;
}

function mcPresetUiPrefix(game) {
  return gamePresetUiPrefix(game);
}

function mcPresetCloneActions(list) {
  try { return JSON.parse(JSON.stringify(Array.isArray(list) ? list : [])); }
  catch { return []; }
}

function newMcPresetId() {
  return 'mcbnk_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
}

function mcPresetHasData(bank) {
  return !!(bank && Array.isArray(bank.presets) && bank.presets.length);
}

/** True cuando la lista viva de Acciones ya se hidrató desde el pack/General. */
let accIxLiveReady = false;
function markAccIxLiveReady() {
  accIxLiveReady = true;
  try { window.__accIxLiveReady = true; } catch {}
}

function accIxPackHasContent(pack) {
  if (!pack || typeof pack !== 'object') return false;
  const acts = Array.isArray(pack.actions) ? pack.actions : [];
  const evs = Array.isArray(pack.actionEvents) ? pack.actionEvents : [];
  if (acts.some((a) => a && (a.id || a.keys || a.name))) return true;
  if (evs.some((e) => e && e.id)) return true;
  return false;
}
/** Packs vacíos clonados de las 10 ranuras de la app. Los creados con «Nuevo» (mcbnk_ fecha) no se tocan. */
function pruneEmptyAccIxAutoPacks(bank) {
  if (!bank || !Array.isArray(bank.presets)) return false;
  const packs = bank.presets.filter((p) => p && p.id);
  if (packs.length <= 1) return false;
  const autoEmpty = (p) => /^mcbnk_app_/.test(String(p.id || '')) && !accIxPackHasContent(p);
  const keep = packs.filter((p) => !autoEmpty(p));
  if (keep.length === packs.length) return false;
  if (!keep.length) {
    const prefer = packs.find((p) => p.id === bank.activeId)
      || packs.find((p) => /^Perfil\s+1$/i.test(String(p.name || '')))
      || packs[0];
    if (prefer) keep.push(prefer);
  }
  if (!keep.length) return false;
  bank.presets = keep;
  if (!keep.some((p) => p && p.id === bank.activeId)) {
    const next = keep.find(accIxPackHasContent) || keep[0];
    bank.activeId = next.id;
  }
  return true;
}

function ensureAccInteractiveMeta(bank) {
  if (!bank || typeof bank !== 'object') return bank;
  if (bank.editMode !== 'general') bank.editMode = 'profile';
  if (!bank.general || typeof bank.general !== 'object') bank.general = { actions: [], actionEvents: [] };
  if (!Array.isArray(bank.general.actions)) bank.general.actions = [];
  if (!Array.isArray(bank.general.actionEvents)) bank.general.actionEvents = [];
  return bank;
}

function accIxRekeyBag(actions, events) {
  const map = new Map();
  const nextActions = mcPresetCloneActions(actions).map((a, i) => {
    const copy = a && typeof a === 'object' ? a : {};
    const old = String(copy.id || '');
    copy.id = 'act_' + Date.now() + '_' + i + '_' + Math.random().toString(36).slice(2, 7);
    if (old) map.set(old, copy.id);
    delete copy.uid;
    return copy;
  });
  const nextEvents = mcPresetCloneActions(events).map((ev, i) => {
    const copy = ev && typeof ev === 'object' ? ev : {};
    copy.id = 'acev_' + Date.now() + '_' + i + '_' + Math.random().toString(36).slice(2, 7);
    copy.actionIds = (copy.actionIds || []).map((id) => map.get(String(id)) || id).filter(Boolean);
    copy.randomActionIds = (copy.randomActionIds || []).map((id) => map.get(String(id)) || id).filter(Boolean);
    return copy;
  });
  return { actions: nextActions, actionEvents: nextEvents };
}

function ensureMcPresetBank(game) {
  if (!settings) return null;
  const meta = GAME_PRESET_MAP[game];
  if (!meta) return null;
  if (!settings.mcPresetBanks || typeof settings.mcPresetBanks !== 'object') settings.mcPresetBanks = {};
  let bank = settings.mcPresetBanks[game];
  const actions = Array.isArray(settings[meta.key]) ? settings[meta.key] : [];
  if (mcPresetHasData(bank)) {
    if (!bank.activeId || !bank.presets.some((p) => p && p.id === bank.activeId)) bank.activeId = bank.presets[0].id;
    if (game === 'acciones') ensureAccInteractiveMeta(bank);
    return bank;
  }
  // Interactive: banco ya existe (aunque packs=[] / solo General). NO fabricar
  // un pack desde la lista viva — eso duplicaba y resucitaba acciones viejas.
  if (game === 'acciones' && bank && typeof bank === 'object') {
    if (!Array.isArray(bank.presets)) bank.presets = [];
    ensureAccInteractiveMeta(bank);
    if (bank.activeId && !bank.presets.some((p) => p && p.id === bank.activeId)) {
      bank.activeId = bank.presets[0] ? bank.presets[0].id : '';
    }
    settings.mcPresetBanks[game] = bank;
    return bank;
  }
  // Banco vacío/corrupto: recuperar un preset desde acciones vivas (nunca borrar presets existentes).
  const id = (bank && bank.activeId) || newMcPresetId();
  bank = {
    activeId: id,
    editMode: (bank && bank.editMode === 'general') ? 'general' : 'profile',
    general: (game === 'acciones')
      ? ((bank && bank.general) || { actions: [], actionEvents: [] })
      : undefined,
    presets: [{
      id,
      name: game === 'acciones' ? 'Perfil 1' : 'Preset 1',
      actions: mcPresetCloneActions(actions),
      actionEvents: game === 'acciones' ? mcPresetCloneActions(settings.actionEvents || []) : [],
    }],
  };
  if (game === 'acciones') ensureAccInteractiveMeta(bank);
  settings.mcPresetBanks[game] = bank;
  return bank;
}

function normalizeGamePresetLiveActions(game) {
  if (!settings) return [];
  if (game === 'roblox') return ensureRobloxSlots();
  if (game === 'roblox3') return ensureRoblox3Slots();
  const meta = GAME_PRESET_MAP[game];
  if (!meta) return [];
  return Array.isArray(settings[meta.key]) ? settings[meta.key] : [];
}

function refreshVisibleGamePresetBars() {
  if (!settings || typeof GAME_PRESET_MAP !== 'object') return;
  for (const game of Object.keys(GAME_PRESET_MAP)) {
    if (document.getElementById(gamePresetUiPrefix(game) + '-preset-select')) scheduleRefreshMcPresetBar(game);
  }
}

function syncMcPresetFromActions(game) {
  const bank = ensureMcPresetBank(game);
  const meta = GAME_PRESET_MAP[game];
  if (!bank || !meta) return;
  if (game === 'acciones') {
    ensureAccInteractiveMeta(bank);
    const liveActions = mcPresetCloneActions(normalizeGamePresetLiveActions(game));
    const liveEvents = mcPresetCloneActions(settings.actionEvents || []);
    const liveN = liveActions.length + liveEvents.length;
    const dest = bank.editMode === 'general'
      ? bank.general
      : (bank.presets.find((p) => p && p.id === bank.activeId) || null);
    if (!dest) return;
    const destN = (Array.isArray(dest.actions) ? dest.actions.length : 0)
      + (Array.isArray(dest.actionEvents) ? dest.actionEvents.length : 0);
    const wasReady = accIxLiveReady;
    // Live más gordo y aún no hidratado = catálogo viejo. No infectar el pack.
    if (!wasReady && destN > 0 && liveN > destN) return;
    if (liveN > 0) {
      accIxLiveReady = true;
      try { window.__accIxLiveReady = true; } catch {}
    }
    if (liveN === 0 && destN > 0 && (
      (typeof applyingSettings !== 'undefined' && applyingSettings)
      || !wasReady
    )) return;
    dest.actions = liveActions;
    dest.actionEvents = liveEvents;
    if (bank.editMode !== 'general') {
      const er = captureEditorRapidoForGame(game);
      if (er) dest.editorRapido = er;
    }
    return;
  }
  const active = bank.presets.find((p) => p && p.id === bank.activeId);
  if (!active) return;
  const liveActions = mcPresetCloneActions(normalizeGamePresetLiveActions(game));
  const liveN = liveActions.length;
  const packN = Array.isArray(active.actions) ? active.actions.length : 0;
  // Eco/carga: no vaciar preset rico de Bedrock/Mario/etc. con lista viva vacía.
  if (liveN === 0 && packN > 0 && (typeof applyingSettings !== 'undefined' && applyingSettings)) return;
  active.actions = liveActions;
  const er = captureEditorRapidoForGame(game);
  if (er) active.editorRapido = er;
}

/** Clona el montaje del Editor Pro ligado a este juego (si existe). */
function cloneEditorRapidoSnap(snap) {
  try { return JSON.parse(JSON.stringify(snap)); }
  catch { return null; }
}

function captureEditorRapidoForGame(game) {
  const meta = GAME_PRESET_MAP[game];
  if (!meta || !settings) return null;
  let snap = null;
  try {
    if (typeof window.getEditorRapidoSnapshot === 'function') {
      snap = window.getEditorRapidoSnapshot();
    }
  } catch {}
  if (!snap || typeof snap !== 'object') {
    snap = settings.editorRapido;
  }
  if (!snap || typeof snap !== 'object') return null;
  const linked = String(snap.gameSync?.settingsKey || '').trim();
  // Solo guardar si el Editor Pro está vinculado a este juego.
  if (!linked || linked !== meta.key) return null;
  return cloneEditorRapidoSnap(snap);
}

/**
 * Al cambiar de preset: restaura la plantilla del Editor Pro de ese preset.
 * Si no había ninguna, reconstruye desde las acciones (comportamiento anterior).
 */
function restoreEditorRapidoForGamePreset(game, preset) {
  const meta = GAME_PRESET_MAP[game];
  if (!meta) return;
  suppressEditorRapidoSync(2000);
  const snap = preset && preset.editorRapido;
  if (snap && typeof snap === 'object' && (Array.isArray(snap.overlays) || snap.count != null)) {
    const next = cloneEditorRapidoSnap(snap);
    if (!next) {
      setTimeout(() => notifyEditorRapidoActionsChanged(meta.key), 80);
      return;
    }
    if (!next.gameSync || typeof next.gameSync !== 'object') next.gameSync = {};
    next.gameSync.settingsKey = meta.key;
    try {
      if (typeof window.applyEditorRapidoPresetSnapshot === 'function') {
        window.applyEditorRapidoPresetSnapshot(next, { flush: true });
      } else {
        window.__applyEditorRapidoFromSettings?.(next);
        settings.editorRapido = next;
        saveSettingsKeysPatch('editorRapido', { skipErSync: true, flush: true });
      }
    } catch (e) {
      console.warn('restoreEditorRapidoForGamePreset', e);
    }
    // Parche suave de regalos/qty con las acciones vivas (mismos uid → no borra montaje).
    setTimeout(() => {
      erSyncSuppressedUntil = 0;
      notifyEditorRapidoActionsChanged(meta.key);
    }, 350);
    return;
  }
  setTimeout(() => {
    erSyncSuppressedUntil = 0;
    notifyEditorRapidoActionsChanged(meta.key);
  }, 80);
}

function syncMcPresetsFromDirty() {
  if (!settings || applyingSettings || !mcPresetDirtyGames.size) return;
  for (const game of mcPresetDirtyGames) syncMcPresetFromActions(game);
  mcPresetDirtyGames.clear();
}

function syncAllMcPresetsFromActions() {
  syncMcPresetsFromDirty();
}

function activateMcPresetRuntime(game) {
  const bank = settings.mcPresetBanks?.[game];
  const meta = GAME_PRESET_MAP[game];
  if (!meta || !mcPresetHasData(bank)) return;
  if (game === 'acciones') {
    ensureAccInteractiveMeta(bank);
    if (bank.editMode === 'general') {
      settings[meta.key] = mcPresetCloneActions(bank.general.actions);
      settings.actionEvents = mcPresetCloneActions(bank.general.actionEvents);
      markAccIxLiveReady();
      migrateAccionesLegacyEvents(settings);
      if (typeof migrateVideosToAcciones === 'function') migrateVideosToAcciones(settings);
      return;
    }
  }
  const active = bank.presets.find((p) => p && p.id === bank.activeId) || bank.presets[0];
  if (!active) return;
  bank.activeId = active.id;
  settings[meta.key] = mcPresetCloneActions(active.actions);
  if (game === 'acciones') {
    settings.actionEvents = mcPresetCloneActions(active.actionEvents || []);
    markAccIxLiveReady();
    migrateAccionesLegacyEvents(settings);
    if (typeof migrateVideosToAcciones === 'function') migrateVideosToAcciones(settings);
  }
}

function restoreMcActionsFromActivePresetIfNeeded(game) {
  const meta = GAME_PRESET_MAP[game];
  const bank = settings.mcPresetBanks?.[game];
  if (!meta || !mcPresetHasData(bank)) return;
  if (game === 'acciones') {
    ensureAccInteractiveMeta(bank);
    // Mientras editas, la lista viva manda. Si no, el pack/General es la verdad
    // (no dejar 163 fantasmas y luego pegarlos otra vez al pack).
    if (typeof accListsWereEditedRecently === 'function' && accListsWereEditedRecently()) {
      markAccIxLiveReady();
      return;
    }
    const bag = bank.editMode === 'general'
      ? bank.general
      : ((bank.presets || []).find((p) => p && p.id === bank.activeId) || (bank.presets || [])[0]);
    if (!bag || typeof bag !== 'object') return;
    settings[meta.key] = mcPresetCloneActions(bag.actions);
    settings.actionEvents = mcPresetCloneActions(bag.actionEvents);
    markAccIxLiveReady();
    migrateAccionesLegacyEvents(settings);
    if (typeof migrateVideosToAcciones === 'function') migrateVideosToAcciones(settings);
    return;
  }
  const active = bank.presets.find((p) => p && p.id === bank.activeId) || bank.presets[0];
  if (!active) return;
  const live = Array.isArray(settings[meta.key]) ? settings[meta.key] : [];
  const saved = Array.isArray(active.actions) ? active.actions : [];
  if (!live.length && saved.length) settings[meta.key] = mcPresetCloneActions(saved);
}

/** Tras cambiar preset de Acciones: no dejar modal/selección de otro set. */
function afterAccionesPresetRuntimeChange() {
  try { accPage = 1; } catch {}
  try { accEvPage = 1; } catch {}
  try { closeAccModal(); } catch {}
  try { accSelected.clear(); updateAccSelCount(); } catch {}
  try { accEvSelected.clear(); updateAccEvSelCount(); } catch {}
  try { if (typeof accMgHydrateAllActions === 'function') accMgHydrateAllActions(settings && settings.actions); } catch {}
  try { if (typeof renderAcciones === 'function') renderAcciones(); } catch {}
  try { syncDesktopWebhookSettings(); } catch {}
}

function refreshMcPresetBar(game) {
  const prefix = gamePresetUiPrefix(game);
  const sel = document.getElementById(prefix + '-preset-select');
  const delBtn = document.getElementById(prefix + '-preset-del');
  if (!sel) return;
  let bank = settings?.mcPresetBanks?.[game];
  if (!mcPresetHasData(bank)) {
    ensureMcPresetBank(game);
    bank = settings?.mcPresetBanks?.[game];
  }
  if (!bank) return;
  const sig = String(bank.editMode || 'profile') + '\n' + bank.activeId + '\n' + bank.presets.map((p) => `${p.id}\t${p.name || 'Preset'}`).join('\n');
  const disabled = bank.presets.length <= 1;
  if (delBtn && game !== 'acciones') delBtn.disabled = disabled;
  if (sel._presetSig === sig) {
    if (sel.value !== bank.activeId) sel.value = bank.activeId;
    if (game === 'acciones') refreshAccIxPanel();
    return;
  }
  sel._presetSig = sig;
  const prev = sel.value;
  sel.innerHTML = bank.presets.map((p) => `<option value="${esc(p.id)}">${esc(p.name || 'Preset')}</option>`).join('');
  sel.value = bank.activeId || prev;
  if (game === 'acciones') {
    try { syncAccIxDropdown(); } catch {}
    refreshAccIxPanel();
  }
}

function refreshAllMcPresetBars() {
  for (const game of Object.keys(GAME_PRESET_MAP)) refreshMcPresetBar(game);
}

function loadMcPresetActions(game, presetId) {
  const bank = ensureMcPresetBank(game);
  const meta = GAME_PRESET_MAP[game];
  const prefix = gamePresetUiPrefix(game);
  const sel = document.getElementById(prefix + '-preset-select');
  if (!bank || !meta || !presetId || presetId === bank.activeId || sel?._presetLoading) return false;
  const preset = bank.presets.find((p) => p && p.id === presetId);
  if (!preset) return false;
  if (game === 'acciones') {
    ensureAccInteractiveMeta(bank);
    if (bank.editMode === 'general') {
      if (sel) sel._presetLoading = true;
      try {
        syncMcPresetFromActions(game);
        bank.activeId = presetId;
        lastGameActionEditAt = Date.now();
        scheduleRefreshMcPresetBar(game);
        saveGamePresetState(game, { sync: false, skipErSync: true });
        toast && toast('Perfil «' + (preset.name || 'Perfil') + '» listo para cuando vuelvas a Modo perfil. Ahora solo corre el general.', 'ok');
      } finally {
        if (sel) sel._presetLoading = false;
      }
      return true;
    }
  }
  if (sel) sel._presetLoading = true;
  try {
    // Guarda acciones + plantilla Editor Pro del preset que se deja.
    syncMcPresetFromActions(game);
    suppressEditorRapidoSync(2000);
    bank.activeId = presetId;
    settings[meta.key] = mcPresetCloneActions(preset.actions);
    if (game === 'acciones') {
      settings.actionEvents = mcPresetCloneActions(preset.actionEvents || []);
      markAccIxLiveReady();
      migrateAccionesLegacyEvents(settings);
      if (typeof migrateVideosToAcciones === 'function') migrateVideosToAcciones(settings);
      if (typeof accMgHydrateAllActions === 'function') accMgHydrateAllActions(settings.actions);
    }
    if (game === 'roblox') ensureRobloxSlots();
    else if (game === 'roblox3') ensureRoblox3Slots();
    lastGameActionEditAt = Date.now();
    scheduleRefreshMcPresetBar(game);
    scheduleGamePresetRender(game);
    if (game === 'acciones') {
      try { if (typeof markAllowEmptyAcciones === 'function' && !(settings.actions || []).length) markAllowEmptyAcciones(); } catch {}
    } else if (!(settings[meta.key] || []).length) {
      try { if (typeof markAllowEmptySlotLists === 'function') markAllowEmptySlotLists(); } catch {}
    }
    saveGamePresetState(game, { sync: false, skipErSync: true });
    if (game === 'acciones') afterAccionesPresetRuntimeChange();
    restoreEditorRapidoForGamePreset(game, preset);
  } finally {
    if (sel) sel._presetLoading = false;
  }
  return true;
}

function createMcPreset(game) {
  const bank = ensureMcPresetBank(game);
  const meta = GAME_PRESET_MAP[game];
  if (!bank || !meta) return;
  syncMcPresetFromActions(game);
  const n = bank.presets.length + 1;
  const id = newMcPresetId();
  const name = game === 'acciones' ? ('Perfil ' + n) : ('Preset ' + n);
  bank.presets.push({ id, name, actions: [], actionEvents: [], editorRapido: null });
  suppressEditorRapidoSync(2000);
  bank.activeId = id;
  if (game === 'acciones') {
    ensureAccInteractiveMeta(bank);
    bank.editMode = 'profile';
  }
  settings[meta.key] = [];
  if (game === 'acciones') {
    settings.actionEvents = [];
    markAccIxLiveReady();
    try { if (typeof markAllowEmptyAcciones === 'function') markAllowEmptyAcciones(); } catch {}
  } else {
    try { if (typeof markAllowEmptySlotLists === 'function') markAllowEmptySlotLists(); } catch {}
  }
  scheduleGamePresetRender(game);
  scheduleRefreshMcPresetBar(game);
  saveGamePresetState(game, { sync: false, skipErSync: true });
  if (game === 'acciones') afterAccionesPresetRuntimeChange();
  restoreEditorRapidoForGamePreset(game, bank.presets.find((p) => p && p.id === id));
  toast && toast('Creado ' + name + '.', 'ok');
}

async function deleteMcPreset(game) {
  const bank = ensureMcPresetBank(game);
  const meta = GAME_PRESET_MAP[game];
  if (!bank || !meta) return;
  if (bank.presets.length <= 1) {
    toast && toast(game === 'acciones' ? 'Debe quedar al menos un perfil.' : 'Debe quedar al menos un preset.', 'warn');
    return;
  }
  const idx = bank.presets.findIndex((p) => p && p.id === bank.activeId);
  const active = idx >= 0 ? bank.presets[idx] : bank.presets[0];
  const ok = await askConfirm({
    title: game === 'acciones' ? 'Eliminar perfil' : 'Eliminar preset',
    message: game === 'acciones'
      ? `¿Borrar «${esc(active.name || 'Perfil')}»? Sus acciones y eventos se perderán.`
      : `¿Borrar «${esc(active.name || 'Preset')}»? Sus acciones y plantilla del Editor Pro se perderán.`,
    confirmText: 'Eliminar',
  });
  if (!ok) return;
  window.__mcPresetUserDeleteConfirm = true;
  try {
    bank.presets.splice(idx >= 0 ? idx : 0, 1);
  } finally {
    window.__mcPresetUserDeleteConfirm = false;
  }
  const next = bank.presets[Math.min(idx >= 0 ? idx : 0, bank.presets.length - 1)];
  suppressEditorRapidoSync(2000);
  bank.activeId = next.id;
  settings[meta.key] = mcPresetCloneActions(next.actions);
  if (game === 'acciones') {
    settings.actionEvents = mcPresetCloneActions(next.actionEvents || []);
    migrateAccionesLegacyEvents(settings);
    try { if (typeof markAllowEmptyAcciones === 'function') markAllowEmptyAcciones(); } catch {}
  }
  scheduleGamePresetRender(game);
  scheduleRefreshMcPresetBar(game);
  saveGamePresetState(game, { sync: false, skipErSync: true, flush: true });
  if (game === 'acciones') afterAccionesPresetRuntimeChange();
  restoreEditorRapidoForGamePreset(game, next);
  toast && toast(game === 'acciones' ? 'Perfil eliminado.' : 'Preset eliminado.', 'ok');
}

function gamePresetBarInnerHtml(prefix) {
  return `
    <label class="mc-preset-lbl" for="${prefix}-preset-select">Preset</label>
    <select id="${prefix}-preset-select" class="mc-preset-select" title="Cambiar preset"></select>
    <button type="button" class="mc-img-btn mc-preset-new" id="${prefix}-preset-new" title="Crear otro preset vacío">＋ Nuevo</button>
    <button type="button" class="mc-img-btn mc-preset-del" id="${prefix}-preset-del" title="Eliminar preset actual">🗑 Borrar</button>
    <button type="button" class="mc-img-btn mc-preset-share" id="${prefix}-preset-share" title="Generar código para compartir este preset">Generar código</button>
    <button type="button" class="mc-img-btn mc-preset-import-code" id="${prefix}-preset-import-code" title="Importar preset con código de un amigo">Importar preset</button>`;
}

function ensureGamePresetBarDom(game) {
  const meta = GAME_PRESET_MAP[game];
  if (!meta) return null;
  const prefix = gamePresetUiPrefix(game);
  let sel = document.getElementById(prefix + '-preset-select');
  if (sel) return sel;
  const wrap = document.getElementById(meta.wrapId);
  if (!wrap) return null;
  const subHead = wrap.closest('.mc-actions-wrap')?.querySelector('.mc-sub-head');
  if (!subHead) return null;
  if (!subHead.querySelector('.mc-preset-bar')) {
    const bar = document.createElement('div');
    bar.className = 'mc-preset-bar';
    bar.innerHTML = gamePresetBarInnerHtml(prefix);
    const btns = subHead.querySelector('.mc-sub-btns');
    if (btns) subHead.insertBefore(bar, btns);
    else subHead.appendChild(bar);
  }
  sel = document.getElementById(prefix + '-preset-select');
  return sel;
}

const MC_PRESET_RENAME_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg>';

function ensureMcPresetRenameBtn(game, sel) {
  if (game === 'acciones') return document.getElementById('acciones-preset-rename');
  if (!sel || !sel.parentNode) return null;
  const prefix = mcPresetUiPrefix(game);
  let wrap = sel.parentElement;
  if (!wrap.classList.contains('mc-preset-select-wrap')) {
    wrap = document.createElement('div');
    wrap.className = 'mc-preset-select-wrap';
    sel.parentNode.insertBefore(wrap, sel);
    wrap.appendChild(sel);
  }
  let btn = document.getElementById(prefix + '-preset-rename');
  if (!btn) {
    btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'mc-preset-rename';
    btn.id = prefix + '-preset-rename';
    btn.title = 'Renombrar preset';
    btn.setAttribute('aria-label', 'Renombrar preset');
    btn.innerHTML = MC_PRESET_RENAME_ICON;
    wrap.appendChild(btn);
  }
  return btn;
}

function reconcileMcPresetBankOnOpen(game) {
  if (!settings || !GAME_PRESET_MAP[game] || mcPresetReconciledGames.has(game)) return;
  mcPresetReconciledGames.add(game);
  if (!settings.mcPresetBanks || typeof settings.mcPresetBanks !== 'object') settings.mcPresetBanks = {};
  const hadBank = mcPresetHasData(settings.mcPresetBanks[game]);
  const finish = () => {
    restoreMcActionsFromActivePresetIfNeeded(game);
    scheduleRefreshMcPresetBar(game);
    if (!hadBank) flushMcPresetBankMigration();
  };
  if (!hadBank) {
    runWhenIdle(() => {
      ensureMcPresetBank(game);
      finish();
    });
    return;
  }
  const bank = settings.mcPresetBanks[game];
  if (!bank.activeId || !bank.presets.some((p) => p && p.id === bank.activeId)) bank.activeId = bank.presets[0].id;
  finish();
}

const ACC_IX_CODE_PREFIX = 'LCACC1.';

function accIxB64Encode(str) {
  const bytes = new TextEncoder().encode(String(str || ''));
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/=+$/, '');
}

function accIxB64Decode(b64) {
  const raw = String(b64 || '').replace(/\s+/g, '');
  const pad = raw.length % 4 === 0 ? raw : raw + '='.repeat(4 - (raw.length % 4));
  const bin = atob(pad);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

function accIxCurrentSnapshot() {
  const bank = ensureMcPresetBank('acciones');
  if (!bank) return { name: 'Perfil', actions: [], actionEvents: [], scope: 'profile' };
  ensureAccInteractiveMeta(bank);
  syncMcPresetFromActions('acciones');
  if (bank.editMode === 'general') {
    return {
      name: 'Modo general',
      scope: 'general',
      actions: mcPresetCloneActions(bank.general.actions),
      actionEvents: mcPresetCloneActions(bank.general.actionEvents),
    };
  }
  const active = bank.presets.find((p) => p && p.id === bank.activeId) || bank.presets[0];
  return {
    name: (active && active.name) || 'Perfil',
    scope: 'profile',
    actions: mcPresetCloneActions(active && active.actions),
    actionEvents: mcPresetCloneActions(active && active.actionEvents),
  };
}

function accIxEncodeCode(snap) {
  const payload = {
    v: 1,
    kind: 'livecoins-acc-interactive',
    scope: snap.scope === 'general' ? 'general' : 'profile',
    name: snap.name || 'Perfil',
    actions: snap.actions || [],
    actionEvents: snap.actionEvents || [],
  };
  return ACC_IX_CODE_PREFIX + accIxB64Encode(JSON.stringify(payload));
}

function accIxDecodeAny(raw) {
  let s = String(raw || '').trim();
  if (!s) return null;
  if (s.startsWith(ACC_IX_CODE_PREFIX)) {
    try {
      const json = accIxB64Decode(s.slice(ACC_IX_CODE_PREFIX.length));
      return accIxNormalizeImport(JSON.parse(json));
    } catch {
      return null;
    }
  }
  if (s.charAt(0) === '{') {
    try { return accIxNormalizeImport(JSON.parse(s)); }
    catch { return null; }
  }
  return null;
}

function accIxNormalizeImport(obj) {
  if (!obj || typeof obj !== 'object') return null;
  if (Array.isArray(obj)) {
    return { name: 'Importado', scope: 'profile', actions: obj, actionEvents: [], legacyArray: true };
  }
  const src = (Array.isArray(obj.actions) || Array.isArray(obj.actionEvents) || Array.isArray(obj.acciones) || Array.isArray(obj.eventos))
    ? obj
    : ((obj.data && typeof obj.data === 'object') ? obj.data : obj);
  const actions = Array.isArray(src.actions) ? src.actions
    : (Array.isArray(src.acciones) ? src.acciones : []);
  const actionEvents = Array.isArray(src.actionEvents) ? src.actionEvents
    : (Array.isArray(src.eventos) ? src.eventos : []);
  if (!actions.length && !actionEvents.length) return null;
  const v = Number(obj.v) || 1;
  if (v > 1) {
    /* campos desconocidos se ignoran; importamos lo que conocemos */
  }
  const name = String(obj.name || obj.nombre || src.name || src.nombre || 'Importado').trim().slice(0, 80) || 'Importado';
  const scopeRaw = String(obj.scope || src.scope || '').trim().toLowerCase();
  const looksGeneral = scopeRaw === 'general'
    || /^(modo\s*)?general$/i.test(name)
    || /^modo\s*general$/i.test(name);
  return {
    name,
    scope: looksGeneral ? 'general' : 'profile',
    actions,
    actionEvents,
  };
}

function accIxCountLabel(actions, events) {
  const na = Array.isArray(actions) ? actions.length : 0;
  const ne = Array.isArray(events) ? events.length : 0;
  const a = na + (na === 1 ? ' acción' : ' acciones');
  const e = ne + (ne === 1 ? ' evento' : ' eventos');
  return a + ' · ' + e;
}

function accIxActionFingerprint(a) {
  if (!a || typeof a !== 'object') return '';
  const clips = Array.isArray(a.mediaShow?.clips) ? a.mediaShow.clips.map((c) => c && c.url).filter(Boolean).join(',') : '';
  const animClips = Array.isArray(a.animShow?.clips) ? a.animShow.clips.map((c) => c && c.url).filter(Boolean).join(',') : '';
  const cmds = Array.isArray(a.gameCmd?.cmds)
    ? a.gameCmd.cmds.map((c) => [c && c.thing, c && c.cmd, c && c.count, c && c.kind].join(':')).join(';')
    : '';
  return [
    String(a.name || '').trim().toLowerCase(),
    String(a.keys || ''),
    String(a.sound || ''),
    String(a.mediaShow?.url || ''),
    clips,
    String(a.animShow?.url || ''),
    animClips,
    String(a.gifShow?.url || ''),
    String(a.webhookCmd?.url || ''),
    String(a.obsCmd?.type || ''),
    String(a.obsCmd?.scene || ''),
    String(a.sbCmd?.action || ''),
    String(a.mcCmd?.cmd || ''),
    String(a.gameCmd?.game || ''),
    cmds,
    String(a.ttsCmd?.text || ''),
    String(a.alertText?.text || ''),
    String(a.levelUpShow?.level || ''),
  ].join('|');
}

function accIxEventFingerprint(ev, idMap) {
  if (!ev || typeof ev !== 'object') return '';
  const mapIds = (arr) => (Array.isArray(arr) ? arr : [])
    .map((id) => String(idMap && idMap.get(String(id)) || id || ''))
    .filter(Boolean)
    .sort()
    .join(',');
  return [
    String(ev.name || '').trim().toLowerCase(),
    String(ev.event || ''),
    String(ev.giftId || ''),
    String(ev.giftName || '').trim().toLowerCase(),
    String(ev.command || '').trim().toLowerCase(),
    String(ev.likeN || ev.likeMin || ''),
    String(ev.emoteId || ''),
    mapIds(ev.actionIds),
    mapIds(ev.randomActionIds),
  ].join('|');
}

/** Fusiona un export de Modo general en bank.general: ignora duplicados, agrega faltantes. */
function accIxMergeIntoGeneral(actions, events) {
  const bank = ensureMcPresetBank('acciones');
  if (!bank) return { addedActions: 0, addedEvents: 0, skippedActions: 0, skippedEvents: 0 };
  ensureAccInteractiveMeta(bank);
  syncMcPresetFromActions('acciones');

  const curActions = mcPresetCloneActions(bank.general.actions);
  const curEvents = mcPresetCloneActions(bank.general.actionEvents);
  const byFp = new Map();
  for (const a of curActions) {
    const fp = accIxActionFingerprint(a);
    if (fp && !byFp.has(fp)) byFp.set(fp, a);
  }

  const idMap = new Map();
  const toAddActions = [];
  let skippedActions = 0;
  const incoming = Array.isArray(actions) ? actions : [];
  incoming.forEach((raw, i) => {
    if (!raw || typeof raw !== 'object') return;
    const oldId = String(raw.id || '');
    const fp = accIxActionFingerprint(raw);
    const hit = fp && byFp.get(fp);
    if (hit) {
      if (oldId) idMap.set(oldId, String(hit.id));
      skippedActions += 1;
      return;
    }
    const copy = mcPresetCloneActions([raw])[0] || {};
    const newId = 'act_' + Date.now() + '_' + i + '_' + Math.random().toString(36).slice(2, 7);
    if (oldId) idMap.set(oldId, newId);
    copy.id = newId;
    delete copy.uid;
    toAddActions.push(copy);
    if (fp) byFp.set(fp, copy);
  });

  const evByFp = new Set();
  for (const ev of curEvents) {
    const fp = accIxEventFingerprint(ev, null);
    if (fp) evByFp.add(fp);
  }
  const toAddEvents = [];
  let skippedEvents = 0;
  const incomingEv = Array.isArray(events) ? events : [];
  incomingEv.forEach((raw, i) => {
    if (!raw || typeof raw !== 'object') return;
    const copy = mcPresetCloneActions([raw])[0] || {};
    copy.actionIds = (copy.actionIds || []).map((id) => idMap.get(String(id)) || id).filter(Boolean);
    copy.randomActionIds = (copy.randomActionIds || []).map((id) => idMap.get(String(id)) || id).filter(Boolean);
    const fp = accIxEventFingerprint(copy, null);
    if (fp && evByFp.has(fp)) {
      skippedEvents += 1;
      return;
    }
    copy.id = 'acev_' + Date.now() + '_' + i + '_' + Math.random().toString(36).slice(2, 7);
    toAddEvents.push(copy);
    if (fp) evByFp.add(fp);
  });

  bank.general.actions = curActions.concat(toAddActions);
  bank.general.actionEvents = curEvents.concat(toAddEvents);
  bank.editMode = 'general';
  settings.actions = mcPresetCloneActions(bank.general.actions);
  settings.actionEvents = mcPresetCloneActions(bank.general.actionEvents);
  try { migrateAccionesLegacyEvents(settings); } catch {}
  if (typeof migrateVideosToAcciones === 'function') {
    try { migrateVideosToAcciones(settings); } catch {}
  }
  lastGameActionEditAt = Date.now();
  markMcPresetDirty('acciones');
  afterAccionesPresetRuntimeChange();
  scheduleGamePresetRender('acciones');
  scheduleRefreshMcPresetBar('acciones');
  saveGamePresetState('acciones', { sync: false });
  refreshAccIxPanel();
  return {
    addedActions: toAddActions.length,
    addedEvents: toAddEvents.length,
    skippedActions,
    skippedEvents,
  };
}

function accIxApplyToLive(actions, events, { rekey = true } = {}) {
  const bag = rekey ? accIxRekeyBag(actions, events) : {
    actions: mcPresetCloneActions(actions),
    actionEvents: mcPresetCloneActions(events),
  };
  settings.actions = bag.actions;
  settings.actionEvents = bag.actionEvents;
  try { migrateAccionesLegacyEvents(settings); } catch {}
  if (typeof migrateVideosToAcciones === 'function') {
    try { migrateVideosToAcciones(settings); } catch {}
  }
  lastGameActionEditAt = Date.now();
  markMcPresetDirty('acciones');
  syncMcPresetFromActions('acciones');
  afterAccionesPresetRuntimeChange();
  scheduleGamePresetRender('acciones');
  scheduleRefreshMcPresetBar('acciones');
  saveGamePresetState('acciones', { sync: false });
}

function accIxImportAsNewPack(name, actions, events) {
  const bank = ensureMcPresetBank('acciones');
  if (!bank) return;
  ensureAccInteractiveMeta(bank);
  syncMcPresetFromActions('acciones');
  const bag = accIxRekeyBag(actions, events);
  const id = newMcPresetId();
  const packName = String(name || 'Importado').trim().slice(0, 80) || 'Importado';
  bank.presets.push({
    id,
    name: packName,
    actions: bag.actions,
    actionEvents: bag.actionEvents,
    editorRapido: null,
  });
  bank.activeId = id;
  bank.editMode = 'profile';
  accIxApplyToLive(bag.actions, bag.actionEvents, { rekey: false });
  toast && toast('Perfil «' + packName + '» importado (' + accIxCountLabel(bag.actions, bag.actionEvents) + ').', 'ok');
}

function closeAccIxDropdown() {
  const wrap = document.getElementById('acciones-preset-dd');
  const btn = document.getElementById('acciones-preset-dd-btn');
  const menu = document.getElementById('acciones-preset-dd-menu');
  if (menu) menu.hidden = true;
  if (btn) btn.setAttribute('aria-expanded', 'false');
  if (wrap) wrap.classList.remove('is-open');
}

function syncAccIxDropdown() {
  const sel = document.getElementById('acciones-preset-select');
  const menu = document.getElementById('acciones-preset-dd-menu');
  const val = document.getElementById('acciones-preset-dd-val');
  const btn = document.getElementById('acciones-preset-dd-btn');
  if (!sel) return;
  const opts = [...sel.options];
  if (menu) {
    menu.innerHTML = opts.map((o) => (
      '<button type="button" class="acc-ix-dd-opt' + (o.value === sel.value ? ' is-on' : '') + '" role="option" data-id="' + esc(o.value) + '">' + esc(o.textContent || 'Perfil') + '</button>'
    )).join('');
  }
  const cur = sel.selectedOptions && sel.selectedOptions[0];
  if (val) val.textContent = (cur && cur.textContent) || 'Perfil';
  if (btn) {
    btn.disabled = !!sel.disabled;
    btn.title = sel.title || 'Perfil Interactive';
  }
  if (sel.disabled) closeAccIxDropdown();
}

function wireAccIxDropdown() {
  const wrap = document.getElementById('acciones-preset-dd');
  const btn = document.getElementById('acciones-preset-dd-btn');
  const menu = document.getElementById('acciones-preset-dd-menu');
  const sel = document.getElementById('acciones-preset-select');
  if (!wrap || !btn || !menu || !sel || wrap._ddWired) return;
  wrap._ddWired = true;
  btn.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (sel.disabled) return;
    const open = !!menu.hidden;
    if (open) {
      wrap.classList.add('is-open');
      menu.hidden = false;
      btn.setAttribute('aria-expanded', 'true');
    } else closeAccIxDropdown();
  });
  menu.addEventListener('click', (e) => {
    const opt = e.target.closest('.acc-ix-dd-opt');
    if (!opt || sel.disabled) return;
    const id = opt.getAttribute('data-id') || '';
    if (id && sel.value !== id) {
      sel.value = id;
      sel.dispatchEvent(new Event('change', { bubbles: true }));
    }
    closeAccIxDropdown();
  });
  document.addEventListener('click', (e) => {
    if (!wrap.contains(e.target)) closeAccIxDropdown();
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeAccIxDropdown();
  });
}

function refreshAccIxPanel() {
  const panel = document.getElementById('acc-ix-panel');
  if (!panel) return;
  const bank = settings?.mcPresetBanks?.acciones;
  const mode = bank && bank.editMode === 'general' ? 'general' : 'profile';
  panel.dataset.mode = mode;
  const profileBtn = document.getElementById('acc-ix-mode-profile');
  const generalBtn = document.getElementById('acc-ix-mode-general');
  if (profileBtn) profileBtn.classList.toggle('is-on', mode === 'profile');
  if (generalBtn) generalBtn.classList.toggle('is-on', mode === 'general');
  const packLocked = mode === 'general';
  const sel = document.getElementById('acciones-preset-select');
  if (sel) sel.disabled = packLocked;
  try { syncAccIxDropdown(); } catch {}
  ['acciones-preset-new', 'acciones-preset-rename', 'acciones-preset-dup'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.disabled = packLocked;
  });
  const del = document.getElementById('acciones-preset-del');
  if (del) del.disabled = packLocked || !!(bank && bank.presets && bank.presets.length <= 1);
  const hint = document.getElementById('acc-ix-hint');
  if (hint) {
    hint.hidden = false;
    if (mode === 'general') {
      hint.textContent = 'Editando el modo general. En vivo solo corre esta bolsa; los perfiles 1, 2… no se disparan.';
    } else {
      const p = bank && bank.presets && bank.presets.find((x) => x && x.id === bank.activeId);
      hint.textContent = 'Editando el perfil «' + ((p && p.name) || 'Perfil') + '». El modo general sigue activo en vivo.';
    }
  }
}

function setAccInteractiveEditMode(mode) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const bank = ensureMcPresetBank('acciones');
  if (!bank) return;
  ensureAccInteractiveMeta(bank);
  const next = mode === 'general' ? 'general' : 'profile';
  if (bank.editMode === next) {
    refreshAccIxPanel();
    return;
  }
  // Guardar SOLO el lado que se está editando; el otro queda intacto en el bank.
  syncMcPresetFromActions('acciones');
  bank.editMode = next;
  if (next === 'general') {
    // Cargar General en el editor vivo — no copiar packs → general.
    settings.actions = mcPresetCloneActions(bank.general.actions);
    settings.actionEvents = mcPresetCloneActions(bank.general.actionEvents);
  } else {
    // Cargar pack activo — no copiar general → pack.
    const active = bank.presets.find((p) => p && p.id === bank.activeId) || bank.presets[0];
    settings.actions = mcPresetCloneActions(active && active.actions);
    settings.actionEvents = mcPresetCloneActions(active && active.actionEvents);
  }
  markAccIxLiveReady();
  try { migrateAccionesLegacyEvents(settings); } catch {}
  lastGameActionEditAt = Date.now();
  afterAccionesPresetRuntimeChange();
  scheduleGamePresetRender('acciones');
  saveGamePresetState('acciones', { sync: false });
  refreshAccIxPanel();
}

function duplicateAccInteractivePack() {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const bank = ensureMcPresetBank('acciones');
  if (!bank) return;
  ensureAccInteractiveMeta(bank);
  if (bank.editMode === 'general') {
    toast && toast('Pasa a Modo perfil para duplicar un perfil.', 'warn');
    return;
  }
  syncMcPresetFromActions('acciones');
  const src = bank.presets.find((p) => p && p.id === bank.activeId);
  if (!src) return;
  const bag = accIxRekeyBag(src.actions, src.actionEvents);
  const id = newMcPresetId();
  const name = String(src.name || 'Perfil').trim().slice(0, 68) + ' copia';
  bank.presets.push({
    id,
    name,
    actions: bag.actions,
    actionEvents: bag.actionEvents,
    editorRapido: src.editorRapido ? JSON.parse(JSON.stringify(src.editorRapido)) : null,
  });
  bank.activeId = id;
  accIxApplyToLive(bag.actions, bag.actionEvents, { rekey: false });
  toast && toast('Duplicado «' + name + '».', 'ok');
}

function accIxPayloadFromSnap(snap) {
  return {
    v: 1,
    kind: 'livecoins-acc-interactive',
    scope: snap && snap.scope === 'general' ? 'general' : 'profile',
    name: (snap && snap.name) || 'Perfil',
    actions: (snap && snap.actions) || [],
    actionEvents: (snap && snap.actionEvents) || [],
  };
}

function accIxSafeFileName(name) {
  return String(name || 'perfil').replace(/[^\w\-]+/g, '_').slice(0, 40) || 'perfil';
}

function accIxDownloadBlob(blob, filename) {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { try { URL.revokeObjectURL(a.href); a.remove(); } catch {} }, 500);
}

async function accIxPackAndDownload(payload, { emptyWarn } = {}) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const hasAcc = (payload.actions || []).length || (payload.actionEvents || []).length;
  if (emptyWarn && !hasAcc) {
    toast && toast('Este perfil no tiene acciones ni eventos para exportar.', 'warn');
    return;
  }
  const safe = accIxSafeFileName(payload.name);
  if (IS_DESKTOP) {
    try {
      const packRes = await fetch('/api/settings-transfer/pack-backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (packRes.status === 200) {
        const blob = await packRes.blob();
        if (blob && blob.size > 64) {
          accIxDownloadBlob(blob, 'livecoins-interactive-' + safe + '.zip');
          toast && toast(
            'Perfil exportado con videos (.zip) · ' + accIxCountLabel(payload.actions, payload.actionEvents)
            + ' · solo el perfil Interactive activo.',
            'ok'
          );
          return;
        }
      }
    } catch {}
  }
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  accIxDownloadBlob(blob, 'livecoins-interactive-' + safe + '.json');
  const refs = (window.SettingsTransfer && typeof window.SettingsTransfer.collectLocalMediaRefs === 'function')
    ? window.SettingsTransfer.collectLocalMediaRefs(payload)
    : { urls: [] };
  if (refs.urls && refs.urls.length && IS_DESKTOP) {
    toast && toast('JSON descargado. Los videos no están en este PC; en la otra máquina exporta de nuevo para armar el .zip.', 'warn');
  } else {
    toast && toast(
      'JSON descargado · ' + accIxCountLabel(payload.actions, payload.actionEvents)
      + ' · solo el perfil Interactive activo.',
      'ok'
    );
  }
}

async function accIxReadImportFile(file) {
  const buf = await file.arrayBuffer();
  const u8 = new Uint8Array(buf);
  const looksZip = /\.zip$/i.test(file.name || '') || (u8.length >= 2 && u8[0] === 0x50 && u8[1] === 0x4b);
  if (looksZip) {
    if (!IS_DESKTOP) return { error: 'Este .zip con videos hay que importarlo en la app de escritorio.' };
    const unpack = await fetch('/api/settings-transfer/unpack-backup?overwrite=1', {
      method: 'POST',
      headers: { 'Content-Type': 'application/zip' },
      body: buf,
    });
    const packed = await unpack.json().catch(() => ({}));
    if (!unpack.ok || !packed.backup) return { error: packed.error || 'No se pudo abrir el .zip' };
    return { backup: packed.backup, zipRestored: Number(packed.restored) || 0 };
  }
  const text = new TextDecoder().decode(u8).replace(/^\uFEFF/, '');
  const local = accIxDecodeAny(text);
  if (local) {
    return {
      backup: {
        v: 1,
        kind: 'livecoins-acc-interactive',
        scope: local.scope === 'general' ? 'general' : 'profile',
        name: local.name,
        actions: local.actions,
        actionEvents: local.actionEvents,
      },
      zipRestored: 0,
    };
  }
  try { return { backup: JSON.parse(text), zipRestored: 0 }; }
  catch { return { error: 'JSON no válido.' }; }
}

async function accIxImportFromBackup(backup, { asNewPack = false, zipRestored = 0, confirmReplace = false } = {}) {
  const local = accIxNormalizeImport(backup);
  if (!local) return { error: 'Ese archivo no trae acciones/eventos de Acciones.' };

  if (local.legacyArray) {
    toast && toast('Este JSON es antiguo (solo lista de acciones). No trae Eventos; usa Exportar Perfil reciente o créalos a mano.', 'warn');
  }

  // Export de Modo general → siempre a General (merge), nunca pack nuevo.
  if (local.scope === 'general') {
    await restoreImportedLocalMedia(backup, {
      overwrite: zipRestored > 0,
      toastMissing: !(zipRestored > 0),
    });
    const m = accIxMergeIntoGeneral(local.actions, local.actionEvents);
    const parts = [];
    if (m.addedActions) parts.push(m.addedActions + ' acción(es) nueva(s)');
    if (m.addedEvents) parts.push(m.addedEvents + ' evento(s) nuevo(s)');
    if (!parts.length) {
      toast && toast('Modo general: no había nada nuevo (ya estaban).', 'ok');
    } else {
      const skip = (m.skippedActions || m.skippedEvents)
        ? ` · ${m.skippedActions + m.skippedEvents} ya existían`
        : '';
      toast && toast('Modo general: ' + parts.join(', ') + skip + '.', 'ok');
    }
    if (zipRestored > 0) {
      toast && toast(zipRestored + ' archivo(s) de video/audio copiados a este PC.', 'ok');
    }
    return { ok: true, local, mergedGeneral: true, merge: m };
  }

  if (confirmReplace) {
    const ok = await askConfirm({
      title: 'Importar JSON',
      message: `Se reemplazarán las acciones y eventos de lo que estás editando ahora («${esc(accIxCurrentSnapshot().name)}»).`,
      confirmText: 'Reemplazar',
    });
    if (!ok) return { cancelled: true };
  }
  await restoreImportedLocalMedia(backup, {
    overwrite: zipRestored > 0 || confirmReplace,
    toastMissing: !(zipRestored > 0),
  });
  if (asNewPack) accIxImportAsNewPack(local.name, local.actions, local.actionEvents);
  else {
    accIxApplyToLive(local.actions, local.actionEvents, { rekey: true });
    toast && toast(
      'Importado en «' + accIxCurrentSnapshot().name + '» (' + accIxCountLabel(settings.actions, settings.actionEvents) + ').',
      'ok'
    );
  }
  if (zipRestored > 0) {
    toast && toast(zipRestored + ' archivo(s) de video/audio copiados a este PC.', 'ok');
  }
  return { ok: true, local };
}

function showAccIxCodeModal(code, title) {
  const back = document.createElement('div');
  back.className = 'modal confirm-modal';
  back.innerHTML = `
    <div class="confirm-box" style="max-width:480px;text-align:left">
      <div class="confirm-ico">🔗</div>
      <h3>${esc(title || 'Código de perfil')}</h3>
      <p>Copia este código e impórtalo en Acciones → Importar Perfil. Solo incluye el perfil Interactive que estás editando ahora. No incluye los archivos de video; para llevar videos a otra PC usa Exportar Perfil (.zip).</p>
      <textarea readonly class="acc-ix-code-box" style="width:100%;min-height:92px;margin:12px 0;padding:10px 12px;border-radius:10px;border:1px dashed rgba(255,255,255,.2);background:rgba(0,0,0,.35);color:inherit;font-size:12px;word-break:break-all">${esc(code)}</textarea>
      <div class="confirm-btns">
        <button type="button" class="btn ghost c-close">Cerrar</button>
        <button type="button" class="btn primary c-copy">Copiar código</button>
      </div>
    </div>`;
  document.body.appendChild(back);
  const close = () => { try { back.remove(); } catch {} };
  back.querySelector('.c-close').onclick = close;
  back.querySelector('.c-copy').onclick = async () => {
    try {
      await navigator.clipboard.writeText(code);
      toast && toast('Código copiado.', 'ok');
    } catch {
      toast && toast('Copia el texto del recuadro.', 'ok');
    }
  };
  back.addEventListener('click', (e) => { if (e.target === back) close(); });
}

function exportAccIxCode() {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const snap = accIxCurrentSnapshot();
  if (!(snap.actions || []).length && !(snap.actionEvents || []).length) {
    toast && toast('Este perfil no tiene acciones ni eventos para exportar.', 'warn');
    return;
  }
  showAccIxCodeModal(accIxEncodeCode(snap), 'Código de perfil');
}

async function exportAccIxPackFile(emptyWarn) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  await accIxPackAndDownload(accIxPayloadFromSnap(accIxCurrentSnapshot()), { emptyWarn: emptyWarn !== false });
}

function askAccIxCodeInput() {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal confirm-modal';
    back.innerHTML = `
      <div class="confirm-box" style="max-width:480px;text-align:left">
        <div class="confirm-ico">📥</div>
        <h3>Importar perfil</h3>
        <p>Pega el código <b>LCACC1…</b> o un JSON. También puedes elegir un <b>.zip</b> (con videos) o un JSON descargado.</p>
        <textarea class="acc-ix-code-inp" placeholder="LCACC1.…" style="width:100%;min-height:88px;margin:10px 0 14px;padding:10px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.15);background:rgba(0,0,0,.25);color:inherit;font-size:13px"></textarea>
        <div class="confirm-btns">
          <button type="button" class="btn ghost c-cancel">Cancelar</button>
          <button type="button" class="btn ghost c-file">Elegir .zip / .json</button>
          <button type="button" class="btn primary c-ok">Importar</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    const inp = back.querySelector('.acc-ix-code-inp');
    const close = (val) => { try { back.remove(); } catch {} resolve(val); };
    back.querySelector('.c-cancel').onclick = () => close(null);
    back.querySelector('.c-ok').onclick = () => close({ text: String(inp.value || '').trim() });
    back.querySelector('.c-file').onclick = async () => {
      const file = await accIxPickFile('.zip,.json,application/json,application/zip');
      if (!file) return;
      close({ file });
    };
    inp.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') close(null);
    });
    setTimeout(() => { try { inp.focus(); } catch {} }, 50);
    back.addEventListener('click', (e) => { if (e.target === back) close(null); });
  });
}

async function importAccIxCode() {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const picked = await askAccIxCodeInput();
  if (!picked) return;
  if (picked.file) {
    const got = await accIxReadImportFile(picked.file);
    if (got.error) { toast && toast(got.error, 'warn'); return; }
    const r = await accIxImportFromBackup(got.backup, { asNewPack: true, zipRestored: got.zipRestored });
    if (r.error) toast && toast(r.error, 'warn');
    return;
  }
  const raw = String(picked.text || '').trim();
  if (!raw) return;
  const local = accIxDecodeAny(raw);
  if (local) {
    if (local.legacyArray) {
      toast && toast('Este JSON es antiguo (solo lista de acciones). No trae Eventos; usa Exportar Perfil reciente o créalos a mano.', 'warn');
    }
    await restoreImportedLocalMedia(local, { overwrite: false, toastMissing: true });
    if (local.scope === 'general') {
      const m = accIxMergeIntoGeneral(local.actions, local.actionEvents);
      const parts = [];
      if (m.addedActions) parts.push(m.addedActions + ' acción(es) nueva(s)');
      if (m.addedEvents) parts.push(m.addedEvents + ' evento(s) nuevo(s)');
      toast && toast(parts.length
        ? ('Modo general: ' + parts.join(', ') + '.')
        : 'Modo general: no había nada nuevo (ya estaban).', 'ok');
      return;
    }
    accIxImportAsNewPack(local.name, local.actions, local.actionEvents);
    return;
  }
  const code = normalizeMcPresetShareCodeClient(raw);
  if (code) {
    await importMcPresetFromShareCode('acciones', raw);
    return;
  }
  toast && toast('Código no válido. Usa LCACC1…, JSON, .zip o MC-XXXXXX.', 'warn');
}

async function exportAccIxJson() {
  await exportAccIxPackFile(false);
}

function accIxPickFile(accept) {
  return new Promise((resolve) => {
    const inp = document.createElement('input');
    inp.type = 'file';
    inp.accept = accept || '*';
    inp.style.display = 'none';
    let finished = false;
    const done = (file) => {
      if (finished) return;
      finished = true;
      try { inp.remove(); } catch {}
      resolve(file || null);
    };
    inp.onchange = () => done(inp.files && inp.files[0]);
    inp.addEventListener('cancel', () => done(null));
    document.body.appendChild(inp);
    inp.click();
  });
}

async function importAccIxJsonFile() {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const file = await accIxPickFile('.zip,.json,application/json,application/zip');
  if (!file) return;
  const got = await accIxReadImportFile(file);
  if (got.error) { toast && toast(got.error, 'warn'); return; }
  const r = await accIxImportFromBackup(got.backup, {
    asNewPack: false,
    zipRestored: got.zipRestored,
    confirmReplace: true,
  });
  if (r.error) toast && toast(r.error, 'warn');
}

function accIxExtractFromTikfinityRaw(raw) {
  if (!raw || typeof raw !== 'object') return null;
  if (window.SettingsTransfer) {
    try {
      const result = window.SettingsTransfer.parseFile(JSON.stringify(raw));
      const patch = (result && result.patch) || {};
      const actions = Array.isArray(patch.actions) ? patch.actions : [];
      const actionEvents = Array.isArray(patch.actionEvents) ? patch.actionEvents : [];
      if (actions.length || actionEvents.length) {
        return { name: 'TikFinity', actions, actionEvents };
      }
    } catch {}
    try {
      const result = window.SettingsTransfer.convertLegacy(raw, { includeActions: true });
      const patch = (result && result.patch) || {};
      const actions = Array.isArray(patch.actions) ? patch.actions : [];
      const actionEvents = Array.isArray(patch.actionEvents) ? patch.actionEvents : [];
      if (actions.length || actionEvents.length) {
        return { name: 'TikFinity', actions, actionEvents };
      }
    } catch {}
  }
  return accIxNormalizeImport(raw);
}

async function importAccIxTfcFile() {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const file = await accIxPickFile('.tfc,.json,.txt,application/json,text/plain');
  if (!file) return;
  const text = String(await file.text() || '').replace(/^\uFEFF/, '');
  const head = text.trim().slice(0, 16);
  let raw = null;
  if (head.startsWith('U2FsdGVk')) {
    const ans = await askTikfinityPointsImport({
      title: 'Importar TFC a este perfil',
      needPassword: true,
      reason: 'El .tfc está cifrado. Solo se importan acciones/eventos a Interactive, no a los Perfiles de la app.',
    });
    if (!ans) return;
    toast && toast('Descifrando .tfc…', 'ok');
    const dec = await requestTikfinityDecrypt({
      ciphertext: text,
      channelId: ans.channelId,
      password: ans.password,
    });
    if (!dec || !dec.ok || !dec.data) {
      toast && toast((dec && dec.error) || 'No se pudo descifrar el .tfc', 'warn');
      return;
    }
    raw = dec.data;
  } else {
    try { raw = JSON.parse(text); }
    catch { toast && toast('No se pudo leer el archivo TFC/JSON.', 'warn'); return; }
  }
  const local = accIxExtractFromTikfinityRaw(raw);
  if (!local) {
    toast && toast('Ese TFC no trae acciones reconocibles.', 'warn');
    return;
  }
  const ok = await askConfirm({
    title: 'Importar TFC',
    message: `Se reemplazarán las acciones de «${esc(accIxCurrentSnapshot().name)}» con las del TFC. No cambia los Perfiles de la app.`,
    confirmText: 'Importar aquí',
  });
  if (!ok) return;
  accIxApplyToLive(local.actions, local.actionEvents, { rekey: true });
  toast && toast('TFC importado en Interactive.', 'ok');
}

function wireAccInteractivePanel() {
  const panel = document.getElementById('acc-ix-panel');
  if (!panel) return;
  if (!panel._ixWired) {
    panel._ixWired = true;
    document.getElementById('acc-ix-mode-profile')?.addEventListener('click', () => setAccInteractiveEditMode('profile'));
    document.getElementById('acc-ix-mode-general')?.addEventListener('click', () => setAccInteractiveEditMode('general'));
    document.getElementById('acciones-preset-dup')?.addEventListener('click', () => duplicateAccInteractivePack());
    document.getElementById('acciones-preset-share')?.addEventListener('click', () => exportAccIxPackFile(true));
    document.getElementById('acciones-preset-import-code')?.addEventListener('click', () => importAccIxCode());
    document.getElementById('acciones-preset-code')?.addEventListener('click', () => exportAccIxCode());
    document.getElementById('acciones-preset-export-json')?.addEventListener('click', () => exportAccIxJson());
    document.getElementById('acciones-preset-import-json')?.addEventListener('click', () => importAccIxJsonFile());
    document.getElementById('acciones-preset-import-tfc')?.addEventListener('click', () => importAccIxTfcFile());
    try { wireAccIxDropdown(); } catch {}
  }
  scheduleRefreshMcPresetBar('acciones');
}

function wireMcPresetBar(game) {
  if (_gamePresetBarReady.has(game)) {
    scheduleRefreshMcPresetBar(game);
    return;
  }
  ensureGamePresetBarDom(game);
  const prefix = gamePresetUiPrefix(game);
  const sel = document.getElementById(prefix + '-preset-select');
  const newBtn = document.getElementById(prefix + '-preset-new');
  const delBtn = document.getElementById(prefix + '-preset-del');
  const shareBtn = document.getElementById(prefix + '-preset-share');
  const importBtn = document.getElementById(prefix + '-preset-import-code');
  if (!sel) return;
  reconcileMcPresetBankOnOpen(game);
  const renameBtn = ensureMcPresetRenameBtn(game, sel);
  if (!sel._wired) {
    sel._wired = true;
    sel.title = 'Cambiar preset · lápiz para renombrar';
    sel.onchange = () => {
      const id = sel.value;
      const bank = ensureMcPresetBank(game);
      if (!id || !bank || id === bank.activeId) return;
      loadMcPresetActions(game, id);
    };
  }
  if (renameBtn && !renameBtn._wired) {
    renameBtn._wired = true;
    renameBtn.onclick = () => renameMcPreset(game);
  }
  if (newBtn && !newBtn._wired) {
    newBtn._wired = true;
    newBtn.onclick = () => {
      if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
      createMcPreset(game);
    };
  }
  if (delBtn && !delBtn._wired) {
    delBtn._wired = true;
    delBtn.onclick = () => deleteMcPreset(game);
  }
  if (shareBtn && !shareBtn._wired && game !== 'acciones') {
    shareBtn._wired = true;
    shareBtn.onclick = () => shareMcPresetCode(game);
  }
  if (importBtn && !importBtn._wired && game !== 'acciones') {
    importBtn._wired = true;
    importBtn.onclick = () => importMcPresetFromShareCode(game);
  }
  _gamePresetBarReady.add(game);
}

function wireGamePresetBar(game) {
  wireMcPresetBar(game);
}

const ACC_IX_EVENTS_SHARE_MARKER = '__lc_ix_events_v1__';

function mcPresetEmbedAccIxEvents(actions, actionEvents) {
  const list = mcPresetCloneActions(actions);
  const evs = mcPresetCloneActions(actionEvents);
  if (!evs.length) return list;
  list.push({
    id: ACC_IX_EVENTS_SHARE_MARKER,
    name: ACC_IX_EVENTS_SHARE_MARKER,
    event: 'none',
    enabled: false,
    __lcIxActionEvents: evs,
  });
  return list;
}

function mcPresetExtractAccIxEvents(actions, actionEventsFromApi) {
  if (Array.isArray(actionEventsFromApi) && actionEventsFromApi.length) {
    return {
      actions: (actions || []).filter((a) => a && a.id !== ACC_IX_EVENTS_SHARE_MARKER && !a.__lcIxActionEvents),
      actionEvents: mcPresetCloneActions(actionEventsFromApi),
    };
  }
  const clean = [];
  let embedded = [];
  for (const a of (actions || [])) {
    if (!a || typeof a !== 'object') continue;
    if (a.id === ACC_IX_EVENTS_SHARE_MARKER || Array.isArray(a.__lcIxActionEvents)) {
      if (Array.isArray(a.__lcIxActionEvents) && a.__lcIxActionEvents.length) {
        embedded = a.__lcIxActionEvents;
      }
      continue;
    }
    clean.push(a);
  }
  return { actions: clean, actionEvents: mcPresetCloneActions(embedded) };
}

function mcPresetActiveSharePayload(game) {
  const bank = ensureMcPresetBank(game);
  const meta = GAME_PRESET_MAP[game];
  if (!bank || !meta) return null;
  syncMcPresetFromActions(game);
  const active = bank.presets.find((p) => p && p.id === bank.activeId);
  let actions = mcPresetCloneActions(normalizeGamePresetLiveActions(game));
  if (!actions.length) return null;
  const payload = {
    game,
    presetName: active?.name || 'Preset',
    actions,
  };
  if (game === 'acciones') {
    if (bank.editMode === 'general') {
      payload.presetName = 'Modo general';
      payload.actionEvents = mcPresetCloneActions(bank.general?.actionEvents || settings.actionEvents || []);
    } else {
      payload.actionEvents = mcPresetCloneActions(
        (active && active.actionEvents) || settings.actionEvents || []
      );
    }
    // Respaldo: nube vieja solo guarda `actions`; embebe eventos en un stub.
    payload.actions = mcPresetEmbedAccIxEvents(payload.actions, payload.actionEvents);
  }
  return payload;
}

function showMcPresetShareCodeModal(data) {
  const exp = data.expiresAt ? new Date(data.expiresAt).toLocaleDateString() : '30 días';
  const evPart = (data.game === 'acciones' || Number(data.eventCount) > 0)
    ? ` · ${esc(data.eventCount || 0)} evento${Number(data.eventCount) === 1 ? '' : 's'}`
    : '';
  const back = document.createElement('div');
  back.className = 'modal confirm-modal';
  back.innerHTML = `
    <div class="confirm-box" style="max-width:420px">
      <div class="confirm-ico">🔗</div>
      <h3>Código de preset</h3>
      <p>Comparte este código con tu amigo. Válido hasta <b>${esc(exp)}</b>.</p>
      <div class="mc-preset-code-box" style="font-size:22px;font-weight:800;letter-spacing:.12em;text-align:center;padding:14px 10px;margin:12px 0;border-radius:10px;background:rgba(0,0,0,.35);border:1px dashed rgba(255,255,255,.2)">${esc(data.code)}</div>
      <p style="font-size:12px;opacity:.75">${esc(data.actionCount || 0)} acciones${evPart} · ${esc(data.name || 'Preset')}</p>
      <div class="confirm-btns">
        <button type="button" class="btn ghost c-close">Cerrar</button>
        <button type="button" class="btn primary c-copy">Copiar código</button>
      </div>
    </div>`;
  document.body.appendChild(back);
  const close = () => { try { back.remove(); } catch {} };
  back.querySelector('.c-close').onclick = close;
  back.querySelector('.c-copy').onclick = async () => {
    try {
      await navigator.clipboard.writeText(data.code);
      toast && toast('Código copiado.', 'ok');
    } catch {
      toast && toast('Copia manual: ' + data.code, 'ok');
    }
  };
  back.addEventListener('click', (e) => { if (e.target === back) close(); });
}

function askMcPresetRenameInput(current) {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal confirm-modal';
    back.innerHTML = `
      <div class="confirm-box" style="max-width:420px;text-align:left">
        <div class="confirm-ico">✏️</div>
        <h3>Renombrar preset</h3>
        <p>Nombre del preset actual.</p>
        <input type="text" class="mc-preset-rename-inp" maxlength="80" style="width:100%;margin:10px 0 14px;padding:10px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.15);background:rgba(0,0,0,.25);color:inherit;font-size:15px">
        <div class="confirm-btns">
          <button type="button" class="btn ghost c-cancel">Cancelar</button>
          <button type="button" class="btn primary c-ok">Guardar</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    const inp = back.querySelector('.mc-preset-rename-inp');
    inp.value = String(current || '').slice(0, 80);
    const close = (val) => { try { back.remove(); } catch {} resolve(val); };
    back.querySelector('.c-cancel').onclick = () => close(null);
    back.querySelector('.c-ok').onclick = () => close(String(inp.value || '').trim());
    inp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); close(String(inp.value || '').trim()); }
      if (e.key === 'Escape') close(null);
    });
    setTimeout(() => { try { inp.focus(); inp.select(); } catch {} }, 50);
    back.addEventListener('click', (e) => { if (e.target === back) close(null); });
  });
}

async function renameMcPreset(game) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const bank = ensureMcPresetBank(game);
  if (!bank) return;
  const active = bank.presets.find((p) => p && p.id === bank.activeId);
  if (!active) return;
  const name = await askMcPresetRenameInput(active.name || 'Preset');
  if (!name) return;
  active.name = name.slice(0, 80);
  scheduleRefreshMcPresetBar(game);
  try { saveSettingsKeysPatch('mcPresetBanks'); } catch {}
  toast && toast('Nombre actualizado.', 'ok');
}

