async function shareMcPresetCode(game) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const payload = mcPresetActiveSharePayload(game);
  if (!payload) { toast && toast('No hay acciones en este preset para compartir.', 'warn'); return; }
  try {
    const r = await fetch('/api/mc-preset-share', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify(payload),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok || !data.ok || !data.code) {
      toast && toast(data.error || 'No se pudo generar el código.', 'warn');
      return;
    }
    if (game === 'acciones' && (payload.actionEvents || []).length && !(Number(data.eventCount) > 0)) {
      // Nube vieja: los eventos van embebidos en actions; el modal no muestra eventCount.
      // No spamear warn: el import los recupera con mcPresetExtractAccIxEvents.
    }
    showMcPresetShareCodeModal({
      ...data,
      game: data.game || game,
      actionCount: (payload.actions || []).filter((a) => a && a.id !== ACC_IX_EVENTS_SHARE_MARKER).length
        || Number(data.actionCount) || 0,
      eventCount: Number(data.eventCount) > 0
        ? data.eventCount
        : ((payload.actionEvents || []).length || 0),
    });
  } catch {
    toast && toast('Sin conexión. Revisa internet.', 'warn');
  }
}

async function importMcPresetFromShareCode(game, rawCode) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const raw = rawCode != null ? String(rawCode).trim() : await askMcPresetShareCodeInput();
  if (!raw) return;
  const code = normalizeMcPresetShareCodeClient(raw);
  if (!code) { toast && toast('Código no válido. Usa el formato MC-XXXXXX.', 'warn'); return; }
  try {
    const r = await fetch('/api/mc-preset-share/' + encodeURIComponent(code), { credentials: 'same-origin' });
    const data = await r.json().catch(() => ({}));
    if (!r.ok || !data.ok || !Array.isArray(data.actions) || !data.actions.length) {
      toast && toast(data.error || 'Código no encontrado.', 'warn');
      return;
    }
    const meta = GAME_PRESET_MAP[game];
    if (!meta) return;
    if (data.game && data.game !== game) {
      const src = (GAME_PRESET_MAP[data.game] || {}).label || data.game;
      const ok = await askConfirm({
        title: 'Juego distinto',
        message: `El código es de <b>${esc(src)}</b>. ¿Importarlo aquí en <b>${esc(meta.label)}</b>?`,
        confirmText: 'Importar igual',
        danger: false,
        icon: '📥',
      });
      if (!ok) return;
    }
    if (game === 'acciones') {
      const sample = data.actions.find((a) => a && typeof a === 'object'
        && a.id !== ACC_IX_EVENTS_SHARE_MARKER && !a.__lcIxActionEvents);
      const looksGame = !!(sample && (sample.thing || sample.cmd || sample.cmds || (sample.uid && !sample.event && !sample.keys)));
      if (looksGame) {
        toast && toast('Ese código es de un juego, no de Acciones (teclas).', 'warn');
        return;
      }
    }
    syncMcPresetFromActions(game);
    const bank = ensureMcPresetBank(game);
    let clean;
    let importedEvents = [];
    if (game === 'acciones') {
      const extracted = mcPresetExtractAccIxEvents(data.actions, data.actionEvents);
      const bag = accIxRekeyBag(extracted.actions, extracted.actionEvents);
      clean = bag.actions;
      importedEvents = bag.actionEvents;
    } else {
      clean = data.actions
        .filter((a) => a && typeof a === 'object')
        .filter((a) => a.id !== ACC_IX_EVENTS_SHARE_MARKER && !a.__lcIxActionEvents)
        .map((a, i) => {
          const copy = { ...a };
          copy.uid = 'mca_' + Date.now() + '_' + i + '_' + Math.random().toString(36).slice(2, 7);
          return copy;
        });
    }
    const id = newMcPresetId();
    const name = String(data.name || 'Importado').trim().slice(0, 80) || 'Importado';
    bank.presets.push({
      id,
      name,
      actions: mcPresetCloneActions(clean),
      actionEvents: game === 'acciones' ? mcPresetCloneActions(importedEvents) : [],
    });
    bank.activeId = id;
    if (game === 'acciones') {
      ensureAccInteractiveMeta(bank);
      bank.editMode = 'profile';
      settings.actionEvents = mcPresetCloneActions(importedEvents);
    }
    settings[meta.key] = mcPresetCloneActions(clean);
    if (MC_GAME_MAP[game]) repairMcImportedCmds(settings[meta.key]);
    if (game === 'roblox') ensureRobloxSlots();
    else if (game === 'roblox3') ensureRoblox3Slots();
    lastGameActionEditAt = Date.now();
    if (game === 'acciones') {
      try { migrateAccionesLegacyEvents(settings); } catch {}
      // Si el código era viejo (sin actionEvents), la migración puede haber creado eventos.
      importedEvents = Array.isArray(settings.actionEvents) ? settings.actionEvents : importedEvents;
      const pack = bank.presets.find((p) => p && p.id === id);
      if (pack) pack.actionEvents = mcPresetCloneActions(importedEvents);
    }
    scheduleGamePresetRender(game);
    scheduleRefreshMcPresetBar(game);
    saveGamePresetState(game, { sync: false });
    if (game === 'acciones') afterAccionesPresetRuntimeChange();
    toast && toast(
      game === 'acciones'
        ? (`Importado «${name}» (${accIxCountLabel(clean, importedEvents)}).`)
        : (`Importado «${name}» (${clean.length} acciones).`),
      'ok'
    );
    if (game === 'acciones' && !(importedEvents || []).length) {
      const hadApiEvents = Array.isArray(data.actionEvents) && data.actionEvents.length;
      const hadEmbed = Array.isArray(data.actions) && data.actions.some((a) => a && (a.id === ACC_IX_EVENTS_SHARE_MARKER || a.__lcIxActionEvents));
      if (!hadApiEvents && !hadEmbed) {
        toast && toast('Este código no traía Eventos (código antiguo o sin eventos). Genera uno nuevo tras actualizar.', 'warn');
      }
    }
  } catch {
    toast && toast('Sin conexión. Revisa internet.', 'warn');
  }
}

function reconcileMcPresetBanks(touchedKeys) {
  if (!settings) return;
  if (!settings.mcPresetBanks || typeof settings.mcPresetBanks !== 'object') settings.mcPresetBanks = {};
  const full = !touchedKeys || !touchedKeys.length;
  const accHold = typeof accListsWereEditedRecently === 'function' && accListsWereEditedRecently();
  if (full) {
    const recentEdit = Date.now() - lastGameActionEditAt <= GAME_ACTION_EDIT_ECHO_MS;
    if (!recentEdit) {
      for (const game of Object.keys(GAME_PRESET_MAP)) {
        if (game === 'acciones' && accHold) continue;
        if (!mcPresetHasData(settings.mcPresetBanks[game])) continue;
        restoreMcActionsFromActivePresetIfNeeded(game);
      }
    }
    return;
  }
  const recentEdit = Date.now() - lastGameActionEditAt <= GAME_ACTION_EDIT_ECHO_MS;
  let migrated = false;
  let accionesSynced = false;
  for (const game of Object.keys(GAME_PRESET_MAP)) {
    const meta = GAME_PRESET_MAP[game];
    if (!touchedKeys.includes(meta.key) && !touchedKeys.includes('mcPresetBanks')) continue;
    if (game === 'acciones' && accHold) continue;
    const hadBank = mcPresetHasData(settings.mcPresetBanks?.[game]);
    ensureMcPresetBank(game);
    if (!hadBank) migrated = true;
    else if (!recentEdit) {
      restoreMcActionsFromActivePresetIfNeeded(game);
      // Si llegó un patch de la lista viva, alinear el preset activo (evita banco viejo).
      if (touchedKeys.includes(meta.key)) {
        syncMcPresetFromActions(game);
        if (game === 'acciones') accionesSynced = true;
      }
    }
    if (document.getElementById(gamePresetUiPrefix(game) + '-preset-select')) scheduleRefreshMcPresetBar(game);
  }
  if (migrated || accionesSynced) flushMcPresetBankMigration();
}

function mcFamilyGameByKey(settingsKey) {
  return Object.entries(MC_GAME_MAP).find(([, g]) => g.key === settingsKey)?.[0] || 'minecraft';
}

function findMcFamilyAction(uid) {
  if (!uid || !settings) return null;
  for (const [game, g] of Object.entries(MC_GAME_MAP)) {
    const list = settings[g.key];
    if (!Array.isArray(list)) continue;
    const action = list.find((x) => x.uid === uid);
    if (action) return { action, game, key: g.key, render: g.render };
  }
  return null;
}

function mcFamilyThumbHtml(a, game) {
  if (game === 'mcfarm' && !a.image) return farmIconHtml(a.catId, 'mc-act-ic');
  if (game === 'mcshooter') return mcShooterActionIconHtml(a);
  if (a.image) return `<img class="mc-act-ic" src="${esc(a.image)}" alt="" onerror="this.style.display='none'">`;
  const dirs = {
    minecraft: '/img/minecraft/',
    bedrock: '/img/bedrock/',
    sandbox: '/img/sandbox/',
    mcparkour: '/img/parkour/',
    mconeblock: '/img/oneblock/',
    mcparadise: '/img/mcparadise/',
    mcsandwall: '/img/sandwall/',
    mckoth: '/img/koth/',
    mcfarm: '/img/farm/',
    mcshooter: '/img/mcshooter/',
  };
  const q = game === 'mcsandwall' ? '?v=sw6' : (String(a.catId || '').startsWith('ao_') ? '?v=ao1' : '');
  return `<img class="mc-act-ic" src="${(dirs[game] || '/img/minecraft/') + esc(a.catId || '')}.png${q}" alt="" onerror="this.style.display='none'">`;
}

function bindMcFamilyAudio(wrap, find, rerender) {
  const openLib = (uid) => {
    mcSoundPickUid = uid;
    soundPickTarget = 'mc';
    openSoundLib();
  };
  wrap.querySelectorAll('.mc-audio-add').forEach((b) => b.onclick = () => openLib(b.dataset.uid));
  wrap.querySelectorAll('.mc-audio-file').forEach((b) => b.onclick = () => openLib(b.dataset.uid));
  wrap.querySelectorAll('.mc-audio-clear').forEach((b) => b.onclick = (e) => {
    e.stopPropagation();
    const a = find(b.dataset.uid); if (!a) return;
    a.sound = '';
    a.soundName = '';
    a.audioOn = false;
    a.soundRestart = false;
    flushSaveSettings();
    rerender();
  });
  wrap.querySelectorAll('.mc-audio-restart-en').forEach((c) => {
    c.onchange = () => {
      const a = find(c.dataset.uid); if (!a) return;
      a.soundRestart = !!c.checked;
      c.closest('.mc-audio-restart')?.classList.toggle('is-on', !!c.checked);
      flushSaveSettings();
    };
  });
  wrap.querySelectorAll('.mc-audio-test-n').forEach((inp) => {
    const saveN = () => {
      const a = find(inp.dataset.uid); if (!a) return;
      a.soundTestN = Math.max(1, Math.min(100, parseInt(inp.value, 10) || 100));
      inp.value = String(a.soundTestN);
    };
    inp.addEventListener('change', () => { saveN(); flushSaveSettings(); });
    inp.addEventListener('pointerdown', (e) => e.stopPropagation());
  });
  wrap.querySelectorAll('.mc-audio-test').forEach((b) => {
    b.onclick = (e) => {
      e.stopPropagation();
      const a = find(b.dataset.uid); if (!a) return;
      const row = b.closest('.mc-audio-testbar');
      const nInp = row?.querySelector('.mc-audio-test-n');
      const n = Math.max(1, Math.min(100, parseInt(nInp?.value, 10) || a.soundTestN || 100));
      a.soundTestN = n;
      if (nInp) nInp.value = String(n);
      testGameActionAudio(a, n);
    };
  });
  wrap.querySelectorAll('.mc-audio-vol').forEach((inp) => {
    const setVolUi = () => {
      const a = find(inp.dataset.uid); if (!a) return;
      const v = Math.max(0, Math.min(100, Number(inp.value) || 0));
      a.soundVolume = v;
      const val = inp.closest('.mc-act-card')?.querySelector('.mc-audio-vol-val');
      if (val) val.textContent = `${v}%`;
    };
    inp.addEventListener('pointerdown', (e) => {
      e.stopPropagation();
      window._mcVolDrag = true;
    });
    const endDrag = () => {
      if (!window._mcVolDrag) return;
      window._mcVolDrag = false;
      setVolUi();
      saveSettings();
    };
    inp.addEventListener('pointerup', endDrag);
    inp.addEventListener('pointercancel', endDrag);
    inp.addEventListener('change', endDrag);
    inp.oninput = () => { setVolUi(); };
  });
}

function renderMcFamilyActions(game) {
  if (window._mcVolDrag) return;
  const meta = MC_GAME_MAP[game];
  if (!meta) return;
  const wrap = document.getElementById(meta.wrapId);
  if (!wrap) return;
  const key = meta.key;
  const list = (settings && Array.isArray(settings[key])) ? settings[key] : [];
  if (!list.length) {
    wrap.innerHTML = '<div class="mc-empty">Aún no agregaste acciones. Elige una del catálogo de abajo.</div>';
    prepareGameActionsView(wrap);
    return;
  }
  wrap.innerHTML = list.map((a) => {
    const audioBlock = gameSurvivalAudioHtml(a);
    const cmdCount = a.custom
      ? (Array.isArray(a.cmds) ? a.cmds.filter((c) => (typeof c === 'string' ? c : c?.cmd || c?.text || '').trim()).length : (a.cmd ? 1 : 0))
      : (a.cmd ? 1 : 0);
    const cmdPreview = a.custom
      ? String((Array.isArray(a.cmds) && a.cmds[0] && (typeof a.cmds[0] === 'string' ? a.cmds[0] : (a.cmds[0].cmd || a.cmds[0].text || ''))) || a.cmd || '')
      : String(a.cmd || '');
    const rep = Math.max(1, parseInt(a.repeat, 10) || 1);
    const delayEach = Math.max(0, parseInt(a.delayEach, 10) || 0);
    const delayGroup = Math.max(0, parseInt(a.delayGroup ?? a.delayBefore, 10) || 0);
    const metaChips = a.custom ? `
      <div class="mc-act-meta">
        <span>Repetición: <b>${rep}</b></span>
        <span>Intervalo: <b>${delayEach}</b></span>
        <span>Retraso: <b>${delayGroup}</b></span>
        <span>Comandos: <b>${cmdCount}</b></span>
      </div>
      ${cmdPreview ? `<div class="mc-act-cmdprev" title="${esc(cmdPreview)}">${esc(cmdPreview)}</div>` : ''}` : `
      <div class="mc-act-meta">${a.desc ? `<span class="mc-act-desc-inline">${esc(a.desc)}</span>` : ''}</div>`;
    return `
    <div class="mc-act-card mc-act-row ${a.enabled === false ? 'mc-off' : ''}" data-uid="${esc(a.uid)}">
      ${gameActDragHtml(a)}
      <div class="mc-act-col mc-act-col-trig">
        ${mcTrigCardBtnHtml(a)}
      </div>
      <div class="mc-act-col mc-act-col-thumb" aria-hidden="true">
        ${mcFamilyThumbHtml(a, game)}
      </div>
      <div class="mc-act-col mc-act-col-info">
        <div class="mc-act-name">${esc(a.name)}</div>
        ${metaChips}
        ${mcCardQtyHtml(a)}
        ${mcCardComboInstantHtml(a)}
      </div>
      <div class="mc-act-col mc-act-col-audio">
        ${audioBlock}
      </div>
      <div class="mc-act-col mc-act-col-actions">
        <label class="mc-act-toggle"><input type="checkbox" class="mc-act-en" data-uid="${esc(a.uid)}" ${a.enabled === false ? '' : 'checked'}> Activa</label>
        <div class="mc-act-btns">
          ${a.custom ? `<button type="button" class="mc-act-edit acc-icon-btn" data-uid="${esc(a.uid)}" title="Editar">${CARD_ICON.gear}</button>` : ''}
          <button type="button" class="mc-act-test-delay acc-icon-btn" data-uid="${esc(a.uid)}" title="Probar en 4 s">${CARD_ICON.play}</button>
          <button type="button" class="mc-act-test acc-icon-btn acc-try-instant" data-uid="${esc(a.uid)}" title="Probar ya">${CARD_ICON.play}</button>
          <button type="button" class="mc-act-dup acc-icon-btn acc-dup" data-uid="${esc(a.uid)}" title="Duplicar acción">${CARD_ICON.dup}</button>
          <button type="button" class="mc-act-del acc-icon-btn acc-del-one" data-uid="${esc(a.uid)}" title="Quitar">${CARD_ICON.trash}</button>
        </div>
      </div>
    </div>`;
  }).join('');

  const find = (uid) => (settings[key] || []).find((x) => x.uid === uid);
  const rerender = () => meta.render();
  wrap.querySelectorAll('.mc-act-dup').forEach((b) => b.onclick = () => {
    if (!b.dataset.uid) return;
    duplicateGameActionBelow(key, b.dataset.uid, rerender);
  });
  wrap.querySelectorAll('.mc-act-del').forEach((b) => b.onclick = () => {
    settings[key] = (settings[key] || []).filter((x) => x.uid !== b.dataset.uid);
    markMcPresetDirty(game);
    try { if (typeof markAllowEmptySlotLists === 'function') markAllowEmptySlotLists(); } catch {}
    saveSettings(); rerender();
  });
  wrap.querySelectorAll('.mc-trig-icon-btn').forEach((b) => b.onclick = () => openMcTrigPop(b.dataset.uid, key));
  wrap.querySelectorAll('.mc-act-en').forEach((c) => c.onchange = () => {
    const a = find(c.dataset.uid); if (!a) return;
    a.enabled = c.checked;
    lastGameActionEditAt = Date.now();
    if (!c.checked) {
      const n = disableMatchingGameActions(key, a);
      if (n > 0 && typeof toast === 'function') {
        toast('Apagadas también ' + n + ' copia(s) igual(es) (evita spawn fantasma).', 'ok');
      }
    }
    saveSettingsKeysPatch(key, { skipErSync: true, flush: !c.checked }); rerender();
  });
  wrap.querySelectorAll('.mc-qty-n').forEach((inp) => inp.onchange = () => {
    const a = find(inp.dataset.uid); if (!a) return;
    a.count = Math.max(1, parseInt(inp.value, 10) || 1);
    inp.value = String(a.count);
    markMcPresetDirty(game);
    saveSettings();
    notifyEditorRapidoActionsChanged(key);
  });
  wrap.querySelectorAll('.mc-act-edit').forEach((b) => b.onclick = () => {
    const a = find(b.dataset.uid); if (a) openMcCmdModal(a, game === 'minecraft' ? undefined : game);
  });
  wrap.querySelectorAll('.mc-act-test-delay').forEach((b) => b.onclick = () => {
    const uid = b.dataset.uid;
    toast && toast('La acción se ejecutará en 4 segundos…', 'ok');
    setTimeout(() => sendTestMcAction(uid), 4000);
  });
  wrap.querySelectorAll('.mc-act-test').forEach((b) => b.onclick = () => sendTestMcAction(b.dataset.uid));
  bindMcFamilyAudio(wrap, find, rerender);
  bindMcActionCardCommon(wrap, find, rerender);
  prepareGameActionsView(wrap);
}

let mccEditingUid = null;
let mccGame = 'minecraft'; // a qué pestaña pertenece el comando que se edita/crea
const MCC_MAX_CMDS = 15;

function updateMccCmdCount(n) {
  const el = document.getElementById('mcc-cmd-count');
  if (el) el.textContent = `${Math.min(MCC_MAX_CMDS, n || 0)}/${MCC_MAX_CMDS}`;
}
function openMccVarsPop() {
  const o = document.getElementById('mcc-vars-overlay');
  if (o) { o.classList.remove('hidden'); o.setAttribute('aria-hidden', 'false'); }
}
function closeMccVarsPop() {
  const o = document.getElementById('mcc-vars-overlay');
  if (o) { o.classList.add('hidden'); o.setAttribute('aria-hidden', 'true'); }
}
function openMcCmdModal(a, game) {
  wireMcCmdModalOnce();
  closeMccVarsPop();
  closeMccGalleryPicker();
  mccGame = game || (a && a.game) || 'minecraft';
  mccEditingUid = a && a.uid ? a.uid : null;
  const gameLabel = (MC_GAME_MAP[mccGame] || MC_GAME_MAP.minecraft).label;
  document.getElementById('mcc-title').textContent = a ? 'Editar comando personalizado' : ('Comando personalizado de ' + gameLabel);
  document.getElementById('mcc-name').value = a?.name || '';
  document.getElementById('mcc-desc').value = a?.desc || '';
  document.getElementById('mcc-repeat').value = a?.repeat != null ? a.repeat : 1;
  document.getElementById('mcc-delayeach').value = a?.delayEach != null ? a.delayEach : 100;
  document.getElementById('mcc-delaygroup').value = a?.delayGroup != null ? a.delayGroup : (a?.delayBefore != null ? a.delayBefore : 0);
  document.getElementById('mcc-radius').value = a?.radius != null ? a.radius : 3;
  const multEl = document.getElementById('mcc-mult');
  if (multEl) multEl.checked = a ? a.giftMult !== false : true;
  document.getElementById('mcc-random').checked = !!a?.random;
  const extraOn = a
    ? !!(a.cmdsExtra || (Array.isArray(a.cmds) && a.cmds.some((x) => x && typeof x === 'object' && (x.repeat != null || x.delayEach != null || x.delayBefore != null))))
    : false;
  document.getElementById('mcc-extra').checked = extraOn;
  document.getElementById('mcc-status').textContent = '';
  setMccImage(a?.image || '');
  syncMccExtraUI();
  renderMccLines(normalizeMccEntries(a?.cmds, a));
  document.getElementById('mcCmdModal').classList.remove('hidden');
}
function closeMcCmdModal() {
  closeMccVarsPop();
  closeMccGalleryPicker();
  document.getElementById('mcCmdModal').classList.add('hidden');
}

function isMccExtraMode() { return !!document.getElementById('mcc-extra')?.checked; }
function mccDefaultEntry() {
  return {
    cmd: '',
    repeat: 1,
    delayEach: 100,
    delayBefore: 0,
    radius: Math.max(0, parseInt(document.getElementById('mcc-radius')?.value, 10) || 3),
  };
}
function normalizeMccEntries(raw, action) {
  const extra = action?.cmdsExtra || isMccExtraMode();
  const defs = {
    radius: action?.radius ?? (Math.max(0, parseInt(document.getElementById('mcc-radius')?.value, 10) || 3)),
  };
  let list = Array.isArray(raw) ? raw.slice() : [];
  if (!list.length && action?.cmd) list = [action.cmd];
  if (!list.length) return extra ? [mccDefaultEntry()] : [''];
  if (!extra) return list.map((e) => (typeof e === 'string' ? e : (e?.cmd || e?.text || '')));
  return list.map((e) => {
    const o = (e && typeof e === 'object') ? e : { cmd: String(e || '') };
    return {
      cmd: o.cmd || o.text || '',
      repeat: o.repeat != null ? o.repeat : 1,
      delayEach: o.delayEach != null ? o.delayEach : 100,
      delayBefore: o.delayBefore != null ? o.delayBefore : (o.delayGroup != null ? o.delayGroup : 0),
      radius: o.radius != null ? o.radius : defs.radius,
    };
  });
}
function syncMccExtraUI() {
  const on = isMccExtraMode();
  const radiusRow = document.getElementById('mcc-radius-row');
  if (radiusRow) radiusRow.style.display = on ? '' : 'none';
}
function renderMccLines(lines) {
  const box = document.getElementById('mcc-cmds');
  if (!box) return;
  const extra = isMccExtraMode();
  const list = extra
    ? (lines.length ? lines : [mccDefaultEntry()])
    : (lines.length ? lines.map((l) => (typeof l === 'string' ? l : (l?.cmd || ''))) : ['']);
  updateMccCmdCount(list.length);
  box.innerHTML = list.map((l, i) => {
    const cmd = extra ? (l.cmd || '') : l;
    const extraFields = extra ? `
      <div class="mcc-line-times">
        <label class="mcc-time-field"><span class="mcc-time-lbl">Repetición</span><input type="number" class="mcc-x-repeat" min="1" value="${Math.max(1, parseInt(l.repeat, 10) || 1)}"></label>
        <label class="mcc-time-field"><span class="mcc-time-lbl">Retraso (ms)</span><input type="number" class="mcc-x-delaybefore" min="0" value="${Math.max(0, parseInt(l.delayBefore, 10) || 0)}" title="Milisegundos desde el inicio de la acción hasta el primer spawn de este comando"></label>
        <label class="mcc-time-field"><span class="mcc-time-lbl">Intervalo (ms)</span><input type="number" class="mcc-x-delayeach" min="0" value="${Math.max(0, parseInt(l.delayEach, 10) || 100)}" title="Pausa entre cada repetición del mismo comando"></label>
      </div>` : '';
    return `
    <div class="mcc-line">
      <div class="mcc-line-head">
        <span class="mcc-line-num">#${i + 1} Comando</span>
        <div class="mcc-line-btns">
          <button type="button" class="mcc-play mcc-play-once" data-i="${i}" data-mode="once" title="Probar 1 vez (solo sintaxis)">▶</button>
          <button type="button" class="mcc-play mcc-play-timed" data-i="${i}" data-mode="timed" title="Probar con tiempos (repetición / retraso / intervalo)">▶</button>
          <button type="button" class="mcc-line-del" data-i="${i}" title="Quitar">✕</button>
        </div>
      </div>
      ${extraFields}
      <textarea class="mcc-line-ta" rows="2" placeholder="Comando sin / inicial (ej. survival villager {nickname})">${esc(cmd)}</textarea>
    </div>`;
  }).join('');
  box.querySelectorAll('.mcc-line-del').forEach((b) => b.onclick = () => {
    const cur = collectMccEntries();
    cur.splice(+b.dataset.i, 1);
    renderMccLines(cur.length ? cur : (extra ? [mccDefaultEntry()] : ['']));
  });
  box.querySelectorAll('.mcc-play').forEach((b) => b.onclick = () => testMccLine(+b.dataset.i, b.dataset.mode || 'once'));
}
function testMccLine(i, mode = 'once') {
  if (ws?.readyState !== WebSocket.OPEN) {
    toast && toast('Sin conexión al servidor. Espera a que el panel conecte.', 'warn');
    return;
  }
  const extra = isMccExtraMode();
  const timed = mode === 'timed';
  const entries = collectMccEntries();
  const raw = entries[i];
  const cmd = extra ? (raw?.cmd || '').trim() : String(raw || '').trim();
  if (!cmd) { toast && toast('Escribe un comando antes de probar.', 'warn'); return; }
  const globalRepeat = Math.max(1, parseInt(document.getElementById('mcc-repeat')?.value, 10) || 1);
  const globalDelayEach = Math.max(0, parseInt(document.getElementById('mcc-delayeach')?.value, 10) || 0);
  const globalDelayGroup = Math.max(0, parseInt(document.getElementById('mcc-delaygroup')?.value, 10) || 0);
  const radius = Math.max(0, parseInt(document.getElementById('mcc-radius')?.value, 10) || 3);
  let entry;
  if (!timed) {
    entry = { cmd, repeat: 1, delayEach: 0, delayBefore: 0, radius };
  } else if (extra) {
    entry = {
      cmd,
      repeat: Math.max(1, parseInt(raw.repeat, 10) || 1),
      delayEach: Math.max(0, parseInt(raw.delayEach, 10) || 0),
      delayBefore: Math.max(0, parseInt(raw.delayBefore, 10) || 0),
      radius,
    };
  } else {
    entry = { cmd, repeat: globalRepeat, delayEach: globalDelayEach, delayBefore: globalDelayGroup, radius };
  }
  send({
    action: 'testMcDraft',
    entry,
    testMode: timed ? 'timed' : 'once',
    radius,
    cmdsExtra: timed && extra,
    repeat: timed ? (extra ? 1 : globalRepeat) : 1,
    delayEach: timed && !extra ? globalDelayEach : 0,
    delayGroup: timed && !extra ? globalDelayGroup : 0,
    giftMult: false,
  });
  toast && toast(timed ? 'Prueba con tiempos enviada…' : 'Prueba rápida (1 vez) enviada…', 'ok');
}
function openMccGalleryPicker() {
  const modal = document.getElementById('mcCmdModal');
  if (!modal) return;
  let overlay = document.getElementById('mcc-gallery-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'mcc-gallery-overlay';
    overlay.className = 'mcc-gallery-overlay hidden';
    overlay.innerHTML = `
      <div class="mcc-gallery-pop" role="dialog" aria-labelledby="mcc-gallery-title">
        <div class="mcc-gallery-head">
          <h3 id="mcc-gallery-title">Galería de comandos</h3>
          <button type="button" class="mcc-vars-close" id="mcc-gallery-close" aria-label="Cerrar">✕</button>
        </div>
        <input type="search" class="mcc-gallery-search" id="mcc-gallery-search" placeholder="Buscar…">
        <div class="mcc-gallery-list" id="mcc-gallery-list"></div>
      </div>`;
    modal.querySelector('.modal-box')?.appendChild(overlay);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) closeMccGalleryPicker(); });
    overlay.querySelector('.mcc-gallery-pop')?.addEventListener('click', (e) => e.stopPropagation());
    document.getElementById('mcc-gallery-close').onclick = () => closeMccGalleryPicker();
    document.getElementById('mcc-gallery-search').oninput = (e) => renderMccGalleryList(e.target.value);
  }
  document.getElementById('mcc-gallery-search').value = '';
  renderMccGalleryList('');
  overlay.classList.remove('hidden');
}
function closeMccGalleryPicker() {
  document.getElementById('mcc-gallery-overlay')?.classList.add('hidden');
}
function renderMccGalleryList(filter) {
  const list = document.getElementById('mcc-gallery-list');
  if (!list) return;
  const f = String(filter || '').trim().toLowerCase();
  const items = (MC_CATALOG || []).filter((c) => {
    if (!f) return true;
    return c.name.toLowerCase().includes(f) || (c.desc || '').toLowerCase().includes(f) || (c.cmd || '').toLowerCase().includes(f);
  });
  list.innerHTML = items.length ? items.map((c) => `
    <button type="button" class="mcc-gallery-item" data-id="${esc(c.id)}">
      <strong>${esc(c.name)}</strong>
      <span>${esc(c.desc || '')}</span>
    </button>`).join('') : '<p class="hint">Sin resultados</p>';
  list.querySelectorAll('.mcc-gallery-item').forEach((btn) => {
    btn.onclick = () => {
      const cat = MC_CATALOG.find((x) => x.id === btn.dataset.id);
      if (!cat?.cmd) return;
      const cur = collectMccEntries();
      if (cur.length >= MCC_MAX_CMDS) { toast && toast(`Máximo ${MCC_MAX_CMDS} comandos.`, 'warn'); return; }
      if (isMccExtraMode()) {
        if (cur.length && !(cur[cur.length - 1]?.cmd || '').trim()) cur.pop();
        cur.push({ ...mccDefaultEntry(), cmd: cat.cmd });
      } else {
        if (cur.length && !String(cur[cur.length - 1] || '').trim()) cur.pop();
        cur.push(cat.cmd);
      }
      renderMccLines(cur);
      closeMccGalleryPicker();
      toast && toast(`Añadido: ${cat.name}`, 'ok');
    };
  });
}
function collectMccEntries() {
  const extra = isMccExtraMode();
  const lines = [...document.querySelectorAll('#mcc-cmds .mcc-line')];
  if (!extra) return lines.map((row) => row.querySelector('.mcc-line-ta')?.value || '');
  return lines.map((row) => ({
    cmd: row.querySelector('.mcc-line-ta')?.value || '',
    repeat: Math.max(1, parseInt(row.querySelector('.mcc-x-repeat')?.value, 10) || 1),
    delayEach: Math.max(0, parseInt(row.querySelector('.mcc-x-delayeach')?.value, 10) || 0),
    delayBefore: Math.max(0, parseInt(row.querySelector('.mcc-x-delaybefore')?.value, 10) || 0),
    radius: Math.max(0, parseInt(document.getElementById('mcc-radius')?.value, 10) || 3),
  }));
}
function saveMcCmd() {
  if (!settings) return;
  const name = document.getElementById('mcc-name').value.trim();
  if (!name) { document.getElementById('mcc-status').textContent = '⚠️ Escribe un nombre.'; return; }
  const extra = isMccExtraMode();
  const entries = collectMccEntries();
  let cmds;
  if (extra) {
    cmds = entries
      .filter((e) => (e.cmd || '').trim())
      .map((e) => ({
        cmd: e.cmd.trim(),
        repeat: e.repeat,
        delayEach: e.delayEach,
        delayBefore: e.delayBefore,
        radius: e.radius,
      }));
  } else {
    cmds = entries.map((s) => String(s).trim()).filter(Boolean);
  }
  if (!cmds.length) { document.getElementById('mcc-status').textContent = '⚠️ Escribe al menos un comando.'; return; }
  const delayGroup = Math.max(0, parseInt(document.getElementById('mcc-delaygroup').value, 10) || 0);
  const payload = {
    name, desc: document.getElementById('mcc-desc').value.trim(),
    cmds,
    cmdsExtra: extra,
    repeat: Math.max(1, parseInt(document.getElementById('mcc-repeat').value, 10) || 1),
    delayEach: Math.max(0, parseInt(document.getElementById('mcc-delayeach').value, 10) || 0),
    delayGroup,
    delayBefore: delayGroup,
    radius: Math.max(0, parseInt(document.getElementById('mcc-radius').value, 10) || 0),
    random: document.getElementById('mcc-random').checked,
    image: mccImage || '',
    custom: true,
  };
  if (document.getElementById('mcc-mult')?.checked === false) payload.giftMult = false;
  const g = MC_GAME_MAP[mccGame] || MC_GAME_MAP.minecraft;
  const key = g.key;
  if (!Array.isArray(settings[key])) settings[key] = [];
  if (mccEditingUid) {
    const a = settings[key].find((x) => x.uid === mccEditingUid);
    if (a) {
      Object.assign(a, payload);
      if (document.getElementById('mcc-mult')?.checked === false) a.giftMult = false;
      else delete a.giftMult;
    }
  } else {
    settings[key].push({
      uid: 'mca_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
      catId: '', game: mccGame,
      trigger: 'gift', giftId: '', giftName: '', giftImage: '', enabled: true, ...payload,
    });
  }
  markMcPresetDirty(mccGame);
  saveSettings();
  g.render();
  closeMcCmdModal();
  toast && toast('Comando personalizado guardado.', 'ok');
}

function renderMcCatalog(filter) {
  const f = (filter || '').trim().toLowerCase();
  const list = f ? MC_CATALOG.filter((c) => c.name.toLowerCase().includes(f) || c.desc.toLowerCase().includes(f)) : MC_CATALOG;
  renderGameCatalogFold({
    grid: 'mc-catalog',
    stateKey: 'mc',
    filter,
    searchId: 'mc-cat-search',
    rerender: renderMcCatalog,
    closeModalId: 'mcCatalogModal',
    emptyMsg: 'Sin resultados',
    sections: buildCatalogSections(list, {
      sectionKey: 'section',
      order: MC_SECTION_ORDER,
      labelMap: MC_SECTION_LABEL,
      iconMap: MC_SECTION_ICON,
      searching: !!f,
    }),
    rowHtml: (c) => gameCatListBtnHtml(
      c.id,
      c.name,
      `<img class="repo-cat-list-ic" src="/img/minecraft/${esc(c.id)}.png${String(c.id || '').startsWith('ao_') ? '?v=ao1' : ''}" alt="" loading="lazy" decoding="async" onerror="this.outerHTML='<span class=\\'repo-cat-list-em\\'>⛏️</span>'">`,
      c.desc,
    ),
    onPick: addMcAction,
  });
}

function addMcAction(catId) {
  const c = MC_CATALOG.find((x) => x.id === catId);
  if (!c) return;
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  if (!Array.isArray(settings.mcActions)) settings.mcActions = [];
  settings.mcActions.push({
    uid: 'mca_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    catId: c.id, name: c.name, desc: c.desc, cmd: c.cmd,
    trigger: 'gift', giftId: '', giftName: '', giftImage: '', enabled: true, count: 1,
  });
  markMcPresetDirty('minecraft');
  saveSettings();
  renderMyMcActions();
  toast && toast(`Acción "${c.name}" agregada. Elige el regalo o evento.`, 'ok');
}

function mcCardQtyHtml(a) {
  if (a.custom) return '';
  return `<label class="mc-qty-row" title="Cuántos spawns/comandos por cada unidad del regalo. Si envían 2 rosas y pones 30, salen 60.">Cantidad a enviar
          <input type="number" min="1" class="mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(String(Math.max(1, parseInt(a.count, 10) || 1)))}"></label>`;
}
function mcCardComboInstantHtml(a) {
  if (a.trigger !== 'gift' && a.trigger !== 'gift-any') return '';
  const on = a.comboInstant !== false;
  return `<label class="mc-combo-instant mcc-check">
        <input type="checkbox" class="mc-combo-instant-en" data-uid="${esc(a.uid)}" ${on ? 'checked' : ''}>
        <span><b class="mc-combo-instant-lbl">Llamada instantánea</b> <span class="mc-combo-instant-sub">(cada rosa en racha; si desmarcas, al final de la racha)</span></span>
      </label>`;
}
function bindMcActionCardCommon(wrap, find, render) {
  wrap.querySelectorAll('.mc-combo-instant-en').forEach((c) => c.onchange = () => {
    const a = find(c.dataset.uid); if (!a) return;
    a.comboInstant = c.checked;
    saveSettings();
  });
}

function renderMyMcActions() {
  repairMcImportedCmds(settings?.mcActions);
  renderMcFamilyActions('minecraft');
}

/** TikFinity import antiguo: tenía `cmd` pero no `cmds[]` (el editor salía vacío). */
function repairMcImportedCmds(list) {
  if (!Array.isArray(list) || !list.length) return false;
  let changed = false;
  const cmdOf = (c) => String(typeof c === 'string' ? c : (c?.cmd || c?.text || '')).trim();
  for (const a of list) {
    if (!a) continue;
    const hasCmds = Array.isArray(a.cmds) && a.cmds.some((c) => cmdOf(c));
    const cmd = String(a.cmd || '').trim();
    const cat = a.catId ? MC_CATALOG.find((x) => x.id === a.catId) : null;
    // Acciones del catálogo: NO son personalizadas (si no, pierden «Cantidad a enviar»).
    // Si esta reparación ya convirtió alguna sin que el usuario la editara, se devuelve a catálogo.
    if (cat) {
      const onlyCatalogCmd = Array.isArray(a.cmds) && a.cmds.length === 1
        && cmdOf(a.cmds[0]) === cmd && cmd === String(cat.cmd || '').trim()
        && (typeof a.cmds[0] === 'string' || (!a.cmds[0].repeat && !a.cmds[0].delayEach && !a.cmds[0].delayBefore && !a.cmds[0].radius));
      if (a.custom && onlyCatalogCmd && !(Array.isArray(a.cmdsExtra) && a.cmdsExtra.length) && !a.random) {
        const rep = Math.max(1, parseInt(a.repeat, 10) || 1);
        if (rep > 1 && Math.max(1, parseInt(a.count, 10) || 1) === 1) a.count = rep;
        a.repeat = 1;
        delete a.custom;
        delete a.cmds;
        changed = true;
      }
      continue;
    }
    if (!hasCmds && cmd) {
      a.cmds = [cmd];
      a.custom = true;
      changed = true;
    } else if (hasCmds && !cmd) {
      const first = a.cmds.find((c) => String(typeof c === 'string' ? c : (c?.cmd || '')).trim());
      a.cmd = typeof first === 'string' ? first : String(first?.cmd || '');
      changed = true;
    }
  }
  if (changed) {
    try { saveSettings(); } catch {}
  }
  return changed;
}

function ensureMcAudioUpload() {
  let inp = document.getElementById('mc-audio-upload-file');
  if (!inp) {
    inp = document.createElement('input');
    inp.type = 'file';
    inp.id = 'mc-audio-upload-file';
    inp.accept = 'audio/*';
    inp.hidden = true;
    inp.addEventListener('change', async (e) => {
      const uid = mcAudioUploadUid;
      mcAudioUploadUid = null;
      const file = e.target.files[0];
      e.target.value = '';
      if (!file || !uid) return;
      const hit = findAnyGameAction(uid);
      if (!hit?.action) return;
      try {
        const res = await fetch('/api/upload?name=' + encodeURIComponent(file.name), { method: 'POST', body: file });
        const data = await res.json();
        if (!data.url) throw new Error(data.error || 'error');
        hit.action.sound = data.url;
        hit.action.soundName = file.name;
        if (!hit.action.audioOn) hit.action.audioOn = true;
        if (hit.action.soundVolume == null) hit.action.soundVolume = 100;
        flushSaveSettings();
        if (typeof hit.render === 'function') hit.render();
        try { closeSoundLib(); } catch {}
        toast && toast('Audio subido.', 'ok');
      } catch {
        toast && toast('No se pudo subir el audio.', 'error');
      }
    });
    document.body.appendChild(inp);
  }
  return inp;
}

// Genera una imagen tipo "menú de regalos" con las acciones agregadas:
// para cada acción muestra el regalo/evento que la activa, la cantidad a enviar
// y la acción de Minecraft (zombie, tnt, etc.). Se descarga como PNG.
/** Envía un PNG generado al Editor (sin descargar). Fallback: descarga clásica. */
async function openGeneratedImageInEditor(dataUrl, fileName) {
  if (!dataUrl) return false;
  if (typeof window.importGeneratedImageToEditor === 'function') {
    return !!(await window.importGeneratedImageToEditor(dataUrl, { name: fileName || 'overlay.png' }));
  }
  try {
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = fileName || 'overlay.png';
    document.body.appendChild(link);
    link.click();
    link.remove();
    toast && toast('Imagen descargada (Editor no disponible).', 'ok');
    return true;
  } catch {
    toast && toast('No se pudo abrir ni descargar la imagen.', 'err');
    return false;
  }
}

/** Overlay con capas → ahora va al Editor Pro (1 cuadro por acción). */
async function openOverlayLayersInEditor(payload) {
  if (payload && Array.isArray(payload.erRows) && payload.erRows.length) {
    return openGameActionsInEditorRapido(payload.erRows, { name: payload.name });
  }
  if (typeof window.importOverlayLayersToEditor === 'function') {
    return !!(await window.importOverlayLayersToEditor(payload || {}));
  }
  toast && toast('Editor no disponible.', 'err');
  return false;
}

function askOverlayOrientation() {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal confirm-modal';
    back.innerHTML = `
      <div class="confirm-box">
        <div class="confirm-ico">🖼️</div>
        <h3>Generar overlay</h3>
        <p>Vertical apila las acciones en columnas, para el live de celular. Horizontal las deja en filas, como hasta ahora.</p>
        <div class="confirm-btns" style="flex-wrap:wrap">
          <button type="button" class="btn ghost c-cancel">Cancelar</button>
          <button type="button" class="btn ghost c-vert">Vertical</button>
          <button type="button" class="btn primary c-horz">Horizontal</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    let done = false;
    const close = (val) => {
      if (done) return;
      done = true;
      try { document.removeEventListener('keydown', onEsc); } catch {}
      try { back.remove(); } catch {}
      resolve(val);
    };
    const onEsc = (e) => { if (e.key === 'Escape') close(''); };
    back.querySelector('.c-cancel').onclick = () => close('');
    back.querySelector('.c-vert').onclick = () => close('vertical');
    back.querySelector('.c-horz').onclick = () => close('horizontal');
    back.addEventListener('click', (e) => { if (e.target === back) close(''); });
    document.addEventListener('keydown', onEsc);
    setTimeout(() => back.querySelector('.c-horz')?.focus(), 30);
  });
}

/** Ya hay plantilla de este juego: ¿sumar lo nuevo ahí o empezar una nueva? */
function askOverlayMergeOrNew(tplName) {
  return new Promise((resolve) => {
    const back = document.createElement('div');
    back.className = 'modal confirm-modal';
    back.innerHTML = `
      <div class="confirm-box">
        <div class="confirm-ico">🖼️</div>
        <h3>Ya tienes un overlay de este juego</h3>
        <p>«${esc(tplName || 'Plantilla')}» ya existe. Puedes agregar ahí solo lo nuevo (tu diseño se queda igual) o crear una plantilla nueva desde cero.</p>
        <div class="confirm-btns" style="flex-wrap:wrap">
          <button type="button" class="btn ghost c-cancel">Cancelar</button>
          <button type="button" class="btn ghost c-new">Crear nueva</button>
          <button type="button" class="btn primary c-merge">Agregar lo nuevo</button>
        </div>
      </div>`;
    document.body.appendChild(back);
    let done = false;
    const close = (val) => {
      if (done) return;
      done = true;
      try { document.removeEventListener('keydown', onEsc); } catch {}
      try { back.remove(); } catch {}
      resolve(val);
    };
    const onEsc = (e) => { if (e.key === 'Escape') close(''); };
    back.querySelector('.c-cancel').onclick = () => close('');
    back.querySelector('.c-new').onclick = () => close('new');
    back.querySelector('.c-merge').onclick = () => close('merge');
    back.addEventListener('click', (e) => { if (e.target === back) close(''); });
    document.addEventListener('keydown', onEsc);
    setTimeout(() => back.querySelector('.c-merge')?.focus(), 30);
  });
}

function columnMajorGrid10(list) {
  const src = (Array.isArray(list) ? list : []).filter(Boolean);
  const cols = 10;
  const rows = 10;
  const gap = 2;
  const slots = Array.from({ length: cols * rows }, () => ({}));
  const contentCols = [];
  for (let c = 0; c < cols; c += 1 + gap) contentCols.push(c);
  let placed = 0;
  const putCol = (col) => {
    for (let row = 0; row < rows && placed < src.length; row++) {
      slots[row * cols + col] = src[placed++];
    }
  };
  contentCols.forEach(putCol);
  if (placed < src.length) {
    for (let c = 0; c < cols && placed < src.length; c++) {
      if (contentCols.indexOf(c) >= 0) continue;
      putCol(c);
    }
  }
  return slots;
}

async function openGameActionsInEditorRapido(rows, opts) {
  // «Generar imagen pro»: las mismas acciones van al generador de tableros en vez del Editor Pro.
  if (tableroProCapture) {
    const cap = tableroProCapture;
    tableroProCapture = null;
    return openTableroFromRows(rows, cap);
  }
  const o = { ...(opts || {}) };
  // Si este juego ya tiene su plantilla en el Editor Pro: sumar lo nuevo ahí, sin reiniciar el diseño.
  if (o.settingsKey && !o.forceNew) {
    try { if (typeof window.ensureEditorRapidoUi === 'function') await window.ensureEditorRapidoUi(); } catch {}
    let tpl = null;
    try { if (typeof window.findEditorTemplateForGame === 'function') tpl = await window.findEditorTemplateForGame(o.settingsKey); } catch {}
    if (tpl && typeof window.mergeGameActionsIntoEditorTemplate === 'function') {
      const choice = await askOverlayMergeOrNew(tpl.name);
      if (!choice) return false;
      if (choice === 'merge') {
        const base = Array.isArray(rows) ? rows.filter(Boolean) : [];
        return !!(await window.mergeGameActionsIntoEditorTemplate(base, { settingsKey: o.settingsKey, templateId: tpl.id }));
      }
    }
  }
  let orient = o.orient === 'vertical' || o.orient === 'horizontal' ? o.orient : '';
  if (!orient) {
    orient = await askOverlayOrientation();
    if (!orient) return false;
  }
  let list = Array.isArray(rows) ? rows.filter(Boolean) : [];
  if (orient === 'vertical' && list.length) {
    o.gridN = 10;
    list = columnMajorGrid10(list);
    const base = String(o.name || '').replace(/\.(png|jpe?g|gif|webp)$/i, '');
    if (base && !/-vertical$/i.test(base)) o.name = base + '-vertical';
  } else {
    o.gridN = 0;
  }
  try {
    if (typeof window.ensureEditorRapidoUi === 'function') await window.ensureEditorRapidoUi();
  } catch {}
  if (typeof window.importGameActionsToEditorRapido === 'function') {
    return !!(await window.importGameActionsToEditorRapido(list, o));
  }
  toast && toast('Editor Pro no disponible. Recarga el panel.', 'err');
  return false;
}

function editorRapidoCornerFromTrigger(trig) {
  const t = String(trig || 'gift');
  if (t === 'like' || t === 'likeGlobal') return 'like';
  if (t === 'follow') return 'follow';
  if (t === 'share') return 'share';
  if (t === 'subscribe' || t === 'fan' || t === 'superFan' || t === 'superFanJoin') return 'superfan';
  return '';
}

const ER_SYNCABLE_ACTION_KEYS = [
  'mcActions', 'bedrockActions', 'parkourActions', 'oneblockActions', 'paradiseActions', 'sandwallActions', 'kothActions', 'farmActions', 'sandboxActions', 'mcshooterActions',
  'marioActions', 'smb3Actions', 'smwActions', 'mari0Actions', 'pvzActions', 'pvzHybridActions', 'pvzFusionActions',
  'repoActions', 'l4dActions', 'unturnedActions', 'gtavKothActions', 'gtavChaosActions', 'gtavChiliadActions',
  'ctrActions', 'flappyActions', 'mk64Actions', 'mslugActions', 'gdashActions', 'robloxActions', 'roblox3Actions', 'robloxtkActions', 'robloxmtActions',
  'actions',
];

function settingsKeyFromEnsureList(fn) {
  const n = String(fn?.name || '');
  const m = /^ensure([A-Z].*)Actions$/.exec(n);
  if (!m) return '';
  return m[1].charAt(0).toLowerCase() + m[1].slice(1) + 'Actions';
}

function settingsKeyForActionList(list) {
  if (!settings || !Array.isArray(list)) return 'mcActions';
  for (const k of ER_SYNCABLE_ACTION_KEYS) {
    if (settings[k] === list) return k;
  }
  return 'mcActions';
}

function findSettingsKeyForActionUid(uid) {
  if (!uid || !settings) return '';
  const id = String(uid);
  if (id.includes('|')) {
    const actionId = id.split('|')[0];
    if ((settings.actions || []).some((a) => a && String(a.id) === actionId)) return 'actions';
  }
  for (const k of ER_SYNCABLE_ACTION_KEYS) {
    if (k === 'actions') continue;
    if ((settings[k] || []).some((a) => a && a.uid === uid)) return k;
  }
  return '';
}

function editorRapidoPatchFromAction(a) {
  if (!a) return null;
  const trig = a.trigger || 'gift';
  const cornerType = editorRapidoCornerFromTrigger(trig);
  let giftSrc = '';
  let giftEmoji = '';
  let giftName = 'Regalo';
  let giftId = '';
  if (cornerType) {
    giftName = (MC_TRIG_ICON[trig] || {}).label || giftName;
  } else if (trig === 'gift' || trig === 'gift-any') {
    giftSrc = overlayImgProxy((a.giftImage && String(a.giftImage).trim()) || giftImageOf(a));
    giftName = a.giftName || 'Regalo';
    giftId = String(a.giftId || '');
  } else {
    giftEmoji = (MC_TRIG_ICON[trig] || { ic: '⚡' }).ic;
    giftName = (MC_TRIG_ICON[trig] || {}).label || 'Evento';
  }
  let qty = Math.max(1, parseInt(a.count, 10) || 1);
  if (a.kind === 'sun') qty = Math.max(1, parseInt(a.amount, 10) || 50);
  return {
    uid: a.uid || '',
    giftSrc,
    giftEmoji,
    giftName,
    giftId,
    cornerType,
    trigger: trig,
    qty,
  };
}

function erIconUrlForSettingsKey(key, a) {
  if (!a) return '';
  return chosenActionImage(a) || validIconUrl(erCatalogIconUrlForSettingsKey(key, a));
}

function erCatalogIconUrlForSettingsKey(key, a) {
  if (!a) return '';
  try {
    switch (key) {
      case 'marioActions': return typeof marioCatalogIconUrl === 'function' ? marioCatalogIconUrl(a) : '';
      case 'mari0Actions': return typeof mari0CatalogIconUrl === 'function' ? mari0CatalogIconUrl(a) : '';
      case 'smb3Actions': return typeof smb3CatalogIconUrl === 'function' ? smb3CatalogIconUrl(a) : '';
      case 'smwActions': return typeof smwCatalogIconUrl === 'function' ? smwCatalogIconUrl(a) : '';
      case 'mslugActions': return typeof mslugCatalogIconUrl === 'function' ? mslugCatalogIconUrl(a) : '';
      case 'unturnedActions': return typeof unturnedCatalogIconUrl === 'function' ? unturnedCatalogIconUrl(a) : '';
      case 'gtavKothActions': return typeof gtavKothCatalogIconUrl === 'function' ? gtavKothCatalogIconUrl(a) : '';
      case 'gtavChaosActions': return typeof gtavChaosCatalogIconUrl === 'function' ? gtavChaosCatalogIconUrl(a) : '';
      case 'gtavChiliadActions': return typeof gtavChiliadCatalogIconUrl === 'function' ? gtavChiliadCatalogIconUrl(a) : '';
      case 'ctrActions': return typeof ctrCatalogIconUrl === 'function' ? ctrCatalogIconUrl(a) : '';
      case 'flappyActions': return typeof flappyCatalogIconUrl === 'function' ? flappyCatalogIconUrl(a) : '';
      case 'mk64Actions': return typeof mk64CatalogIconUrl === 'function' ? mk64CatalogIconUrl(a) : '';
      case 'pvzFusionActions': return typeof pvzFusionCatalogIconUrl === 'function' ? pvzFusionCatalogIconUrl(a) : '';
      case 'l4dActions': return typeof l4dCatalogIconUrl === 'function' ? l4dCatalogIconUrl(a) : '';
      case 'repoActions':
        return typeof repoImgSlug === 'function'
          ? `/img/repo/${encodeURIComponent(repoImgSlug(a.thing))}.png`
          : '';
      case 'pvzActions':
        return `/img/pvz/${encodeURIComponent(a.thing || '')}.png`;
      case 'pvzHybridActions':
        return (typeof pvzHybridThumbUrls === 'function' && pvzHybridThumbUrls(a.thing)?.primary)
          || `/img/pvzhybrid-thumbs/${encodeURIComponent(a.thing || '')}.png`;
      case 'gdashActions':
        return a.thing ? `/img/gdash/${a.thing}.png` : '';
      case 'stackActions':
        return a.thing ? `/img/stack-tower/${a.thing}.png?v=st1` : '';
      case 'pvzgeActions':
        return a.thing ? `/img/pvzge/${a.thing}.png?v=pz6` : '';
      case 'robloxActions':
        return `/img/roblox/${a.id || a.thing || ''}.png`;
      case 'roblox3Actions':
        return `/img/roblox3/${a.id || a.thing || ''}.png`;
      case 'robloxtkActions':
        return `/img/robloxtk/${a.img || ''}.png`;
      case 'robloxmtActions':
        return `/img/robloxmt/${a.id || a.thing || ''}.png`;
      case 'robloxhwActions':
        return rbxhwDefaultImg(a);
      case 'mcActions':
        return `/img/minecraft/${a.catId || ''}.png${String(a.catId || '').startsWith('ao_') ? '?v=ao1' : ''}`;
      case 'bedrockActions':
        return `/img/bedrock/${a.catId || ''}.png`;
      case 'farmActions':
        return `/img/farm/${a.catId || ''}.png`;
      case 'parkourActions':
        return `/img/parkour/${a.catId || ''}.png`;
      case 'oneblockActions':
        return `/img/oneblock/${a.catId || ''}.png`;
      case 'paradiseActions':
        return `/img/mcparadise/${a.catId || ''}.png`;
      case 'sandwallActions':
        return `/img/sandwall/${a.catId || ''}.png?v=sw6`;
      case 'kothActions':
        return `/img/koth/${a.catId || ''}.png`;
      case 'sandboxActions':
        return `/img/sandbox/${a.catId || ''}.png`;
      case 'mcshooterActions':
        return `/img/mcshooter/${a.catId || ''}.png`;
      default:
        return a.img || '';
    }
  } catch {
    return '';
  }
}

function accActionHasMinigame(a) {
  const gc = a && a.gameCmd;
  if (!gc || gc.on === false || !gc.game) return false;
  const spec = typeof accMgSpec === 'function' ? accMgSpec(gc.game) : null;
  if (spec && spec.kind === 'keys') return false;
  return Array.isArray(gc.cmds) && gc.cmds.some((c) => typeof accMgHasOutput === 'function' ? accMgHasOutput(c) : !!(c && (c.thing || c.cmd)));
}

function accErUid(actionId, eventId, cmdIdx) {
  return `${actionId}|${eventId}|${cmdIdx}`;
}

function accGameSettingsKey(game) {
  const tab = String(game || '');
  const preset = (typeof GAME_TAB_TO_PRESET !== 'undefined' && GAME_TAB_TO_PRESET[tab]) || tab;
  return (typeof GAME_PRESET_MAP !== 'undefined' && GAME_PRESET_MAP[preset] && GAME_PRESET_MAP[preset].key) || '';
}

function accMgIconSrcFromHtml(html) {
  const m = String(html || '').match(/\ssrc=["']([^"']+)["']/i);
  return m ? m[1] : '';
}

function accErIconForCmd(game, cmd) {
  const htmlIcon = accMgIconSrcFromHtml(cmd?.iconHtml);
  if (htmlIcon) return htmlIcon;
  const rawId = String(cmd?.thing || cmd?.catId || '');
  const catId = /\s/.test(rawId) ? '' : rawId;
  const fake = {
    thing: catId || cmd?.thing || cmd?.cmd || '',
    label: cmd?.label || '',
    nombre: cmd?.label || '',
    catId,
    id: catId,
    catalogId: catId,
    tipo: cmd?.tipo,
    kind: cmd?.kind,
    npcId: cmd?.npcId,
    spawnId: cmd?.spawnId,
  };
  const sk = accGameSettingsKey(game);
  return sk ? erIconUrlForSettingsKey(sk, fake) : '';
}

function editorRapidoPatchFromAccEvent(ev) {
  if (!ev) return null;
  return editorRapidoPatchFromAction({
    trigger: ev.event || 'gift',
    giftId: ev.giftId,
    giftName: ev.giftName,
    giftImage: ev.giftImage,
    count: 1,
  });
}

function buildEditorRapidoRowsFromAcciones() {
  const actions = Array.isArray(settings?.actions) ? settings.actions : [];
  const events = Array.isArray(settings?.actionEvents) ? settings.actionEvents : [];
  const byId = new Map(actions.filter((a) => a && a.id).map((a) => [String(a.id), a]));
  const rows = [];
  const seen = new Set();
  for (const ev of events) {
    if (!ev || !ev.id) continue;
    const ids = [].concat(ev.actionIds || [], ev.randomActionIds || []).map(String).filter(Boolean);
    for (const aid of ids) {
      const a = byId.get(aid);
      if (!accActionHasMinigame(a)) continue;
      const cmds = (a.gameCmd.cmds || []).filter((c) => typeof accMgHasOutput === 'function' ? accMgHasOutput(c) : !!(c && (c.thing || c.cmd)));
      const patch = editorRapidoPatchFromAccEvent(ev) || {};
      cmds.forEach((cmd, i) => {
        const uid = accErUid(a.id, ev.id, i);
        if (seen.has(uid)) return;
        seen.add(uid);
        const iconSrc = overlayImgProxy(chosenActionImage(a) || validIconUrl(accErIconForCmd(a.gameCmd.game, cmd)));
        rows.push({
          actionSrc: iconSrc || EDITOR_OVERLAY_CLOUD_SRC,
          actionName: cmd.label || cmd.thing || a.name || 'Acción',
          actionUid: uid,
          uid,
          giftSrc: patch.giftSrc || '',
          giftEmoji: patch.giftEmoji || '',
          giftName: patch.giftName || 'Regalo',
          giftId: patch.giftId || '',
          cornerType: patch.cornerType || '',
          trigger: patch.trigger || '',
          qty: Math.max(1, parseInt(cmd.count, 10) || 1),
        });
      });
    }
  }
  return rows;
}

function buildEditorRapidoRowsForSettingsKey(settingsKey) {
  const key = String(settingsKey || '').trim();
  if (key === 'actions') return buildEditorRapidoRowsFromAcciones();
  const list = Array.isArray(settings?.[key]) ? settings[key].filter(Boolean) : [];
  return list.map((a) => {
    const patch = editorRapidoPatchFromAction(a) || {};
    const iconSrc = overlayImgProxy(erIconUrlForSettingsKey(key, a));
    return {
      actionSrc: iconSrc || EDITOR_OVERLAY_CLOUD_SRC,
      actionName: a.name || a.label || a.thing || 'Acción',
      actionUid: a.uid || '',
      uid: a.uid || '',
      giftSrc: patch.giftSrc || '',
      giftEmoji: patch.giftEmoji || '',
      giftName: patch.giftName || 'Regalo',
      giftId: patch.giftId || '',
      cornerType: patch.cornerType || '',
      trigger: patch.trigger || '',
      qty: patch.qty || 1,
    };
  });
}

let _erGameSyncTimer = null;
function notifyEditorRapidoActionsChanged(settingsKey) {
  if (Date.now() < erSyncSuppressedUntil) return;
  const key = String(settingsKey || '').trim();
  if (!key || !Array.isArray(settings?.[key])) return;
  clearTimeout(_erGameSyncTimer);
  _erGameSyncTimer = setTimeout(() => {
    if (Date.now() < erSyncSuppressedUntil) return;
    if (typeof window.syncEditorRapidoFromGameActions !== 'function') return;
    const rows = buildEditorRapidoRowsForSettingsKey(key);
    window.syncEditorRapidoFromGameActions(key, rows).catch(() => {});
  }, 250);
}

/** Esquina del Editor Pro -> disparador de la acción. */
const ER_CORNER_TRIGGER = { like: 'like', follow: 'follow', share: 'share', superfan: 'subscribe' };

function renderGameActionsForSettingsKey(key) {
  try {
    for (const g of Object.values(GAME_PRESET_MAP)) {
      if (g && g.key === key && typeof g.render === 'function') { g.render(); return; }
    }
  } catch { /* ignore */ }
}

/** Editor Pro -> Juegos: el regalo de un cuadro es el disparador de su acción,
    así que cambiarlo en el Editor debe cambiarlo también en la acción. */
window.applyEditorRapidoGiftToGameAction = function applyEditorRapidoGiftToGameAction(settingsKey, uid, payload) {
  const id = String(uid || '').trim();
  if (!id || !payload) return false;
  if (id.includes('|')) return applyEditorRapidoGiftToAccionEvent(id, payload);
  let key = String(settingsKey || '').trim();
  if (!key || !Array.isArray(settings?.[key]) || !settings[key].some((a) => a && a.uid === id)) {
    key = findSettingsKeyForActionUid(id);
  }
  if (!key || !Array.isArray(settings?.[key])) return false;
  const a = settings[key].find((x) => x && x.uid === id);
  if (!a) return false;

  // El Editor no distingue likes globales de likes por usuario: si se pierde el
  // matiz hay que decirlo, porque cambia a quién responde la acción en directo.
  const wasLikeGlobal = a.trigger === 'likeGlobal';
  const type = String(payload.type || 'gift');
  if (type === 'gift') {
    const gid = String(payload.giftId || '').trim();
    if (!gid) return false;
    const cat = giftCatalogById.get(gid);
    if (a.trigger === 'gift' && String(a.giftId || '') === gid) return true;
    a.trigger = 'gift';
    a.giftId = gid;
    a.giftName = cat?.name || String(payload.giftName || 'Regalo');
    a.giftImage = cat?.image || '';
  } else {
    const trig = ER_CORNER_TRIGGER[type];
    if (!trig) return false;
    // superFan/subscribe comparten icono: si ya es ese evento, no pisar el matiz elegido.
    if (editorRapidoCornerFromTrigger(a.trigger) === type) return true;
    a.trigger = trig;
  }

  if (wasLikeGlobal && a.trigger !== 'likeGlobal') {
    toast && toast('Esa acción usaba «Likes globales». Ahora usa otro disparador; si lo necesitas, vuelve a elegirlo en Juegos.', 'warn');
  }

  lastGameActionEditAt = Date.now();
  suppressEditorRapidoSync(1500);
  saveSettingsKeysPatch(key);
  renderGameActionsForSettingsKey(key);
  return true;
};

function applyEditorRapidoGiftToAccionEvent(uid, payload) {
  const parts = String(uid || '').split('|');
  const eventId = parts[1];
  if (!eventId || !payload || !settings) return false;
  const ev = (settings.actionEvents || []).find((e) => e && String(e.id) === String(eventId));
  if (!ev) return false;
  const wasLikeGlobal = ev.event === 'likeGlobal';
  const type = String(payload.type || 'gift');
  if (type === 'gift') {
    const gid = String(payload.giftId || '').trim();
    if (!gid) return false;
    const cat = giftCatalogById.get(gid);
    if (ev.event === 'gift' && String(ev.giftId || '') === gid) return true;
    ev.event = 'gift';
    ev.giftId = gid;
    ev.giftName = cat?.name || String(payload.giftName || 'Regalo');
    ev.giftImage = cat?.image || '';
    ev.emoteId = '';
    ev.emoteImage = '';
  } else {
    const trig = ER_CORNER_TRIGGER[type];
    if (!trig) return false;
    if (editorRapidoCornerFromTrigger(ev.event) === type) return true;
    ev.event = trig;
    ev.giftId = '';
    ev.giftName = '';
    ev.giftImage = '';
    ev.emoteId = '';
    ev.emoteImage = '';
  }
  if (wasLikeGlobal && ev.event !== 'likeGlobal') {
    toast && toast('Ese evento usaba «Likes globales». Ahora usa otro disparador; si lo necesitas, vuelve a elegirlo en Eventos.', 'warn');
  }
  lastGameActionEditAt = Date.now();
  suppressEditorRapidoSync(1500);
  try { markMcPresetDirty('acciones'); } catch {}
  saveSettingsKeysPatch('actionEvents');
  if (typeof renderAccEventos === 'function') renderAccEventos();
  return true;
}

async function generateAccionesOverlayImage() {
  const games = new Set();
  for (const a of (settings.actions || [])) {
    if (accActionHasMinigame(a)) games.add(a.gameCmd.game);
  }
  for (const g of games) {
    try { await accMgEnsureCatalog(g); } catch {}
  }
  const rows = buildEditorRapidoRowsFromAcciones();
  if (!rows.length) {
    toast && toast('Crea una acción de Mini-Juegos y un evento que la dispare (regalo, like…).', 'warn');
    return;
  }
  if (!tableroProCapture) toast && toast('Abriendo en Editor Pro…', 'ok');
  lastGameActionEditAt = Date.now();
  try {
    markMcPresetDirty('acciones');
    saveSettingsKeysPatch('actions', 'actionEvents', { flush: true, skipErSync: true });
  } catch {}
  await openGameActionsInEditorRapido(rows, {
    name: 'acciones-overlay',
    settingsKey: 'actions',
  });
}

const EDITOR_OVERLAY_CLOUD_SRC = 'data:image/svg+xml,' + encodeURIComponent(
  '<svg xmlns="http://www.w3.org/2000/svg" width="108" height="108" viewBox="0 0 108 108">'
  + '<ellipse cx="40" cy="58" rx="28" ry="22" fill="#c5e4f8"/>'
  + '<ellipse cx="58" cy="48" rx="32" ry="26" fill="#c5e4f8"/>'
  + '<ellipse cx="78" cy="56" rx="24" ry="20" fill="#c5e4f8"/>'
  + '</svg>'
);

/** Imagen que el usuario eligió para la acción: va antes que el icono del catálogo
    (antes «Generar imagen» la ignoraba y en Editor Pro salía el cuadro vacío). */
function chosenActionImage(a) {
  return String((a && a.image) || '').trim();
}
/** Icono de catálogo sin id («/img/juego/.png») no existe: mejor la nube que un cuadro vacío. */
function validIconUrl(u) {
  const s = String(u || '');
  return /\/\.png(?:[?#]|$)/.test(s) ? '' : s;
}

function overlayImgProxy(u) {
  if (!u) return '';
  if (/^(data|blob):/i.test(String(u))) return u;
  try {
    if (new URL(u, location.href).origin === location.origin) return u;
  } catch { /* ignore */ }
  return `/api/img-proxy?url=${encodeURIComponent(u)}`;
}

async function generateMcMenuImage(srcList, iconDir, fileName, iconUrlFor) {
  const all = Array.isArray(srcList) ? srcList : ((settings && Array.isArray(settings.mcActions)) ? settings.mcActions : []);
  const ICON_DIR = iconDir || '/img/minecraft/';
  const settingsKey = settingsKeyForActionList(all);
  const list = all.filter(Boolean);
  if (!list.length) { toast && toast('Agrega acciones primero (con su regalo o evento).', 'warn'); return; }
  if (!tableroProCapture) toast && toast('Abriendo en Editor Pro…', 'ok');

  const rows = [];
  for (const a of list) {
    const patch = editorRapidoPatchFromAction(a) || {};
    const iconSrc = overlayImgProxy(chosenActionImage(a) || validIconUrl(typeof iconUrlFor === 'function'
      ? iconUrlFor(a)
      : ICON_DIR + (a.catId || '') + '.png'));
    rows.push({
      actionSrc: iconSrc || EDITOR_OVERLAY_CLOUD_SRC,
      actionName: a.name || a.label || 'Acción',
      actionUid: a.uid || '',
      giftSrc: patch.giftSrc || '',
      giftEmoji: patch.giftEmoji || '',
      giftName: patch.giftName || 'Regalo',
      cornerType: patch.cornerType || '',
      trigger: patch.trigger || '',
      qty: patch.qty || 1,
    });
  }

  await openGameActionsInEditorRapido(rows, {
    name: fileName || 'menu-regalos-minecraft.png',
    settingsKey,
  });
}

