function closeMcCfgCmdsPop() {
  const el = document.getElementById('mc-cfg-cmds-pop');
  if (el) el.classList.add('hidden');
}

function placeMcCfgCmdsPop(anchor) {
  const pop = document.getElementById('mc-cfg-cmds-pop');
  if (!pop || !anchor) return;
  const r = anchor.getBoundingClientRect();
  const w = Math.min(360, window.innerWidth - 16);
  pop.style.width = w + 'px';
  const h = pop.offsetHeight || 320;
  let left = r.left;
  let top = r.bottom + 6;
  if (left + w > window.innerWidth - 8) left = window.innerWidth - w - 8;
  if (left < 8) left = 8;
  if (top + h > window.innerHeight - 8) top = Math.max(8, r.top - h - 6);
  pop.style.left = left + 'px';
  pop.style.top = top + 'px';
}

async function copyMcCfgCmd(command) {
  let cmd = String(command || '').trim();
  if (!cmd) { toast && toast('Escribe un comando.', 'warn'); return; }
  if (!cmd.startsWith('/')) cmd = '/' + cmd;
  let ok = false;
  try { await navigator.clipboard.writeText(cmd); ok = true; }
  catch {
    try {
      const ta = document.createElement('textarea');
      ta.value = cmd;
      ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;left:-9999px;top:0';
      document.body.appendChild(ta);
      ta.select();
      ok = document.execCommand('copy');
      ta.remove();
    } catch { /* ignore */ }
  }
  toast && toast(ok ? `Copiado: ${cmd}` : 'No se pudo copiar.', ok ? 'ok' : 'warn');
}

function ensureMcCfgCmdsPop() {
  let el = document.getElementById('mc-cfg-cmds-pop');
  if (el) return el;
  el = document.createElement('div');
  el.id = 'mc-cfg-cmds-pop';
  el.className = 'game-act-swap-pop mc-cfg-cmds-pop hidden';
  el.setAttribute('role', 'dialog');
  el.innerHTML = `
    <div class="game-act-swap-head">
      <strong id="mc-cfg-cmds-title">Comando creación</strong>
      <button type="button" class="game-act-swap-x" id="mc-cfg-cmds-close" aria-label="Cerrar">✕</button>
    </div>
    <p class="mc-cfg-cmds-hint">Copia y pega en el chat de Minecraft (no van por RCON).</p>
    <div class="game-act-swap-list mc-cfg-cmds-list" id="mc-cfg-cmds-list"></div>`;
  el.addEventListener('mousedown', (e) => e.stopPropagation());
  el.addEventListener('click', (e) => e.stopPropagation());
  document.body.appendChild(el);
  document.getElementById('mc-cfg-cmds-close').onclick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    closeMcCfgCmdsPop();
  };
  const box = document.getElementById('mc-cfg-cmds-list');
  if (box && !box._wired) {
    box._wired = true;
    box.addEventListener('click', (e) => {
      const btn = e.target.closest('.mc-cfg-cmds-copy');
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      copyMcCfgCmd(btn.dataset.cmd || '');
    });
  }
  if (!window._mcCfgCmdsOutside) {
    window._mcCfgCmdsOutside = true;
    document.addEventListener('mousedown', (e) => {
      const pop = document.getElementById('mc-cfg-cmds-pop');
      if (!pop || pop.classList.contains('hidden')) return;
      if (e.target.closest('#mc-cfg-cmds-pop') || e.target.closest('[id$="-cfg-cmds"]')) return;
      closeMcCfgCmdsPop();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeMcCfgCmdsPop();
    });
  }
  return el;
}

function openMcCfgCmdsPop(anchor, opts = {}) {
  const list = Array.isArray(opts.commands) ? opts.commands : [];
  const el = ensureMcCfgCmdsPop();
  const title = document.getElementById('mc-cfg-cmds-title');
  if (title) title.textContent = opts.heading || 'Comando creación';
  el.dataset.btnId = opts.btnId || '';
  const box = document.getElementById('mc-cfg-cmds-list');
  if (box) {
    box.innerHTML = list.length
      ? list.map((c) => {
        const cmd = String(c.cmd || '').trim();
        const shown = cmd.startsWith('/') ? cmd : `/${cmd}`;
        return `<div class="mc-cfg-cmds-row">
          <div class="mc-cfg-cmds-copy-block">
            <strong>${esc(c.name || cmd)}</strong>
            <em>${esc(c.desc || '')}</em>
            <code>${esc(shown)}</code>
          </div>
          <button type="button" class="mc-cfg-cmds-copy bd-cfg-copy" data-cmd="${esc(cmd)}">Copiar</button>
        </div>`;
      }).join('')
      : '<div class="game-act-swap-empty">Sin comandos</div>';
  }
  el.classList.remove('hidden');
  placeMcCfgCmdsPop(anchor);
  requestAnimationFrame(() => placeMcCfgCmdsPop(anchor));
}

function wireMcCfgCmdsButton(btnId, commands, heading) {
  const btn = document.getElementById(btnId);
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    const pop = document.getElementById('mc-cfg-cmds-pop');
    if (pop && !pop.classList.contains('hidden') && pop.dataset.btnId === btnId) {
      closeMcCfgCmdsPop();
      return;
    }
    openMcCfgCmdsPop(btn, {
      heading: heading || 'Comando creación',
      commands: commands || [],
      btnId,
    });
  };
}

