function exportOneblockPresets() {
  const list = (settings && Array.isArray(settings.oneblockActions)) ? settings.oneblockActions : [];
  if (!list.length) { toast && toast('No hay acciones de OneBlock para exportar.', 'warn'); return; }
  const out = { type: 'livecoins-oneblock-presets', version: 1, exportedAt: Date.now(), oneblockActions: list };
  const blob = new Blob([JSON.stringify(out, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `oneblock-presets-${window.MY_USER || 'panel'}-${Date.now()}.json`;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => { try { URL.revokeObjectURL(a.href); } catch {} }, 1000);
  toast && toast(`Exportadas ${list.length} acciones de OneBlock.`, 'ok');
}

async function importOneblockPresets(file) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  let parsed;
  try { parsed = JSON.parse(await file.text()); }
  catch { toast && toast('El archivo no es un preset válido.', 'warn'); return; }
  const incoming = Array.isArray(parsed)
    ? parsed
    : (parsed && Array.isArray(parsed.oneblockActions) ? parsed.oneblockActions : null);
  if (!incoming || !incoming.length) { toast && toast('El archivo no contiene acciones de OneBlock.', 'warn'); return; }
  const mode = await askMcImportMode(incoming.length);
  if (!mode) return;
  const clean = incoming
    .filter((a) => a && typeof a === 'object')
    .map((a, i) => ({ ...a, game: 'mconeblock', uid: 'mca_' + Date.now() + '_' + i + '_' + Math.random().toString(36).slice(2, 7) }));
  if (!Array.isArray(settings.oneblockActions)) settings.oneblockActions = [];
  settings.oneblockActions = (mode === 'replace') ? clean : settings.oneblockActions.concat(clean);
  saveSettings();
  renderMyOneblockActions();
  toast && toast(mode === 'replace' ? 'Acciones de OneBlock reemplazadas.' : 'Acciones de OneBlock añadidas.', 'ok');
}

function setupMcOneblockActionsUI() {
  const search = document.getElementById('mconeblock-cat-search');
  if (search && !search._wired) { search._wired = true; search.oninput = () => renderOneblockCatalog(search.value); }
  const createBtn = document.getElementById('mconeblock-create-cmd');
  if (createBtn && !createBtn._wired) {
    createBtn._wired = true;
    createBtn.onclick = () => { if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; } openMcCmdModal(null, 'mconeblock'); };
  }
  wireMcCfgCmdsButton('mconeblock-cfg-cmds', ONEBLOCK_CONFIGS, 'Comando creación');
  const genImgBtn = document.getElementById('mconeblock-gen-img');
  if (genImgBtn && !genImgBtn._wired) {
    genImgBtn._wired = true;
    genImgBtn.onclick = () => generateMcMenuImage(settings && settings.oneblockActions, '/img/oneblock/', 'menu-regalos-oneblock.png');
  }
  const expBtn = document.getElementById('mconeblock-export-preset');
  if (expBtn && !expBtn._wired) { expBtn._wired = true; expBtn.onclick = exportOneblockPresets; }
  const impBtn = document.getElementById('mconeblock-import-preset');
  const impFile = document.getElementById('mconeblock-import-file');
  if (impBtn && impFile && !impBtn._wired) {
    impBtn._wired = true;
    impBtn.onclick = () => { if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; } impFile.click(); };
    impFile.addEventListener('change', async (e) => {
      const file = e.target.files[0];
      e.target.value = '';
      if (file) await importOneblockPresets(file);
    });
  }
  wireGameToggleAllButton('mconeblock-toggle-all', () => (settings && Array.isArray(settings.oneblockActions)) ? settings.oneblockActions : [], renderMyOneblockActions, 'oneblockActions');
  renderOneblockCatalog(search ? search.value : '');
  renderMyOneblockActions();
}

