  const f = (filter || '').trim().toLowerCase();
  const list = f ? ONEBLOCK_CATALOG.filter((c) => c.name.toLowerCase().includes(f) || c.desc.toLowerCase().includes(f) || c.cmd.toLowerCase().includes(f) || (ONEBLOCK_SECTION_LABEL[c.section] || '').toLowerCase().includes(f)) : ONEBLOCK_CATALOG;
