function warnMarioQueuePending(h) {
  if (!h || !h.ok) {
    toast && toast('Bridge Mario no responde. Pulsa «Conectar».', 'warn');
    return;
  }
  const pending = Number(h.queuePending) || 0;
  if (pending > 0) {
    toast && toast(
      pending === 1
        ? 'Spawn en cola. Entra a SMBX2 → cliche → nivel marios_pad con Mario en pantalla.'
        : `Hay ${pending} spawns en cola. Entra a un nivel en SMBX2 (marios_pad).`,
      'warn',
    );
  }
}

function parseMarioWebhookSpawn(url, times = 1) {
  try {
    const u = new URL(String(url).replace(/\{[^}]+\}/g, 'Prueba'));
    if (!/\/spawn\b/i.test(u.pathname)) return null;
    const id = u.searchParams.get('id') ?? u.searchParams.get('npcId');
    const qty = u.searchParams.get('quantity') ?? u.searchParams.get('count') ?? '1';
    const npcId = Number(id);
    if (!Number.isFinite(npcId)) return null;
    const name = decodeURIComponent(u.searchParams.get('userName') || 'Prueba');
    return { npcId, name, times: Math.max(1, (parseInt(qty, 10) || 1) * times) };
  } catch { return null; }
}

async function testMarioWebhookLocal(a, times) {
  const label = a.label || a.thing || 'acción';
  const qty = Math.max(1, Math.min(999, parseInt(times, 10) || 1));
  let url = applyMarioWebhookQuantity(a.webhookCmd.url, qty);
  url = url.replace(/\{nickname\}/gi, 'Prueba').replace(/\{username\}/gi, 'prueba');
  let r;
  // Misma ruta que donaciones en vivo: webhook :5720 con quantity=N en una sola petición.
  if (isExternalSmbxTiktokWebhook(a.webhookCmd.url)) {
    r = await execGameLocal({
      tipo: 'WEBHOOK',
      method: a.webhookCmd.method || 'GET',
      url,
      body: a.webhookCmd.body || '',
    });
  } else {
    const parsed = parseMarioWebhookSpawn(url, 1);
    if (parsed) {
      r = await execGameLocal({
        tipo: 'MARIO_SPAWN', thing: parsed.npcId, npcId: parsed.npcId,
        name: parsed.name, times: parsed.times,
      });
    } else {
      r = await execGameLocal({
        tipo: 'WEBHOOK',
        method: a.webhookCmd.method || 'GET',
        url,
        body: a.webhookCmd.body || '',
      });
    }
  }
  if (r && r.ok !== false) {
    addEvent(`🍄 Prueba Mario: ${esc(label)}${qty > 1 ? ` ×${qty}` : ''}`, 'ok');
    return true;
  }
  toast && toast(`Spawn falló («${label}»). ¿SMBX2 abierto en marios_pad?`, 'warn');
  return false;
}

async function testMarioAction(a) {
  if (!a) return;
  const label = a.label || a.thing || 'acción';
  if (!IS_DESKTOP) {
    toast && toast('Mario Bros solo funciona en la app de escritorio (.exe).', 'warn');
    return;
  }

  if (a.webhookCmd?.on && a.webhookCmd?.url) {
    const times = Math.max(1, parseInt(a.count, 10) || 1);
    if (isExternalSmbxTiktokWebhook(a.webhookCmd.url)) {
      const whBridge = await requireGameBridge('smbx');
      if (!whBridge) {
        toast && toast('Bridge Mario apagado. Pulsa «Conectar».', 'warn');
        return;
      }
    }
    await testMarioWebhookLocal(a, times);
    return;
  }

  if (a.kind !== 'effect' && !a.thing && a.npcId == null) {
    toast && toast('Acción sin enemigo/objeto. Quítala y agrégala de nuevo del catálogo.', 'warn');
    return;
  }

  const bridgeH = await requireGameBridge('smbx');
  if (!bridgeH) {
    toast && toast('Bridge Mario apagado. Pulsa «Conectar».', 'warn');
    return;
  }

  if (a.kind === 'effect') {
    const seconds = Math.max(1, parseInt(a.seconds, 10) || 5);
    const factor = Math.max(0, parseInt(a.factor, 10) || 0);
    const r = await execGameLocal({ tipo: 'MARIO_EFFECT', type: a.thing, seconds, factor });
    if (r && r.ok !== false) addEvent(`🍄 Prueba Mario: efecto ${esc(label)}`, 'ok');
    else toast && toast('Efecto no enviado. Pulsa «Conectar».', 'warn');
    return;
  }

  const times = Math.max(1, parseInt(a.count, 10) || 1);
  const spawnThing = a.thing || String(a.npcId);
  let ok = false;
  await runTimedGameActionTest(a, async () => {
    const r = await execGameLocal({ tipo: 'MARIO_SPAWN', thing: spawnThing, npcId: a.npcId, name: 'Prueba', times: 1 });
    if (r && r.ok !== false) ok = true;
  }, { timingMode: 'count' });
  if (ok) {
    addEvent(`🍄 Prueba Mario: ${esc(label)}${times > 1 ? ` ×${times}` : ''}`, 'ok');
    setTimeout(async () => warnMarioQueuePending((await gameBridgeHealth()) || bridgeH), 400);
  } else {
    toast && toast(`Spawn falló («${label}»). Inicia bridge y entra a marios_pad en SMBX2.`, 'warn');
  }
}

/** Mario y Mari0 traen su webhook del catálogo: al cambiar la cosa hay que
    reemplazarlo (o quitarlo) o quedaría apuntando a la anterior. Lo que eligió
    el usuario —disparador, regalo, cantidad— no se toca. */
function marioFamilyWebhookAssign(a, c) {
  if (c.webhookCmd?.on && c.webhookCmd?.url) {
    a.webhookCmd = {
      on: true,
      method: c.webhookCmd.method || 'GET',
      url: applyMarioWebhookQuantity(c.webhookCmd.url, Math.max(1, parseInt(a.count, 10) || 1)),
      body: c.webhookCmd.body || '',
    };
    a.comboInstant = c.comboInstant !== false;
  } else if (a.webhookCmd) {
    delete a.webhookCmd;
  }
}

registerGameActSwap('mario', {
  title: 'Clic para cambiar el objeto o enemigo',
  heading: 'Cambiar elemento',
  placeholder: 'Buscar elemento…',
  entries: () => (MARIO_CATALOG || []).map((c) => ({
    id: c.id, name: c.nombre, desc: MARIO_TIPO_LABEL[c.tipo] || '', iconHtml: marioCatalogIconHtml(c),
  })),
  current: (uid) => ensureMarioActions().find((x) => x && x.uid === uid)?.thing,
  apply: gameActSwapApply({
    actions: ensureMarioActions,
    entry: (id) => MARIO_CATALOG.find((x) => x.id === id),
    settingsKey: 'marioActions',
    render: () => renderMarioActions(),
    assign: (a, c) => {
      a.catalogId = c.id;
      a.npcId = c.npcId != null ? c.npcId : null;
      a.tipo = c.tipo;
      a.kind = c.kind || 'spawn';
      a.seconds = c.seconds != null ? c.seconds : 5;
      a.factor = c.factor != null ? c.factor : 0;
      if (c.likeN != null) a.likeN = c.likeN;
      marioFamilyWebhookAssign(a, c);
    },
  }),
});

function marioCardHtml(a) {
  const uid = esc(a.uid);
  const webhookOn = !!(a.webhookCmd && a.webhookCmd.on && a.webhookCmd.url);
  const emoji = a.kind === 'effect' ? '✨' : (a.tipo === 'enemy' ? '👾' : '🍄');
  const iconSrc = marioCatalogIconUrl(a);
  const thumbHtml = iconSrc
    ? `<img class="mc-act-ic" src="${esc(iconSrc)}" alt="" onerror="this.style.display='none'">`
    : `<span class="mc-act-em">${emoji}</span>`;
  const nameHtml = gameActSwapNameHtml(a, 'mario');
  const actionSub = a.actionName ? `<div class="mc-act-meta"><span class="mc-act-desc-inline">${esc(a.actionName)}</span></div>` : '';
  const whChip = webhookOn ? '<span class="acc-chip key mc-wh-chip">🪝 WebHook</span>' : '';
  let cfgOpts = {
    countMax: a.kind === 'effect' ? 60 : 999,
    countMin: 1,
    hideCount: a.kind === 'effect',
    countValue: a.count || 1,
  };
  if (a.kind === 'effect') {
    cfgOpts.extraConfigHtml = `
      <label class="mc-act-cfg-field"><span class="mc-act-cfg-lbl">Segundos</span><input type="number" min="1" max="60" class="mc-act-cfg-seconds" data-uid="${uid}" value="${esc(String(a.seconds || 5))}"></label>
      <label class="mc-act-cfg-field"><span class="mc-act-cfg-lbl">Tamaño (x, 0=auto)</span><input type="number" min="0" max="10" class="mc-act-cfg-factor" data-uid="${uid}" value="${esc(String(a.factor || 0))}"></label>`;
  }
  const infoExtra = `
    ${actionSub}
    ${whChip}
    ${((a.trigger || 'gift') === 'gift' || a.trigger === 'gift-any') ? mcCardComboInstantHtml(a).replace('mc-combo-instant-en', 'mario-combo-instant-en') : ''}`;
  return gameSurvivalStyleCardHtml(a, {
    settingsKey: 'marioActions',
    thumbHtml,
    nameHtml,
    infoExtraHtml: infoExtra,
    cfgOpts,
    testClass: 'mario-test',
    delClass: 'mario-del',
    cardClass: webhookOn ? 'mc-wh-card' : '',
  });
}

function renderMarioActions() {
  const wrap = document.getElementById('mario-my-actions');
  if (!wrap || !settings) return;
  registerGameActionRenderer('marioActions', renderMarioActions);
  const list = ensureMarioActions();
  if (!list.length) {
    wrap.innerHTML = '<div class="mc-empty">Aún no agregaste acciones. Pulsa <b>+ Agregar</b> en el catálogo de abajo.</div>';
    return;
  }
  wrap.innerHTML = list.map((a) => marioCardHtml(a)).join('');

  const find = (uid) => list.find((x) => x.uid === uid);
  wrap.querySelectorAll('.mario-del').forEach((b) => b.onclick = () => {
    settings.marioActions = list.filter((x) => x.uid !== b.dataset.uid);
    saveSettings();
    renderMarioActions();
    renderMarioCatalog(document.getElementById('mario-cat-search')?.value || '');
  });
  bindGameActionConfigPopovers(wrap, find, renderMarioActions, {
    countMax: 999,
    extraBind: (w, _find, savePatch) => {
      w.querySelectorAll('.mc-act-cfg-seconds').forEach((inp) => inp.onchange = () => savePatch(inp, { seconds: Math.max(1, Math.min(60, parseInt(inp.value, 10) || 5)) }));
      w.querySelectorAll('.mc-act-cfg-factor').forEach((inp) => inp.onchange = () => savePatch(inp, { factor: Math.max(0, Math.min(10, parseInt(inp.value, 10) || 0)) }));
    },
  });
  wrap.querySelectorAll('.mario-count').forEach((inp) => {
    const apply = () => {
      const a = find(inp.dataset.uid);
      if (!a) return;
      a.count = Math.max(1, Math.min(999, parseInt(inp.value, 10) || 1));
      if (a.webhookCmd?.url) a.webhookCmd.url = applyMarioWebhookQuantity(a.webhookCmd.url, a.count);
      saveSettings();
      notifyEditorRapidoActionsChanged('marioActions');
    };
    inp.oninput = apply;
    inp.onchange = apply;
  });
  wrap.querySelectorAll('.mario-combo-instant-en').forEach((c) => c.onchange = () => { const a = find(c.dataset.uid); if (!a) return; a.comboInstant = c.checked; saveSettingsKeysPatch('marioActions'); });
  bindGameSurvivalCardExtras(wrap, find, renderMarioActions, {
    settingsKey: 'marioActions',
    testClass: 'mario-test',
    onTest: (b) => {
      const a = syncMarioActionFieldsFromDom(b.dataset.uid);
      if (a) testMarioAction(a);
    },
  });
}

// Capas editables en el Editor: icono de acción + regalo/evento + x{cantidad}.
async function generateGameActionsOverlayImage({ ensureList, iconUrlFor, downloadName, emptyToast, settingsKey: sk }) {
  try { commitOpenGameActionConfig({ quiet: true, skipErSync: true }); } catch {}
  lastGameActionEditAt = Date.now();
  const all = ensureList();
  const list = (Array.isArray(all) ? all : []).filter(Boolean);
  if (!list.length) {
    toast && toast(emptyToast || 'Agrega acciones del catálogo con su regalo primero.', 'warn');
    return;
  }
  if (!tableroProCapture) toast && toast('Abriendo en Editor Pro…', 'ok');
  const settingsKey = sk || settingsKeyFromEnsureList(ensureList) || settingsKeyForActionList(all);
  if (settingsKey) {
    try {
      const g = typeof gamePresetFromSettingsKey === 'function' ? gamePresetFromSettingsKey(settingsKey) : null;
      if (g) markMcPresetDirty(g);
      saveSettingsKeysPatch(settingsKey, { flush: true });
    } catch {}
  }

  const rows = [];
  for (const a of list) {
    const actionSrc = overlayImgProxy(chosenActionImage(a) || validIconUrl(iconUrlFor(a)));
    const patch = editorRapidoPatchFromAction(a) || {};
    rows.push({
      actionSrc: actionSrc || EDITOR_OVERLAY_CLOUD_SRC,
      actionName: a.name || a.label || a.thing || 'Acción',
      actionUid: a.uid || '',
      giftSrc: patch.giftSrc || '',
      giftEmoji: patch.giftEmoji || '',
      giftName: patch.giftName || 'Regalo',
      cornerType: patch.cornerType || '',
      qty: Math.max(1, parseInt(patch.qty, 10) || 1),
    });
  }

  await openGameActionsInEditorRapido(rows, {
    name: downloadName || 'game-overlay',
    settingsKey,
  });
}

