    const giftLabel = info.giftName ? `Regalo: ${info.giftName}${units > 1 ? ` ×${units}` : ''}` : null;
    await execRelayL4dSpawn(a.thing, a.label || a.thing, name, times, params, {
      eventType,
      giftName: info.giftName,
      reason: giftLabel || eventType,
    });
