const FLAPPY_SPAWN_MAX = 100;
const FLAPPY_SECTION_ORDER = ['hazards', 'fx', 'player'];
const FLAPPY_SECTION_LABEL = { hazards: 'Obstáculos', fx: 'Efectos', player: 'Pájaro' };
const FLAPPY_SECTION_ICON = { hazards: '🌵', fx: '✨', player: '🐦' };
