const _flappyTestBusy = new Set();
async function testFlappyAction(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  const lock = String(a.uid || a.thing);
  if (_flappyTestBusy.has(lock)) return;
  _flappyTestBusy.add(lock);
  try {
    const bridge = await flappyBridgeHealthApi();
    const running = !!(bridge?.ok && (bridge?.health?.running || bridge?.running));
    if (!running) {
      toast && toast('Bridge Flappy apagado. Pulsa «Conectar» primero.', 'warn');
      return;
    }
    if (!(bridge?.health?.gameConnected || bridge?.gameConnected)) {
      toast && toast('El juego no está en línea. Ejecutar juego y esperá que se quite el candado 🔒.', 'warn');
    }
    const times = Math.max(1, Math.min(FLAPPY_SPAWN_MAX, parseInt(a.count, 10) || 1));
    const delayBefore = Math.max(0, parseInt(a.delayBefore ?? a.delayGroup, 10) || 0);
    const delayEach = Math.max(0, parseInt(a.delayEach, 10) || 0);
    if (delayBefore) await new Promise((r) => setTimeout(r, delayBefore));
    const lastR = await execGameLocal({ tipo: 'FLAPPY_SPAWN', thing: a.thing, name: 'Prueba', times, delayEach });
    const ok = !!(lastR && lastR.ok !== false);
    if (ok) {
      addEvent(`🐦 Prueba Flappy: ${esc(a.label || a.thing)}${times > 1 ? ` ×${times}` : ''}`, 'ok');
      toast && toast('Efecto enviado al juego.', 'ok');
    } else if (lastR?.error === 'evento_invalido') {
      toast && toast('Efecto no válido.', 'warn');
    } else if (lastR?.error === 'juego_no_conectado') {
      toast && toast('El juego no está conectado. Conectar + abrir FlappyBird.exe.', 'warn');
    } else if (lastR?.error === 'puerto_9967_ocupado') {
      toast && toast('Puerto 9967 ocupado. Cierra Gameriya / Interactive y pulsa Conectar.', 'warn');
    } else {
      toast && toast('¿Bridge activo y Flappy Bird abierto?', 'warn');
    }
  } finally {
    _flappyTestBusy.delete(lock);
  }
}

function syncFlappyActionFieldsFromDom(uid) {
  const list = ensureFlappyActions();
  const a = list.find((x) => x.uid === uid);
  if (!a) return null;
  const card = document.querySelector(`.mc-act-card[data-uid="${CSS.escape(uid)}"]`);
  if (!card) return a;
  const countInp = card.querySelector('.flappy-count');
  if (countInp) a.count = Math.max(1, Math.min(FLAPPY_SPAWN_MAX, parseInt(countInp.value, 10) || 1));
  return a;
}

function renderFlappyActions() {
  const wrap = document.getElementById('flappy-my-actions');
  if (!wrap || !settings) return;
  registerGameActionRenderer('flappyActions', renderFlappyActions);
  const list = ensureFlappyActions();
  if (!list.length) {
    wrap.innerHTML = '<div class="mc-empty">Aún no agregaste acciones. Elige una del catálogo.</div>';
    return;
  }
  wrap.innerHTML = list.map((a) => flappyCardHtml(a)).join('');
  const find = (uid) => list.find((x) => x.uid === uid);
  wrap.querySelectorAll('.flappy-del').forEach((b) => b.onclick = () => {
    settings.flappyActions = list.filter((x) => x.uid !== b.dataset.uid);
    saveSettings();
    renderFlappyActions();
  });
  wrap.querySelectorAll('.flappy-count').forEach((inp) => {
    const commit = (force) => {
      const a = find(inp.dataset.uid);
      if (!a) return;
      const raw = String(inp.value || '').trim();
      if (!force && raw === '') return;
      a.count = Math.max(1, Math.min(FLAPPY_SPAWN_MAX, parseInt(raw, 10) || 1));
      lastGameActionEditAt = Date.now();
      const cfgKey = `uid:${a.uid}`;
      const prev = _gameActCfgOptsMap.get(cfgKey);
      if (prev) _gameActCfgOptsMap.set(cfgKey, { ...prev, countValue: a.count });
      saveSettingsKeysPatch('flappyActions', { skipErSync: true });
    };
    inp.oninput = () => commit(false);
    inp.onchange = () => {
      commit(true);
      const a = find(inp.dataset.uid);
      if (a) inp.value = String(a.count);
      saveSettingsKeysPatch('flappyActions', { skipErSync: true, flush: true });
    };
  });
  bindGameActionConfigPopovers(wrap, find, renderFlappyActions, {
    countMax: FLAPPY_SPAWN_MAX,
    settingsKey: 'flappyActions',
    rerenderOnSave: true,
  });
  bindGameSurvivalCardExtras(wrap, find, renderFlappyActions, {
    settingsKey: 'flappyActions',
    testClass: 'flappy-test',
    onTest: (b) => {
      const a = syncFlappyActionFieldsFromDom(b.dataset.uid);
      if (a) testFlappyAction(a);
    },
  });
}

async function refreshFlappyStatus() {
  const el = document.getElementById('flappy-status');
  const btn = document.getElementById('flappy-bridge');
  if (!IS_DESKTOP) {
    if (el) el.textContent = 'Solo en la app PC.';
    return;
  }
  const cur = await flappyBridgeHealthApi();
  const running = !!(cur?.ok && cur?.health?.running);
  const gameOn = !!cur?.health?.gameConnected;
  paintBridgeConnectBtn(btn, running);
  if (el) {
    if (!running) el.textContent = cur?.health?.lastError === 'puerto_9967_ocupado'
      ? 'Puerto 9967 ocupado (cierra Gameriya / Interactive).'
      : 'Bridge apagado.';
    else if (gameOn) el.textContent = cur?.status?.hello
      ? 'Conectado · el juego está en línea. Entrá a una partida y pulsá Probar.'
      : 'Conectado · el juego está en línea.';
    else el.textContent = 'Bridge listo en :9967 · pulsá Ejecutar juego y esperá que desaparezca el candado 🔒.';
  }
}

function setupFlappyBridgeBtn() {
  if (!IS_DESKTOP) return;
  const bridgeBtn = document.getElementById('flappy-bridge');
  if (!bridgeBtn || bridgeBtn._wired) return;
  bridgeBtn._wired = true;
  paintBridgeConnectBtn(bridgeBtn, false);
  bridgeBtn.onclick = async () => {
    const ok = await runBridgeConnectFlow({
      btn: bridgeBtn,
      isConnected: async () => {
        const cur = await flappyBridgeHealthApi();
        return !!(cur?.ok && cur?.health?.running);
      },
      connect: async () => {
        const r = await ensureFlappyBridgeApi();
        return !!r.ok;
      },
    });
    if (ok) toast && toast('Bridge Flappy en :9967', 'ok');
    else toast && toast('No se pudo abrir :9967. Cierra Gameriya / Interactive.', 'warn');
    refreshFlappyStatus();
  };
}

const FLAPPY_DOWNLOAD_URL = 'https://github.com/paleteriadeyellow-tech/exe/releases/download/pvz/FlappyBird.zip';

function setupFlappyDownloadBtn() {
  const btn = document.getElementById('flappy-download');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = () => downloadMinecraftServer(FLAPPY_DOWNLOAD_URL);
}

function setupFlappyLaunchBtn() {
  const launchBtn = document.getElementById('flappy-launch');
  const pickBtn = document.getElementById('flappy-pick-exe');
  const pathInp = document.getElementById('flappy-exe-path');
  if (pathInp && settings?.flappy?.exePath && !pathInp._filled) {
    pathInp.value = settings.flappy.exePath;
    pathInp._filled = true;
  }
  if (pickBtn && !pickBtn._wired) {
    pickBtn._wired = true;
    pickBtn.onclick = async () => {
      if (!window.desktopAPI?.pickFlappyExe) {
        toast && toast('Elige el .exe solo en la app PC.', 'warn');
        return;
      }
      const p = await window.desktopAPI.pickFlappyExe();
      if (!p) return;
      if (!settings.flappy) settings.flappy = {};
      settings.flappy.exePath = p;
      if (pathInp) pathInp.value = p;
      saveSettings();
    };
  }
  if (launchBtn && !launchBtn._wired) {
    launchBtn._wired = true;
    launchBtn.onclick = async () => {
      if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
      await ensureFlappyBridgeApi();
      const exePath = pathInp?.value?.trim() || settings?.flappy?.exePath || '';
      try {
        const r = await fetch('/api/desktop/flappy-launch', {
          method: 'POST',
          credentials: 'same-origin',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ exePath }),
        }).then((x) => x.json()).catch(() => ({ ok: false }));
        if (r.ok) {
          launchBtn._lcPickedOnce = false;
          if (r.exe && settings) {
            if (!settings.flappy) settings.flappy = {};
            settings.flappy.exePath = r.exe;
            if (pathInp) pathInp.value = r.exe;
            saveSettings();
          }
          toast && toast('Juego lanzado. Si ves el candado, cerralo y pulsá Ejecutar de nuevo.', 'ok');
        } else if (r.error === 'bridge_no_disponible' || r.error === 'puerto_9967_ocupado') {
          toast && toast('No pude abrir :9967. Cerrá Gameriya / Interactive y pulsá Conectar.', 'warn');
        } else if (!launchBtn._lcPickedOnce && window.desktopAPI?.pickFlappyExe) {
          launchBtn._lcPickedOnce = true;
          const p = await window.desktopAPI.pickFlappyExe();
          if (p) {
            if (!settings.flappy) settings.flappy = {};
            settings.flappy.exePath = p;
            if (pathInp) pathInp.value = p;
            saveSettings();
            const r2 = await fetch('/api/desktop/flappy-launch', {
              method: 'POST',
              credentials: 'same-origin',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ exePath: p }),
            }).then((x) => x.json()).catch(() => ({ ok: false }));
            if (r2.ok) {
              launchBtn._lcPickedOnce = false;
              toast && toast('Juego lanzado. Si ves el candado, cerralo y pulsá Ejecutar de nuevo.', 'ok');
            } else {
              toast && toast('No se pudo lanzar con ese .exe.', 'warn');
            }
          } else {
            toast && toast('No encontré FlappyBird.exe.', 'warn');
          }
        } else {
          toast && toast('No encontré FlappyBird.exe.', 'warn');
        }
      } catch {
        toast && toast('No se pudo lanzar el juego.', 'warn');
      }
      refreshFlappyStatus();
    };
  }
}

let flappyStatusTimer = null;
function setupFlappyStatusPoll() {
  if (!IS_DESKTOP || flappyStatusTimer) return;
  const tick = () => {
    const view = document.getElementById('view-juego-flappybird');
    if (view?.classList.contains('active')) refreshFlappyStatus();
  };
  if ('requestIdleCallback' in window) requestIdleCallback(tick, { timeout: 1200 });
  else setTimeout(tick, 400);
  flappyStatusTimer = setInterval(tick, 4000);
}

function setupFlappyActionsUI() {
  const toggleAll = document.getElementById('flappy-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensureFlappyActions();
      if (!list.length) { toast && toast('Agrega acciones del catálogo.', 'warn'); return; }
      const anyOff = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = anyOff; });
      lastGameActionEditAt = Date.now();
      saveSettingsKeysPatch('flappyActions', { skipErSync: true, flush: true });
      renderFlappyActions();
    };
  }
  const genOverlayBtn = document.getElementById('flappy-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generateFlappyOverlayImage();
  }
  if (!setupFlappyActionsUI._painted) {
    setupFlappyActionsUI._painted = true;
    requestAnimationFrame(() => {
      renderFlappyActions();
      scheduleFlappyIconProbe();
    });
  } else {
    scheduleFlappyIconProbe();
  }
}

async function generateFlappyOverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensureFlappyActions(),
    iconUrlFor: (a) => flappyCatalogIconUrl(a),
    downloadName: 'flappy-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'flappyActions',
  });
}

// ===================== PvZ Fusion (MelonLoader S2E :5003) =====================
const PVZFUSION_SPAWN_MAX = 100;
const PVZFUSION_SECTION_ORDER = ['zombies', 'plants', 'sun', 'cmds'];
const PVZFUSION_SECTION_LABEL = { zombies: 'Zombies', plants: 'Plantas', sun: 'Sol y monedas', cmds: 'Comandos' };
const PVZFUSION_SECTION_ICON = { zombies: '🧟', plants: '🌱', sun: '☀️', cmds: '⚡' };
const PVZFUSION_SECTION_DESC = {
  zombies: 'IDs de Fusion 3.8.1 (almanac / Interactive)',
  plants: 'IDs de Fusion 3.8.1 (almanac / Interactive)',
  sun: 'Soles y monedas del mod :5003',
  cmds: 'Comandos del mod StreamToEarn',
};
let PVZFUSION_CATALOG = [];
function bindPvzFusionCatalogFromWindow() {
  PVZFUSION_CATALOG = Array.isArray(window.PVZFUSION_SPAWN_ENTRIES) ? window.PVZFUSION_SPAWN_ENTRIES : [];
}

function pvzFusionCatalogEntry(thing) {
  return PVZFUSION_CATALOG.find((x) => x.id === thing);
}

const PVZFUSION_ICON_V = 'pfimg2';
function pvzFusionIconFileId(id) {
  return String(id || '').replace(/:/g, '-');
}
function pvzFusionCatalogIconSrc(id) {
  const safe = pvzFusionIconFileId(id);
  if (!safe) return '';
  return `/img/pvzfusion/${safe}.png?v=${PVZFUSION_ICON_V}`;
}
function pvzFusionCatalogIconUrl(entry) {
  const id = entry?.id || entry?.thing;
  return id ? pvzFusionCatalogIconSrc(id) : '';
}
function pvzFusionCatalogIconHtml(c, cls = 'repo-cat-list-ic') {
  const em = esc(c?.emoji || '🌻');
  const rawId = c?.id || c?.thing;
  if (!rawId) return `<span class="repo-cat-list-em ${esc(cls)}">${em}</span>`;
  const src = esc(pvzFusionCatalogIconSrc(rawId));
  return `<img class="${esc(cls)}" src="${src}" alt="" loading="lazy" decoding="async" onerror="this.outerHTML='<span class=\\'repo-cat-list-em ${esc(cls)}\\'>${em}</span>'">`;
}

function ensurePvzFusionActions() {
  if (!settings) return [];
  if (!Array.isArray(settings.pvzFusionActions)) settings.pvzFusionActions = [];
  settings.pvzFusionActions = migrateGameActions(settings.pvzFusionActions, 'pvzfusion');
  for (const a of settings.pvzFusionActions) {
    const c = pvzFusionCatalogEntry(a.thing);
    if (c) {
      a.label = c.nombre;
      a.desc = c.desc;
      a.section = c.section;
    }
    const n = parseInt(a.count, 10);
    if (!Number.isFinite(n) || n < 1) a.count = 1;
    else if (n > PVZFUSION_SPAWN_MAX) a.count = PVZFUSION_SPAWN_MAX;
  }
  return settings.pvzFusionActions;
}

registerGameActSwap('pvzfusion', {
  title: 'Clic para cambiar la acción',
  heading: 'Cambiar acción',
  placeholder: 'Buscar zombie, planta, sol…',
  entries: () => (PVZFUSION_CATALOG || []).map((c) => ({
    id: c.id, name: c.nombre, desc: c.desc, iconHtml: pvzFusionCatalogIconHtml(c),
  })),
  current: (uid) => ensurePvzFusionActions().find((x) => x && x.uid === uid)?.thing,
  apply: gameActSwapApply({
    actions: ensurePvzFusionActions,
    entry: pvzFusionCatalogEntry,
    settingsKey: 'pvzFusionActions',
    render: () => renderPvzFusionActions(),
  }),
});

function pvzFusionCardHtml(a) {
  const c = pvzFusionCatalogEntry(a.thing);
  const icon = pvzFusionCatalogIconHtml(c || { id: a.thing, emoji: '🌻' }, 'mc-act-ic repo-cat-list-ic');
  const qty = Math.max(1, Math.min(PVZFUSION_SPAWN_MAX, parseInt(a.count, 10) || 1));
  return gameSurvivalStyleCardHtml(a, {
    settingsKey: 'pvzFusionActions',
    thumbHtml: icon,
    nameHtml: gameActSwapNameHtml(a, 'pvzfusion'),
    infoExtraHtml: `<label class="mc-qty-row" title="Cuántas veces se manda al juego por cada unidad del regalo.">Cantidad
      <input type="number" min="1" max="${PVZFUSION_SPAWN_MAX}" class="pvzfusion-count mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(String(qty))}"></label>`,
    cfgOpts: { countMax: PVZFUSION_SPAWN_MAX, countValue: qty },
    testClass: 'pvzfusion-test',
    delClass: 'pvzfusion-del',
  });
}

function renderPvzFusionCatalog(filter) {
  const f = (filter || '').trim().toLowerCase();
  const list = f
    ? PVZFUSION_CATALOG.filter((c) =>
      c.nombre.toLowerCase().includes(f)
      || c.id.toLowerCase().includes(f)
      || (c.desc || '').toLowerCase().includes(f)
      || (PVZFUSION_SECTION_LABEL[c.section] || '').toLowerCase().includes(f))
    : PVZFUSION_CATALOG;
  renderGameCatalogFold({
    grid: 'pvzfusion-catalog',
    stateKey: 'pvzfusion',
    filter: f,
    searchId: 'pvzfusion-cat-search',
    rerender: renderPvzFusionCatalog,
    closeModalId: 'pvzfusionCatalogModal',
    sections: buildCatalogSections(list, {
      sectionKey: 'section',
      order: PVZFUSION_SECTION_ORDER,
      labelMap: PVZFUSION_SECTION_LABEL,
      iconMap: PVZFUSION_SECTION_ICON,
      descMap: PVZFUSION_SECTION_DESC,
      searching: !!f,
    }),
    rowHtml: (c) => gameCatListBtnHtml(c.id, c.nombre, pvzFusionCatalogIconHtml(c), c.desc || c.nombre),
    onPick: addPvzFusionFromCatalog,
  });
}

function pvzFusionRowFromCatalog(c) {
  return {
    uid: 'pvzf_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    thing: c.id,
    label: c.nombre,
    desc: c.desc,
    section: c.section,
    trigger: 'gift',
    giftId: '',
    giftName: '',
    giftImage: '',
    count: 1,
    text: '',
    enabled: false,
  };
}

function addPvzFusionFromCatalog(thing) {
  const c = pvzFusionCatalogEntry(thing);
  if (!c || !settings) return;
  const row = pvzFusionRowFromCatalog(c);
  ensurePvzFusionActions().push(row);
  saveSettings();
  renderPvzFusionActions();
  renderPvzFusionCatalog(document.getElementById('pvzfusion-cat-search')?.value || '');
  const wrap = document.getElementById('pvzfusion-my-actions');
  if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  toast && toast(`Agregado: ${c.nombre}`, 'ok');
}

async function ensurePvzFusionBridgeApi() {
  try {
    const r = await fetch('/api/desktop/ensure-pvzfusion-bridge', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: '{}',
    });
    return await r.json().catch(() => ({ ok: false }));
  } catch {
    return { ok: false };
  }
}

async function pvzFusionBridgeHealthApi() {
  try {
    const r = await fetch('/api/desktop/pvzfusion-bridge-health', { credentials: 'same-origin' });
    return await r.json().catch(() => ({}));
  } catch {
    return {};
  }
}

const _pvzFusionTestBusy = new Set();
async function testPvzFusionAction(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  const lock = String(a.uid || a.thing);
  if (_pvzFusionTestBusy.has(lock)) return;
  _pvzFusionTestBusy.add(lock);
  try {
    const bridge = await pvzFusionBridgeHealthApi();
    const running = !!(bridge?.ok && (bridge?.health?.ok || bridge?.health?.running));
    if (!running) {
      toast && toast('El mod no está en :5003. Abrí PvZ Fusion + MelonLoader y entra a una partida.', 'warn');
      return;
    }
    const times = Math.max(1, Math.min(PVZFUSION_SPAWN_MAX, parseInt(a.count, 10) || 1));
    const delayBefore = Math.max(0, parseInt(a.delayBefore ?? a.delayGroup, 10) || 0);
    if (delayBefore) await new Promise((r) => setTimeout(r, delayBefore));
    const lastR = await execGameLocal({ tipo: 'PVZFUSION_SPAWN', thing: a.thing, name: 'Prueba', times });
    const ok = !!(lastR && lastR.ok !== false);
    if (ok) {
      addEvent(`🌻 Prueba Fusion: ${esc(a.label || a.thing)}${times > 1 ? ` ×${times}` : ''}`, 'ok');
      toast && toast('Enviado al juego.', 'ok');
    } else {
      toast && toast(lastR?.error === 'sin_conexion'
        ? 'No hay partida / el mod no responde en :5003.'
        : (lastR?.error || '¿Fusion abierto, MelonLoader y partida?'), 'warn');
    }
  } finally {
    _pvzFusionTestBusy.delete(lock);
  }
}

function applyPvzFusionCountValue(a, raw, force) {
  if (!a) return false;
  const s = String(raw ?? '').trim();
  if (!force && s === '') return false;
  const n = parseInt(s, 10);
  a.count = Math.max(1, Math.min(PVZFUSION_SPAWN_MAX, Number.isFinite(n) && n > 0 ? n : 1));
  const cfgKey = `uid:${a.uid}`;
  const prev = _gameActCfgOptsMap.get(cfgKey);
  if (prev) _gameActCfgOptsMap.set(cfgKey, { ...prev, countValue: a.count });
  return true;
}

function syncAllPvzFusionCountsFromDom() {
  const wrap = document.getElementById('pvzfusion-my-actions');
  if (!wrap || !settings || !Array.isArray(settings.pvzFusionActions)) return;
  wrap.querySelectorAll('.pvzfusion-count').forEach((inp) => {
    const a = settings.pvzFusionActions.find((x) => x && x.uid === inp.dataset.uid);
    if (a) applyPvzFusionCountValue(a, inp.value, false);
  });
}

function syncPvzFusionActionFieldsFromDom(uid) {
  syncAllPvzFusionCountsFromDom();
  const list = ensurePvzFusionActions();
  const a = list.find((x) => x.uid === uid);
  if (!a) return null;
  const card = document.querySelector(`.mc-act-card[data-uid="${CSS.escape(uid)}"]`);
  if (!card) return a;
  const countInp = card.querySelector('.pvzfusion-count');
  if (countInp) applyPvzFusionCountValue(a, countInp.value, true);
  return a;
}

function renderPvzFusionActions() {
  const wrap = document.getElementById('pvzfusion-my-actions');
  if (!wrap || !settings) return;
  syncAllPvzFusionCountsFromDom();
  registerGameActionRenderer('pvzFusionActions', renderPvzFusionActions);
  const list = ensurePvzFusionActions();
  if (!list.length) {
    wrap.innerHTML = '<div class="mc-empty">Aún no agregaste acciones. Elige una del catálogo.</div>';
    return;
  }
  wrap.innerHTML = list.map((a) => pvzFusionCardHtml(a)).join('');
  const find = (uid) => (settings.pvzFusionActions || []).find((x) => x && x.uid === uid);
  wrap.querySelectorAll('.pvzfusion-del').forEach((b) => b.onclick = () => {
    settings.pvzFusionActions = (settings.pvzFusionActions || []).filter((x) => x.uid !== b.dataset.uid);
    saveSettings();
    renderPvzFusionActions();
  });
  wrap.querySelectorAll('.pvzfusion-count').forEach((inp) => {
    const commit = (force) => {
      const a = find(inp.dataset.uid);
      if (!a) return;
      if (!applyPvzFusionCountValue(a, inp.value, force)) return;
      lastGameActionEditAt = Date.now();
      saveSettingsKeysPatch('pvzFusionActions', { skipErSync: true, flush: !!force });
    };
    inp.oninput = () => commit(false);
    inp.onchange = () => {
      commit(true);
      const a = find(inp.dataset.uid);
      if (a) inp.value = String(a.count);
    };
  });
  bindGameActionConfigPopovers(wrap, find, renderPvzFusionActions, {
    countMax: PVZFUSION_SPAWN_MAX,
    settingsKey: 'pvzFusionActions',
    rerenderOnSave: true,
  });
  bindGameSurvivalCardExtras(wrap, find, renderPvzFusionActions, {
    settingsKey: 'pvzFusionActions',
    testClass: 'pvzfusion-test',
    onTest: (b) => {
      const a = syncPvzFusionActionFieldsFromDom(b.dataset.uid);
      if (a) testPvzFusionAction(a);
    },
  });
}

async function refreshPvzFusionStatus() {
  const el = document.getElementById('pvzfusion-status');
  const btn = document.getElementById('pvzfusion-bridge');
  if (!IS_DESKTOP) {
    if (el) el.textContent = 'Solo en la app PC.';
    return;
  }
  const cur = await pvzFusionBridgeHealthApi();
  const running = !!(cur?.ok && (cur?.health?.ok || cur?.health?.running));
  paintBridgeConnectBtn(btn, running);
  if (el) {
    if (!running) el.textContent = 'Mod apagado. Abrí PvZ Fusion con MelonLoader y entra a una partida.';
    else el.textContent = 'Conectado · el mod responde en :5003. Enciende acciones y asigná regalos.';
  }
}

