function setupPvzFusionLaunchBtn() {
  const launchBtn = document.getElementById('pvzfusion-launch');
  const pickBtn = document.getElementById('pvzfusion-pick-exe');
  const pathInp = document.getElementById('pvzfusion-exe-path');
  if (pathInp && settings?.pvzfusion?.exePath && !pathInp._filled) {
    pathInp.value = settings.pvzfusion.exePath;
    pathInp._filled = true;
  }
  if (pickBtn && !pickBtn._wired) {
    pickBtn._wired = true;
    pickBtn.onclick = async () => {
      if (!window.desktopAPI?.pickPvzFusionExe) {
        toast && toast('Elige el .exe solo en la app PC.', 'warn');
        return;
      }
      const p = await window.desktopAPI.pickPvzFusionExe();
      if (!p) return;
      if (!settings.pvzfusion) settings.pvzfusion = {};
      settings.pvzfusion.exePath = p;
      if (pathInp) pathInp.value = p;
      saveSettings();
    };
  }
  if (launchBtn && !launchBtn._wired) {
    launchBtn._wired = true;
    launchBtn.onclick = async () => {
      if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
      const exePath = pathInp?.value?.trim() || settings?.pvzfusion?.exePath || '';
      try {
        const r = await fetch('/api/desktop/pvzfusion-launch', {
          method: 'POST',
          credentials: 'same-origin',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ exePath }),
        }).then((x) => x.json()).catch(() => ({ ok: false }));
        if (r.ok) {
          launchBtn._lcPickedOnce = false;
          if (r.exe && settings) {
            if (!settings.pvzfusion) settings.pvzfusion = {};
            settings.pvzfusion.exePath = r.exe;
            if (pathInp) pathInp.value = r.exe;
            saveSettings();
          }
          toast && toast('Juego lanzado. Entrá a una partida y pulsá Conectar.', 'ok');
        } else if (!launchBtn._lcPickedOnce && window.desktopAPI?.pickPvzFusionExe) {
          launchBtn._lcPickedOnce = true;
          const p = await window.desktopAPI.pickPvzFusionExe();
          if (p) {
            if (!settings.pvzfusion) settings.pvzfusion = {};
            settings.pvzfusion.exePath = p;
            if (pathInp) pathInp.value = p;
            saveSettings();
            const r2 = await fetch('/api/desktop/pvzfusion-launch', {
              method: 'POST',
              credentials: 'same-origin',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ exePath: p }),
            }).then((x) => x.json()).catch(() => ({ ok: false }));
            if (r2.ok) {
              launchBtn._lcPickedOnce = false;
              toast && toast('Juego lanzado. Entrá a una partida y pulsá Conectar.', 'ok');
            } else {
              toast && toast('No se pudo lanzar con ese .exe.', 'warn');
            }
          } else {
            toast && toast('No encontré PlantsVsZombiesRH.exe.', 'warn');
          }
        } else {
          toast && toast('No encontré PlantsVsZombiesRH.exe.', 'warn');
        }
      } catch {
        toast && toast('No se pudo lanzar el juego.', 'warn');
      }
      refreshPvzFusionStatus();
    };
  }
}

let pvzFusionStatusTimer = null;
function setupPvzFusionStatusPoll() {
  if (!IS_DESKTOP || pvzFusionStatusTimer) return;
  const tick = () => {
    const view = document.getElementById('view-juego-pvzfusion');
    if (view?.classList.contains('active')) refreshPvzFusionStatus();
  };
  if ('requestIdleCallback' in window) requestIdleCallback(tick, { timeout: 1200 });
  else setTimeout(tick, 400);
  pvzFusionStatusTimer = setInterval(tick, 4000);
}

function setupPvzFusionActionsUI() {
  const toggleAll = document.getElementById('pvzfusion-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensurePvzFusionActions();
      if (!list.length) { toast && toast('Agrega acciones del catálogo.', 'warn'); return; }
      const anyOff = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = anyOff; });
      lastGameActionEditAt = Date.now();
      saveSettingsKeysPatch('pvzFusionActions', { skipErSync: true, flush: true });
      renderPvzFusionActions();
    };
  }
  const genOverlayBtn = document.getElementById('pvzfusion-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generatePvzFusionOverlayImage();
  }
  if (!setupPvzFusionActionsUI._painted) {
    setupPvzFusionActionsUI._painted = true;
    requestAnimationFrame(() => renderPvzFusionActions());
  }
}

async function generatePvzFusionOverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensurePvzFusionActions(),
    iconUrlFor: (a) => pvzFusionCatalogIconSrc(a?.thing),
    downloadName: 'pvzfusion-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'pvzFusionActions',
  });
}

