function mk64CatalogEntry(thing) {
  return MK64_CATALOG.find((x) => x.id === thing);
}

const MK64_ICON_V = 'mk3';

function mk64IconFile(id) {
  const s = String(id || '').trim();
  if (!s) return '';
  const cpu = s.match(/^cpu(\d+)_(giant|tiny|normal)$/);
  if (cpu) return `cpu${cpu[1]}`;
  if (s === 'giant' || s === 'giant_off') return 'giant_on';
  if (/^freeze_player/.test(s) || /^freeze_me/.test(s)) return 'freeze_player';
  if (/^freeze_cpu/.test(s) || /^freeze_enemies/.test(s)) return 'freeze_cpu';
  if (s === 'push_left' || s === 'steer_left' || /^turn_left/.test(s)) return 'turn_left';
  if (s === 'push_right' || s === 'steer_right' || /^turn_right/.test(s)) return 'turn_right';
  if (s === 'add_laps') return 'add_lap';
  return s;
}

function mk64CatalogIconSrc(id) {
  const file = mk64IconFile(id);
  if (!file) return '';
  return `/img/mk64/${file}.png?v=${MK64_ICON_V}`;
}

function mk64CatalogIconHtml(c, cls = 'repo-cat-list-ic') {
  const em = esc(c?.emoji || '🏎️');
  const src = mk64CatalogIconSrc(c?.id);
  if (!src) return `<span class="${esc(cls)} mk64-cat-em" aria-hidden="true">${em}</span>`;
  return `<img class="${esc(cls)}" src="${esc(src)}" alt="" width="44" height="44" loading="lazy" decoding="async" fetchpriority="low" onerror="this.outerHTML='<span class=\\'repo-cat-list-em\\'>${em}</span>'">`;
}

function prefetchMk64CatalogIcons() {
  if (prefetchMk64CatalogIcons._done) return;
  prefetchMk64CatalogIcons._done = true;
  const files = new Set();
  for (const c of MK64_CATALOG) {
    const file = mk64IconFile(c.id);
    if (file) files.add(file);
  }
  const run = () => {
    files.forEach((file) => {
      const img = new Image();
      img.decoding = 'async';
      img.src = `/img/mk64/${file}.png?v=${MK64_ICON_V}`;
    });
  };
  if (typeof requestIdleCallback === 'function') requestIdleCallback(run, { timeout: 1800 });
  else setTimeout(run, 280);
}

function mk64CatalogIconUrl(entry) {
  return mk64CatalogIconSrc(entry?.id || entry?.thing);
}

function ensureMk64Actions() {
  if (!settings) return [];
  if (!Array.isArray(settings.mk64Actions)) settings.mk64Actions = [];
  settings.mk64Actions = migrateGameActions(settings.mk64Actions, 'mk64');
  for (const a of settings.mk64Actions) {
    const c = mk64CatalogEntry(a.thing);
    if (c) {
      if (!a.label) a.label = c.nombre;
      if (!a.desc) a.desc = c.desc;
      if (!a.section) a.section = c.section;
    }
    const n = parseInt(a.count, 10);
    if (!Number.isFinite(n) || n < 1) a.count = 1;
    else if (n > MK64_SPAWN_MAX) a.count = MK64_SPAWN_MAX;
  }
  return settings.mk64Actions;
}

registerGameActSwap('mk64', {
  title: 'Clic para cambiar el efecto',
  heading: 'Cambiar efecto',
  placeholder: 'Buscar ítem o efecto…',
  entries: () => (MK64_CATALOG || []).map((c) => ({
    id: c.id, name: c.nombre, desc: c.desc, iconHtml: mk64CatalogIconHtml(c),
  })),
  current: (uid) => ensureMk64Actions().find((x) => x && x.uid === uid)?.thing,
  apply: gameActSwapApply({
    actions: ensureMk64Actions,
    entry: mk64CatalogEntry,
    settingsKey: 'mk64Actions',
    render: () => renderMk64Actions(),
  }),
});

function mk64CardHtml(a) {
  const c = mk64CatalogEntry(a.thing);
  const icon = mk64CatalogIconHtml(c || { id: a.thing, emoji: '🏎️' }, 'mc-act-ic repo-cat-list-ic');
  const qty = Math.max(1, Math.min(MK64_SPAWN_MAX, parseInt(a.count, 10) || 1));
  return gameSurvivalStyleCardHtml(a, {
    settingsKey: 'mk64Actions',
    thumbHtml: icon,
    nameHtml: gameActSwapNameHtml(a, 'mk64'),
    infoExtraHtml: `<label class="mc-qty-row" title="Cuántos efectos por cada unidad del regalo / like / follow.">Cantidad
      <input type="number" min="1" max="${MK64_SPAWN_MAX}" class="mk64-count mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(String(qty))}"></label>`,
    cfgOpts: { countMax: MK64_SPAWN_MAX, countValue: qty },
    testClass: 'mk64-test',
    delClass: 'mk64-del',
  });
}

function renderMk64Catalog(filter) {
  const f = (filter || '').trim().toLowerCase();
  const list = f
    ? MK64_CATALOG.filter((c) =>
      c.nombre.toLowerCase().includes(f)
      || c.id.toLowerCase().includes(f)
      || (c.desc || '').toLowerCase().includes(f)
      || (MK64_SECTION_LABEL[c.section] || '').toLowerCase().includes(f))
    : MK64_CATALOG;
  renderGameCatalogFold({
    grid: 'mk64-catalog',
    stateKey: 'mk64',
    filter: f,
    searchId: 'mk64-cat-search',
    rerender: renderMk64Catalog,
    closeModalId: 'mk64CatalogModal',
    sections: buildCatalogSections(list, {
      sectionKey: 'section',
      order: MK64_SECTION_ORDER,
      labelMap: MK64_SECTION_LABEL,
      iconMap: MK64_SECTION_ICON,
      descMap: MK64_SECTION_DESC,
      searching: !!f,
    }),
    rowHtml: (c) => gameCatListBtnHtml(c.id, c.nombre, mk64CatalogIconHtml(c), c.desc || c.nombre),
    onPick: addMk64FromCatalog,
  });
}

function mk64RowFromCatalog(c) {
  return {
    uid: 'mk64_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    thing: c.id,
    label: c.nombre,
    desc: c.desc,
    section: c.section,
    trigger: 'gift',
    giftId: '',
    giftName: '',
    giftImage: '',
    count: 1,
    text: '',
    enabled: false,
  };
}

function addMk64FromCatalog(thing) {
  const c = mk64CatalogEntry(thing);
  if (!c || !settings) return;
  closeGameCatalogModal('mk64CatalogModal');
  const row = mk64RowFromCatalog(c);
  ensureMk64Actions().push(row);
  toast && toast(`Agregado: ${c.nombre}`, 'ok');
  requestAnimationFrame(() => {
    renderMk64Actions();
    saveSettingsKeysPatch('mk64Actions', { skipErSync: true, flush: true });
    const wrap = document.getElementById('mk64-my-actions');
    if (wrap) wrap.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  });
}

async function ensureMk64BridgeApi() {
  try {
    const r = await fetch('/api/desktop/ensure-mk64-bridge', {
      method: 'POST',
      credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: '{}',
    });
    return await r.json().catch(() => ({ ok: false }));
  } catch {
    return { ok: false };
  }
}

async function mk64BridgeHealthApi() {
  try {
    const r = await fetch('/api/desktop/mk64-bridge-health', { credentials: 'same-origin' });
    return await r.json().catch(() => ({}));
  } catch {
    return {};
  }
}

const _mk64TestBusy = new Set();
async function testMk64Action(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  const lock = String(a.uid || a.thing);
  if (_mk64TestBusy.has(lock)) return;
  _mk64TestBusy.add(lock);
  try {
    const bridge = await mk64BridgeHealthApi();
    const running = !!(bridge?.ok && (bridge?.health?.running || bridge?.running));
    if (!running) {
      toast && toast('Bridge MK64 apagado. Pulsa «Conectar» primero.', 'warn');
      return;
    }
    if (!(bridge?.health?.gameConnected || bridge?.gameConnected)) {
      toast && toast('El Lua no late. Ejecutar BizHawk, cargá la ROM y entra a una carrera.', 'warn');
    }
    const times = Math.max(1, Math.min(MK64_SPAWN_MAX, parseInt(a.count, 10) || 1));
    const delayBefore = Math.max(0, parseInt(a.delayBefore ?? a.delayGroup, 10) || 0);
    const delayEach = Math.max(0, parseInt(a.delayEach, 10) || 0);
    if (delayBefore) await new Promise((r) => setTimeout(r, delayBefore));
    const lastR = await execGameLocal({ tipo: 'MK64_SPAWN', thing: a.thing, name: 'Prueba', times, delayEach });
    const ok = !!(lastR && lastR.ok !== false);
    if (ok) {
      addEvent(`🏎️ Prueba MK64: ${esc(a.label || a.thing)}${times > 1 ? ` ×${times}` : ''}`, 'ok');
      toast && toast('Efecto enviado a BizHawk.', 'ok');
    } else if (lastR?.error === 'evento_invalido') {
      toast && toast('Efecto no válido.', 'warn');
    } else if (lastR?.error === 'juego_no_conectado') {
      toast && toast('BizHawk no está con el Lua Livecoins. Conectar + Ejecutar y entra a una carrera.', 'warn');
    } else if (lastR?.error === 'puerto_9971_ocupado') {
      toast && toast('Puerto 9971 ocupado. Cierra Interactive y pulsa Conectar.', 'warn');
    } else {
      toast && toast('¿Bridge activo y EmuHawk con el Lua Livecoins?', 'warn');
    }
  } finally {
    _mk64TestBusy.delete(lock);
  }
}

function syncMk64ActionFieldsFromDom(uid) {
  const list = ensureMk64Actions();
  const a = list.find((x) => x.uid === uid);
  if (!a) return null;
  const card = document.querySelector(`.mc-act-card[data-uid="${CSS.escape(uid)}"]`);
  if (!card) return a;
  const countInp = card.querySelector('.mk64-count');
  if (countInp) a.count = Math.max(1, Math.min(MK64_SPAWN_MAX, parseInt(countInp.value, 10) || 1));
  return a;
}

function renderMk64Actions() {
  const wrap = document.getElementById('mk64-my-actions');
  if (!wrap || !settings) return;
  registerGameActionRenderer('mk64Actions', renderMk64Actions);
  const list = ensureMk64Actions();
  if (!list.length) {
    wrap.innerHTML = '<div class="mc-empty">Aún no agregaste acciones. Elige una del catálogo.</div>';
    return;
  }
  wrap.innerHTML = list.map((a) => mk64CardHtml(a)).join('');
  const find = (uid) => list.find((x) => x.uid === uid);
  wrap.querySelectorAll('.mk64-del').forEach((b) => b.onclick = () => {
    settings.mk64Actions = list.filter((x) => x.uid !== b.dataset.uid);
    saveSettings();
    renderMk64Actions();
  });
  wrap.querySelectorAll('.mk64-count').forEach((inp) => {
    const commit = (force) => {
      const a = find(inp.dataset.uid);
      if (!a) return;
      const raw = String(inp.value || '').trim();
      if (!force && raw === '') return;
      a.count = Math.max(1, Math.min(MK64_SPAWN_MAX, parseInt(raw, 10) || 1));
      lastGameActionEditAt = Date.now();
      const cfgKey = `uid:${a.uid}`;
      const prev = _gameActCfgOptsMap.get(cfgKey);
      if (prev) _gameActCfgOptsMap.set(cfgKey, { ...prev, countValue: a.count });
      saveSettingsKeysPatch('mk64Actions', { skipErSync: true });
    };
    inp.oninput = () => commit(false);
    inp.onchange = () => {
      commit(true);
      const a = find(inp.dataset.uid);
      if (a) inp.value = String(a.count);
      saveSettingsKeysPatch('mk64Actions', { skipErSync: true, flush: true });
    };
    inp.onblur = () => {
      commit(true);
      const a = find(inp.dataset.uid);
      if (a) inp.value = String(a.count);
    };
  });
  bindGameActionConfigPopovers(wrap, find, renderMk64Actions, {
    countMax: MK64_SPAWN_MAX,
    settingsKey: 'mk64Actions',
    rerenderOnSave: true,
  });
  bindGameSurvivalCardExtras(wrap, find, renderMk64Actions, {
    settingsKey: 'mk64Actions',
    testClass: 'mk64-test',
    onTest: (b) => {
      const a = syncMk64ActionFieldsFromDom(b.dataset.uid);
      if (a) testMk64Action(a);
    },
  });
}

async function refreshMk64Status() {
  const el = document.getElementById('mk64-status');
  const btn = document.getElementById('mk64-bridge');
  if (!IS_DESKTOP) {
    if (el) el.textContent = 'Solo en la app PC.';
    return;
  }
  const cur = await mk64BridgeHealthApi();
  const running = !!(cur?.ok && cur?.health?.running);
  const gameOn = !!cur?.health?.gameConnected;
  paintBridgeConnectBtn(btn, running);
  if (el) {
    if (!running) el.textContent = cur?.health?.lastError === 'puerto_9971_ocupado'
      ? 'Puerto 9971 ocupado (cierra Interactive).'
      : 'Bridge apagado.';
    else if (gameOn) el.textContent = 'Conectado · el Lua está vivo. Entrá a una carrera y pulsá Probar.';
    else el.textContent = 'Bridge listo en :9971 · pulsá Ejecutar y esperá que BizHawk cargue el Lua.';
  }
}

function setupMk64BridgeBtn() {
  if (!IS_DESKTOP) return;
  const bridgeBtn = document.getElementById('mk64-bridge');
  if (!bridgeBtn || bridgeBtn._wired) return;
  bridgeBtn._wired = true;
  paintBridgeConnectBtn(bridgeBtn, false);
  bridgeBtn.onclick = async () => {
    const ok = await runBridgeConnectFlow({
      btn: bridgeBtn,
      isConnected: async () => {
        const cur = await mk64BridgeHealthApi();
        return !!(cur?.ok && cur?.health?.running);
      },
      connect: async () => {
        const r = await ensureMk64BridgeApi();
        return !!r.ok;
      },
    });
    if (ok) toast && toast('Bridge MK64 en :9971', 'ok');
    else toast && toast('No se pudo abrir :9971. Cierra Interactive.', 'warn');
    refreshMk64Status();
  };
}

const MK64_DOWNLOAD_URL = 'https://github.com/paleteriadeyellow-tech/exe/releases/download/pvz/BizHawk.con.MarioKart64.rar';

function applyMk64LaunchPaths(r) {
  if (!r?.ok) return;
  if (!settings.mk64) settings.mk64 = {};
  if (r.hawk) settings.mk64.hawkPath = r.hawk;
  if (r.rom) settings.mk64.romPath = r.rom;
  saveSettings();
}

function mk64LaunchErrorToast(r) {
  const err = String(r?.error || '');
  if (err === 'bridge_no_disponible' || err === 'puerto_9971_ocupado') {
    toast && toast('No pude abrir :9971. Cerrá Interactive y pulsá Conectar.', 'warn');
  } else if (err === 'sin_rom') {
    toast && toast('No encontré la ROM. Pulsá Ejecutar de nuevo (necesita internet la 1ª vez).', 'warn');
  } else if (/7-Zip|WinRAR|\.rar|descomprim/i.test(err)) {
    toast && toast(err, 'warn');
  } else if (err) {
    toast && toast(err, 'warn');
  } else {
    toast && toast('No se pudo abrir Mario Kart 64. Pulsá Ejecutar de nuevo.', 'warn');
  }
}

function setupMk64LaunchBtn() {
  const launchBtn = document.getElementById('mk64-launch');
  if (launchBtn && !launchBtn._wired) {
    launchBtn._wired = true;
    launchBtn.onclick = async () => {
      if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
      await ensureMk64BridgeApi();
      try {
        launchBtn.disabled = true;
        const r = await runGameModInstallWithProgress('mk64', () => fetch('/api/desktop/mk64-launch', {
          method: 'POST',
          credentials: 'same-origin',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ installIfMissing: true, url: MK64_DOWNLOAD_URL }),
        }).then((x) => x.json()).catch(() => ({ ok: false })), {
          installing: 'Descargando y abriendo Mario Kart 64…',
          done: 'BizHawk abierto',
          fail: 'No se pudo abrir MK64',
        });
        if (r?.ok) {
          applyMk64LaunchPaths(r);
          toast && toast('BizHawk lanzado. Entrá a una carrera y encendé las acciones.', 'ok');
        } else {
          mk64LaunchErrorToast(r);
        }
      } catch (e) {
        toast && toast(e?.message || 'No se pudo lanzar BizHawk.', 'warn');
      } finally {
        launchBtn.disabled = false;
      }
      refreshMk64Status();
    };
  }
}

let mk64StatusTimer = null;
function setupMk64StatusPoll() {
  if (!IS_DESKTOP || mk64StatusTimer) return;
  const tick = () => {
    const view = document.getElementById('view-juego-mk64');
    if (view?.classList.contains('active')) refreshMk64Status();
  };
  if ('requestIdleCallback' in window) requestIdleCallback(tick, { timeout: 1200 });
  else setTimeout(tick, 400);
  mk64StatusTimer = setInterval(tick, 4000);
}

function setupMk64ActionsUI() {
  const toggleAll = document.getElementById('mk64-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensureMk64Actions();
      if (!list.length) { toast && toast('Agrega acciones del catálogo.', 'warn'); return; }
      const anyOff = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = anyOff; });
      lastGameActionEditAt = Date.now();
      saveSettingsKeysPatch('mk64Actions', { skipErSync: true, flush: true });
      renderMk64Actions();
    };
  }
  const genOverlayBtn = document.getElementById('mk64-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generateMk64OverlayImage();
  }
  if (!setupMk64ActionsUI._painted) {
    setupMk64ActionsUI._painted = true;
    requestAnimationFrame(() => renderMk64Actions());
  }
  prefetchMk64CatalogIcons();
}

async function generateMk64OverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensureMk64Actions(),
    iconUrlFor: (a) => mk64CatalogIconUrl(a),
    downloadName: 'mk64-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'mk64Actions',
  });
}

