window.getEditorGamePackById = function getEditorGamePackById(id) {
  const key = String(id || '');
  if (!key) return null;
  if (_editorGamePackByIdCache.has(key)) return _editorGamePackByIdCache.get(key);
  const pack = _buildEditorGamePack(key);
  if (!pack || !Array.isArray(pack.items) || !pack.items.length) return null;
  _editorGamePackByIdCache.set(key, pack);
  return pack;
};

/** Catálogos que se cargan al abrir su pestaña (REPO, PvZ Fusion, GTA V): el Editor los pide antes de listar. */
let _editorLazyCatalogsPromise = null;
window.ensureEditorGameCatalogs = function ensureEditorGameCatalogs() {
  if (!_editorLazyCatalogsPromise) {
    const step = async (src, bind) => {
      try { await loadGameCatalogScript(src); } catch { /* sin archivo: se omite ese juego */ }
      try { bind(); } catch { /* ignore */ }
    };
    _editorLazyCatalogsPromise = Promise.all([
      step('/js/repo-catalog-data.js?v=2', () => bindRepoCatalogFromWindow()),
      step('/js/pvzfusion-catalog.js?v=pf3', () => bindPvzFusionCatalogFromWindow()),
      step('/js/gtavkoth-ramp-vehicles.js', () => rebuildGtavKothCatalog()),
      step('/js/gtavchaos-spawn-catalog.js', () => bindGtavChaosCatalogFromWindow()),
      step('/js/gtavchiliad-spawn-catalog.js?v=chiliad7', () => bindGtavChiliadCatalogFromWindow()),
      (async () => { try { if (!SMB3_CATALOG.length) await loadSmb3Catalog(); } catch { /* ignore */ } })(),
    ]).then(() => {
      // se arman de nuevo con los catálogos completos
      _editorGamePackByIdCache.clear();
      _editorGamePacksAllCache = null;
    });
    _editorLazyCatalogsPromise.catch(() => { _editorLazyCatalogsPromise = null; });
  }
  return _editorLazyCatalogsPromise;
};

window.getEditorGamePacks = function getEditorGamePacks() {
  if (_editorGamePacksAllCache) return _editorGamePacksAllCache;
  const packs = window.getEditorGamePackList().map((row) => window.getEditorGamePackById(row.id)).filter(Boolean);
  _editorGamePacksAllCache = packs;
  return packs;
};


