async function biteBridgeHealthApi() {
  const r = await fetch('/api/desktop/bite-bridge-health', { credentials: 'same-origin' });
  return r.json();
}
async function ensureBiteBridgeApi() {
  const r = await fetch('/api/desktop/ensure-bite-bridge', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: '{}' });
  return r.json();
}
async function testBiteAction(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  syncGameCardQtyFromDom(a, 'biteActions');
  const bridge = await biteBridgeHealthApi().catch(() => null);
  if (!(bridge?.ok && bridge?.health?.running)) {
    toast && toast('Pulsa Ejecutar juego primero.', 'warn');
    return;
  }
  if (!bridge?.health?.gameConnected) {
    toast && toast('Abre el juego con Ejecutar juego.', 'warn');
  }
  const lastR = await execGameLocal({ tipo: 'BITE_SPAWN', thing: a.thing, name: 'Prueba', times: gameQtyForExec(a.count) });
  if (lastR && lastR.ok !== false) toast && toast('Enviado a Bite Arena.', 'ok');
  else if (lastR?.error === 'juego_no_conectado') toast && toast('El juego no está abierto. Pulsa Ejecutar juego.', 'warn');
  else toast && toast(lastR?.error || 'No se pudo enviar', 'warn');
}
function renderBiteActions() {
  const wrap = document.getElementById('bite-my-actions');
  if (!wrap) return;
  registerGameActionRenderer('biteActions', renderBiteActions);
  const list = ensureBiteActions();
  wrap.innerHTML = list.map(biteCardHtml).join('') || '<p class="mc-empty">Todavía no hay acciones. Crea una y elige el regalo.</p>';
  wrap.querySelectorAll('.bite-del').forEach((b) => {
    b.onclick = () => {
      ensureBiteActions();
      removeGameActions('biteActions', (x) => x.uid !== b.dataset.uid, renderBiteActions);
    };
  });
  wrap.querySelectorAll('.bite-count').forEach((inp) => {
    bindInstantGameQty(inp, () => ensureBiteActions().find((x) => x.uid === inp.dataset.uid), 'biteActions');
  });
  const find = (uid) => ensureBiteActions().find((x) => x.uid === uid);
  bindGameActionConfigPopovers(wrap, find, renderBiteActions, { settingsKey: 'biteActions', rerenderOnSave: true });
  bindGameSurvivalCardExtras(wrap, find, renderBiteActions, {
    settingsKey: 'biteActions',
    testClass: 'bite-test',
    onTest: (b) => {
      const a = find(b.dataset.uid);
      if (a) testBiteAction(a);
    },
  });
}
/* Modo (individual / equipos) y duración de la ronda: se guardan en esta PC. */
function biteLaunchOpts() {
  let teams = false, secs = 180;
  try {
    teams = localStorage.getItem('lc.bite.teams') === '1';
    secs = Math.max(30, Math.min(3600, parseInt(localStorage.getItem('lc.bite.secs'), 10) || 180));
  } catch {}
  return { teams, secs };
}
function setupBiteOptions() {
  const o = biteLaunchOpts();
  const solo = document.getElementById('bite-mode-solo');
  const teams = document.getElementById('bite-mode-teams');
  const secs = document.getElementById('bite-secs');
  const paint = (t) => {
    if (solo) solo.classList.toggle('is-on', !t);
    if (teams) teams.classList.toggle('is-on', !!t);
  };
  paint(o.teams);
  const setTeams = (t) => {
    try { localStorage.setItem('lc.bite.teams', t ? '1' : '0'); } catch {}
    paint(t);
  };
  if (solo && !solo._wired) { solo._wired = true; solo.onclick = () => setTeams(false); }
  if (teams && !teams._wired) { teams._wired = true; teams.onclick = () => setTeams(true); }
  if (secs) {
    secs.value = String(o.secs);
    if (!secs._wired) {
      secs._wired = true;
      secs.onchange = () => {
        const v = Math.max(30, Math.min(3600, parseInt(secs.value, 10) || 180));
        secs.value = String(v);
        try { localStorage.setItem('lc.bite.secs', String(v)); } catch {}
      };
    }
  }
}
function setupBiteBridgeBtn() {
  const btn = document.getElementById('bite-bridge');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    btn.disabled = true;
    try {
      const r = await ensureBiteBridgeApi();
      paintBridgeConnectBtn(btn, !!(r && r.ok));
      toast && toast(r && r.ok ? 'Bite Arena conectado. Ahora Ejecutar juego.' : 'No se pudo conectar', r && r.ok ? 'ok' : 'warn');
    } finally { btn.disabled = false; }
  };
}
function setupBiteLaunchBtn() {
  setupBiteOptions();
  const btn = document.getElementById('bite-launch');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    await ensureBiteBridgeApi().catch(() => {});
    const o = biteLaunchOpts();
    if (window.desktopAPI?.openBite) {
      const r = await window.desktopAPI.openBite(o);
      toast && toast(r && r.ok !== false ? 'Bite Arena abierto' : 'No se pudo abrir el juego', r && r.ok !== false ? 'ok' : 'warn');
      return;
    }
    if (window.desktopAPI) {
      toast && toast('Cierra Livecoins y ábrelo otra vez para usar la ventana del juego.', 'warn');
      return;
    }
    window.open(new URL(`/bite-arena/index.html?overlay=1&lc=1&teams=${o.teams ? 1 : 0}&secs=${o.secs}`, location.origin).href, '_blank', 'noopener,noreferrer');
  };
}
function setupBiteStatusPoll() {
  if (setupBiteStatusPoll._on) return;
  setupBiteStatusPoll._on = true;
  const tick = async () => {
    const el = document.getElementById('bite-status');
    const btn = document.getElementById('bite-bridge');
    if (!el && !btn) return;
    if (!(el || btn).closest(".view.active") || document.hidden) return; // pestaña cerrada: no consultar
    const cur = await biteBridgeHealthApi().catch(() => null);
    const running = !!(cur?.ok && cur?.health?.running);
    const gameOn = !!cur?.health?.gameConnected;
    paintBridgeConnectBtn(btn, running);
    if (el) el.textContent = !running ? 'Pulsa Ejecutar juego.' : (gameOn ? 'Juego abierto. El chat, los likes y los regalos entran.' : 'Pulsa Ejecutar juego.');
  };
  setInterval(tick, 4000);
  // Al volver a la pestaña del juego, refrescar ya (no esperar 4 s).
  document.addEventListener('click', (e) => { if (e.target.closest?.('.nav-item, [data-view], [data-game]')) setTimeout(tick, 250); });
  tick();
}
/* Solo para probar: mete varias pelotas con nombres de prueba (tamaños al azar). */
async function biteAddTestBalls(n = 10) {
  if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  const bridge = await biteBridgeHealthApi().catch(() => null);
  if (!bridge?.health?.gameConnected) { toast && toast('Primero pulsa Ejecutar juego.', 'warn'); return; }
  const sizes = ['small', 'small', 'small', 'medium', 'medium', 'big'];
  const names = ['Luna', 'Kai', 'Nico', 'Sol', 'Mati', 'Vale', 'Alex', 'Ren', 'Ivy', 'Zoe', 'Max', 'Noa', 'Leo', 'Mia'];
  let sent = 0;
  for (let i = 0; i < n; i++) {
    const name = `${names[Math.floor(Math.random() * names.length)]}${Math.floor(Math.random() * 900) + 100}`;
    const thing = sizes[Math.floor(Math.random() * sizes.length)];
    const r = await execGameLocal({ tipo: 'BITE_SPAWN', thing, name, times: 1 }).catch(() => null);
    if (r && r.ok !== false) sent++;
  }
  toast && toast(sent ? `${sent} pelotas de prueba en la arena` : 'No se pudieron meter las pelotas', sent ? 'ok' : 'warn');
}
function setupBiteActionsUI() {
  const testBalls = document.getElementById('bite-test-balls');
  if (testBalls && !testBalls._wired) {
    testBalls._wired = true;
    testBalls.onclick = async () => {
      testBalls.disabled = true;
      try { await biteAddTestBalls(10); } finally { testBalls.disabled = false; }
    };
  }
  const open = document.getElementById('bite-open-catalog');
  if (open && !open._wired) {
    open._wired = true;
    open.onclick = () => {
      const modal = document.getElementById('biteCatalogModal');
      if (modal) modal.classList.remove('hidden');
      renderBiteCatalog('');
    };
  }
  const toggleAll = document.getElementById('bite-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensureBiteActions();
      const on = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = on; });
      lastGameActionEditAt = Date.now();
      try { recentGameActionEditKeys.add('biteActions'); } catch {}
      saveSettingsKeysPatch('biteActions', { flush: true, skipErSync: true });
      renderBiteActions();
    };
  }
  const genOverlayBtn = document.getElementById('bite-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generateBiteOverlayImage();
  }
  renderBiteActions();
}

async function generateBiteOverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensureBiteActions(),
    iconUrlFor: (a) => biteIconSrc(a?.thing),
    downloadName: 'bite-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'biteActions',
  });
}

