const SUPERMARKET_SECTION_ORDER = ['clientes', 'tienda', 'basura'];
const SUPERMARKET_SECTION_LABEL = { clientes: 'Clientes y personajes', tienda: 'Tienda y dinero', basura: 'Basura' };
const SUPERMARKET_SECTION_ICON = { clientes: '🧑‍🤝‍🧑', tienda: '🛒', basura: '🗑️' };
const SUPERMARKET_SECTION_DESC = { clientes: 'Gente que entra, sale o aparece', tienda: 'Dinero, puntos, cajas y letrero', basura: 'Ensuciar o limpiar' };
function supermarketCatalogEntry(thing) {
  return SUPERMARKET_CATALOG.find((x) => x.id === thing);
}
/* Íconos propios: public/img/supermarket/<id>.png (íconos de la interfaz del juego sobre fichas de color). */
const SUPERMARKET_ICON_V = 'sm1';
function supermarketIconSrc(id) {
  const raw = String(id || '').trim();
  return raw ? `/img/supermarket/${raw}.png?v=${SUPERMARKET_ICON_V}` : '';
}
function supermarketIcon(c, cls = 'repo-cat-list-ic') {
  const em = esc((c && c.emoji) || '🛒');
  if (!c || !c.id) return `<span class="${esc(cls)}">${em}</span>`;
  const fallback = `this.outerHTML='<span class=\\'repo-cat-list-em\\'>${em}</span>'`;
  return `<img class="${esc(cls)}" src="${esc(supermarketIconSrc(c.id))}" alt="" loading="lazy" decoding="async" onerror="${fallback}">`;
}
function supermarketErrorText(r) {
  const e = String(r?.error || '');
  if (e === 'not_in_game') return 'entra a tu supermercado';
  if (e === 'sin_clientes') return 'no hay clientes en la tienda';
  if (e === 'sin_productos') return 'pon productos en los estantes y abre la tienda (sin productos no llegan clientes)';
  if (e === 'not_host') return 'solo funciona en la partida que tú creas (anfitrión)';
  if (e === 'bad_key') return 'reinstala el mod desde Livecoins (Instalar Mod)';
  if (/fetch|ECONNREFUSED|abort|timeout/i.test(e)) return 'abre el juego (con el mod de Livecoins instalado)';
  return e || 'falló';
}
function ensureSupermarketActions() {
  if (!settings.supermarketActions) settings.supermarketActions = [];
  for (const a of settings.supermarketActions) {
    const c = supermarketCatalogEntry(a.thing);
    if (c) {
      if (!a.label) a.label = c.nombre;
      if (!a.desc) a.desc = c.desc;
      if (c.amount != null && (a.amount == null || a.amount === '')) a.amount = c.amount;
      if (c.text != null && a.smText == null) a.smText = c.text;
    }
    keepStoredGameQty(a, 1);
  }
  return settings.supermarketActions;
}
registerGameActSwap('supermarket', {
  title: 'Clic para cambiar la acción',
  heading: 'Cambiar acción',
  placeholder: 'Buscar…',
  entries: () => SUPERMARKET_CATALOG.map((c) => ({ id: c.id, name: c.nombre, desc: c.desc, iconHtml: supermarketIcon(c) })),
  current: (uid) => ensureSupermarketActions().find((x) => x && x.uid === uid)?.thing,
  apply: gameActSwapApply({
    actions: ensureSupermarketActions,
    entry: supermarketCatalogEntry,
    settingsKey: 'supermarketActions',
    render: () => renderSupermarketActions(),
  }),
});
function supermarketCardHtml(a) {
  const c = supermarketCatalogEntry(a.thing);
  const qty = gameQtyShown(a.count);
  let extra = `<label class="mc-qty-row" title="Cuántas veces">Veces
      <input type="number" min="1" max="50" class="sm-count mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(qty)}"></label>`;
  if (c && c.amount != null) {
    extra += `<label class="mc-qty-row" title="Cantidad por vez">${esc(c.amountLabel || 'Cantidad')}
      <input type="number" min="1" max="1000000" class="sm-amount mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(a.amount ?? c.amount)}"></label>`;
  }
  if (c && c.text != null) {
    extra += `<label class="mc-qty-row sm-text-row" title="{user} = quien mandó el regalo">Texto
      <input type="text" maxlength="60" class="sm-text" data-uid="${esc(a.uid)}" value="${esc(a.smText ?? c.text)}"></label>`;
  }
  return gameSurvivalStyleCardHtml(a, {
    settingsKey: 'supermarketActions',
    thumbHtml: supermarketIcon(c || { emoji: '🛒' }, 'mc-act-ic repo-cat-list-ic'),
    nameHtml: gameActSwapNameHtml(a, 'supermarket'),
    infoExtraHtml: extra,
    cfgOpts: { countValue: qty },
    testClass: 'sm-test',
    delClass: 'sm-del',
  });
}
function renderSupermarketCatalog(filter) {
  const f = (filter || '').trim().toLowerCase();
  const list = f
    ? SUPERMARKET_CATALOG.filter((c) => c.nombre.toLowerCase().includes(f) || c.id.includes(f) || (c.desc || '').toLowerCase().includes(f))
    : SUPERMARKET_CATALOG;
  renderGameCatalogFold({
    grid: 'supermarket-catalog',
    stateKey: 'supermarket',
    filter: f,
    searchId: 'supermarket-cat-search',
    rerender: renderSupermarketCatalog,
    closeModalId: 'supermarketCatalogModal',
    sections: buildCatalogSections(list, {
      sectionKey: 'section',
      order: SUPERMARKET_SECTION_ORDER,
      labelMap: SUPERMARKET_SECTION_LABEL,
      iconMap: SUPERMARKET_SECTION_ICON,
      descMap: SUPERMARKET_SECTION_DESC,
      searching: !!f,
    }),
    rowHtml: (c) => gameCatListBtnHtml(c.id, c.nombre, supermarketIcon(c), c.desc || c.nombre),
    onPick: addSupermarketFromCatalog,
  });
}
function addSupermarketFromCatalog(thing) {
  const c = supermarketCatalogEntry(thing);
  if (!c || !settings) return;
  const a = {
    uid: 'sm_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    thing: c.id,
    label: c.nombre,
    desc: c.desc,
    section: c.section,
    trigger: 'gift',
    giftId: '',
    giftName: '',
    giftImage: '',
    count: 1,
    text: '',
    enabled: false,
  };
  if (c.amount != null) a.amount = c.amount;
  if (c.text != null) a.smText = c.text;
  ensureSupermarketActions().push(a);
  lastGameActionEditAt = Date.now();
  try { recentGameActionEditKeys.add('supermarketActions'); } catch {}
  saveSettingsKeysPatch('supermarketActions', { flush: true, skipErSync: true });
  renderSupermarketActions();
  renderSupermarketCatalog(document.getElementById('supermarket-cat-search')?.value || '');
  toast && toast(`Agregado: ${c.nombre}`, 'ok');
}
async function supermarketStatusApi() {
  const r = await fetch('/api/desktop/supermarket-status', { credentials: 'same-origin' });
  return r.json();
}
async function supermarketPost(path, body) {
  const r = await fetch(`/api/desktop/${path}`, {
    method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}),
  });
  return r.json();
}
async function testSupermarketAction(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  syncGameCardQtyFromDom(a, 'supermarketActions');
  const st = await supermarketStatusApi().catch(() => null);
  if (!st?.http_ok) {
    toast && toast(st?.mod_installed ? 'Abre Supermarket Together y entra a tu supermercado.' : 'Pulsa Instalar Mod con el juego cerrado.', 'warn');
    return;
  }
  const r = await execGameLocal({
    tipo: 'SUPERMARKET_SPAWN', thing: a.thing, name: 'Prueba', times: gameQtyForExec(a.count),
    amount: a.amount, text: a.smText,
  });
  if (r && r.ok !== false) toast && toast('Enviado a Supermarket Together.', 'ok');
  else toast && toast(`Supermarket Together: ${supermarketErrorText(r)}`, 'warn');
}
function renderSupermarketActions() {
  const wrap = document.getElementById('supermarket-my-actions');
  if (!wrap) return;
  registerGameActionRenderer('supermarketActions', renderSupermarketActions);
  const list = ensureSupermarketActions();
  wrap.innerHTML = list.map(supermarketCardHtml).join('') || '<p class="mc-empty">Todavía no hay acciones. Crea una y elige el regalo.</p>';
  const find = (uid) => ensureSupermarketActions().find((x) => x.uid === uid);
  const saveField = () => {
    lastGameActionEditAt = Date.now();
    try { recentGameActionEditKeys.add('supermarketActions'); } catch {}
    saveSettingsKeysPatch('supermarketActions', { skipErSync: true });
  };
  wrap.querySelectorAll('.sm-del').forEach((b) => {
    b.onclick = () => {
      ensureSupermarketActions();
      removeGameActions('supermarketActions', (x) => x.uid !== b.dataset.uid, renderSupermarketActions);
    };
  });
  wrap.querySelectorAll('.sm-count').forEach((inp) => {
    bindInstantGameQty(inp, () => find(inp.dataset.uid), 'supermarketActions');
  });
  wrap.querySelectorAll('.sm-amount').forEach((inp) => {
    inp.onchange = () => {
      const a = find(inp.dataset.uid);
      if (!a) return;
      a.amount = Math.max(1, Math.min(1000000, Number(inp.value) || 1));
      inp.value = a.amount;
      saveField();
    };
  });
  wrap.querySelectorAll('.sm-text').forEach((inp) => {
    inp.onchange = () => {
      const a = find(inp.dataset.uid);
      if (!a) return;
      a.smText = String(inp.value || '').slice(0, 60);
      saveField();
    };
  });
  bindGameActionConfigPopovers(wrap, find, renderSupermarketActions, { settingsKey: 'supermarketActions', rerenderOnSave: true });
  bindGameSurvivalCardExtras(wrap, find, renderSupermarketActions, {
    settingsKey: 'supermarketActions',
    testClass: 'sm-test',
    onTest: (b) => {
      const a = find(b.dataset.uid);
      if (a) testSupermarketAction(a);
    },
  });
}
/* Estado del mod: instalado, juego abierto, dentro del súper y si eres el anfitrión. */
async function refreshSupermarketStatus() {
  const el = document.getElementById('supermarket-status');
  const dirInp = document.getElementById('supermarket-game-dir');
  const st = await supermarketStatusApi().catch(() => null);
  if (dirInp && st?.dir && document.activeElement !== dirInp) dirInp.value = st.dir;
  const ver = document.getElementById('supermarket-mod-ver');
  if (ver && st?.version) ver.textContent = `Versión: ${st.version}`;
  if (!el) return st;
  const parts = [];
  if (!st) parts.push('<span class="mari0-st-warn">Sin respuesta de Livecoins</span>');
  else if (!st.dir) parts.push('<span class="mari0-st-warn">No encontré el juego · elige su carpeta</span>');
  else if (!st.mod_installed) parts.push('<span class="mari0-st-warn">Mod no instalado · cierra el juego y pulsa Instalar Mod</span>');
  else if (!st.http_ok) parts.push('<span class="mari0-st-ok">Mod instalado</span><span class="mari0-st-warn">Abre el juego</span>');
  else if (!st.inGame) parts.push('<span class="mari0-st-ok">Juego abierto</span><span class="mari0-st-warn">Entra a tu supermercado</span>');
  else if (!st.isHost) parts.push('<span class="mari0-st-warn">Estás en la partida de otro · crea tú la partida</span>');
  else parts.push('<span class="mari0-st-ok">Conectado · los regalos entran</span>' + (st.hasProducts === false ? '<span class="mari0-st-warn">Sin productos a la venta: no llegarán clientes</span>' : ''));
  el.innerHTML = parts.join(' ');
  return st;
}
function setupSupermarketModUI() {
  const pick = document.getElementById('supermarket-pick-dir');
  if (pick && !pick._wired) {
    pick._wired = true;
    pick.onclick = async () => {
      const picker = window.desktopAPI?.pickSupermarketGameDir || window.desktopAPI?.pickUnturnedGameDir;
      if (!picker) { toast && toast('Solo en la app .exe', 'warn'); return; }
      const dir = await picker();
      if (!dir) return;
      const r = await supermarketPost('supermarket-game-dir', { dir }).catch(() => null);
      if (r?.ok) toast && toast('Carpeta de Supermarket Together guardada.', 'ok');
      else toast && toast('Esa carpeta no tiene «Supermarket Together.exe».', 'warn');
      refreshSupermarketStatus();
    };
  }
  const install = document.getElementById('supermarket-install');
  if (install && !install._wired) {
    install._wired = true;
    install.onclick = async () => {
      if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
      install.disabled = true;
      setGameModProgressUi('supermarket', 40, 'Instalando mod de Livecoins…');
      try {
        const r = await supermarketPost('supermarket-install-mod', {}).catch(() => null);
        if (r?.ok) {
          setGameModProgressUi('supermarket', 100, '¡Listo!');
          toast && toast(r.backup ? 'Mod instalado. El mod anterior (TikControl) quedó guardado en _respaldo_tikcontrol.' : 'Mod de Livecoins instalado. Ya puedes abrir el juego.', 'ok');
        } else {
          toast && toast(r?.hint || `No se pudo instalar (${r?.error || 'error'})`, 'warn');
        }
      } finally {
        install.disabled = false;
        setTimeout(() => hideGameModProgressUi('supermarket'), 900);
        refreshSupermarketStatus();
      }
    };
  }
  const uninstall = document.getElementById('supermarket-uninstall');
  if (uninstall && !uninstall._wired) {
    uninstall._wired = true;
    uninstall.onclick = async () => {
      const r = await supermarketPost('supermarket-uninstall-mod', {}).catch(() => null);
      toast && toast(r?.ok ? 'Mod borrado.' : (r?.hint || 'No se pudo borrar el mod'), r?.ok ? 'ok' : 'warn');
      refreshSupermarketStatus();
    };
  }
  const launch = document.getElementById('supermarket-launch');
  if (launch && !launch._wired) {
    launch._wired = true;
    launch.onclick = async () => {
      const st = await refreshSupermarketStatus();
      if (st && !st.mod_installed) { toast && toast('Primero pulsa Instalar Mod (con el juego cerrado).', 'warn'); return; }
      const r = await supermarketPost('supermarket-launch', {}).catch(() => null);
      toast && toast(r?.ok ? 'Abriendo Supermarket Together…' : 'No se pudo abrir el juego', r?.ok ? 'ok' : 'warn');
    };
  }
  const steam = document.getElementById('supermarket-steam');
  if (steam && !steam._wired) {
    steam._wired = true;
    steam.onclick = () => {
      const url = 'https://store.steampowered.com/app/2709570/Supermarket_Together/';
      if (window.desktopAPI?.openExternal) window.desktopAPI.openExternal(url);
      else window.open(url, '_blank', 'noopener');
    };
  }
  if (!setupSupermarketModUI._poll) {
    setupSupermarketModUI._poll = setInterval(() => {
      const el = document.getElementById('supermarket-status');
      if (!el || !el.closest('.view.active') || document.hidden) return; // pestaña cerrada: no consultar
      refreshSupermarketStatus();
    }, 4000);
  }
  refreshSupermarketStatus();
}
async function generateSupermarketOverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensureSupermarketActions(),
    iconUrlFor: (a) => supermarketIconSrc(a?.thing),
    downloadName: 'supermarket-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'supermarketActions',
  });
}
/* «En contra» = lo que estorba al streamer: quitar dinero, basura, sacar clientes, resbalón, quejas. */
const SUPERMARKET_CONTRA = new Set(['moneyloss', 'trash', 'removecustomers', 'slip', 'complain']);
async function openSupermarketTableroPro() {
  try { commitOpenGameActionConfig({ quiet: true, skipErSync: true }); } catch {}
  const list = ensureSupermarketActions().filter(Boolean);
  if (!list.length) { toast && toast('Agrega acciones del catálogo primero.', 'warn'); return; }
  if (!(await ensureTableroPro())) { toast && toast('No se pudo abrir el generador. Intenta otra vez.', 'warn'); return; }
  const items = list.map((a) => ({ ...tableroItemFromAction(a, supermarketIconSrc(a.thing)), contra: SUPERMARKET_CONTRA.has(a.thing) }));
  window.openTableroPro({
    game: 'supermarket',
    title: 'Supermarket Together',
    sides: {
      items,
      defaultSide: (it) => (it.contra ? 'b' : 'a'),
      a: { id: 'favor', name: 'A favor', icon: '🛒', desc: 'Ayudan al súper: clientes, dinero, cajas, ofertas…', defaults: { label: 'A FAVOR', labelColor: '#4ade80' } },
      b: { id: 'contra', name: 'En contra', icon: '🗑️', desc: 'Estorban: basura, quitar dinero, sacar clientes…', defaults: { label: 'EN CONTRA', labelColor: '#ff4d5e' } },
    },
    boards: [
      { id: 'todas', name: 'Todas', icon: '🎮', desc: 'Todas tus acciones juntas', items, defaults: { label: 'ACCIONES', labelColor: '#e53935', cols: 4 } },
    ],
  });
}
function setupSupermarketActionsUI() {
  const genOverlayBtn = document.getElementById('supermarket-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generateSupermarketOverlayImage();
  }
  const genProBtn = document.getElementById('supermarket-gen-pro');
  if (genProBtn && !genProBtn._wired) {
    genProBtn._wired = true;
    genProBtn.onclick = () => openSupermarketTableroPro();
  }
  try { wireStarterPresetButtons(); } catch {}
  const open = document.getElementById('supermarket-open-catalog');
  if (open && !open._wired) {
    open._wired = true;
    open.onclick = () => {
      const modal = document.getElementById('supermarketCatalogModal');
      if (modal) modal.classList.remove('hidden');
      renderSupermarketCatalog('');
    };
  }
  const toggleAll = document.getElementById('supermarket-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensureSupermarketActions();
      const on = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = on; });
      lastGameActionEditAt = Date.now();
      try { recentGameActionEditKeys.add('supermarketActions'); } catch {}
      saveSettingsKeysPatch('supermarketActions', { flush: true, skipErSync: true });
      renderSupermarketActions();
    };
  }
  renderSupermarketActions();
}

