const PEAK_SECTION_ORDER = ['items', 'objetos', 'aguante', 'estados', 'caos', 'soltar'];
const PEAK_SECTION_LABEL = { items: 'Dar objeto', objetos: 'Objetos', aguante: 'Stamina y curación', estados: 'Estados', caos: 'Caos', soltar: 'Soltar y lanzar' };
const PEAK_SECTION_ICON = { items: '🎒', objetos: '🎁', aguante: '⚡', estados: '🥶', caos: '🚀', soltar: '🫳' };
