const OC2_SECTION_ORDER = ['tiempo', 'pedidos', 'cocina', 'chefs', 'velocidad'];
const OC2_SECTION_LABEL = { tiempo: 'Tiempo, puntos y combo', pedidos: 'Pedidos', cocina: 'Cocina', chefs: 'Chefs', velocidad: 'Velocidad del juego' };
const OC2_SECTION_ICON = { tiempo: '⏱️', pedidos: '📋', cocina: '🔥', chefs: '👨‍🍳', velocidad: '⏩' };
const OC2_SECTION_DESC = { tiempo: 'Reloj, marcador y propinas', pedidos: 'Quitar, sumar o pausar pedidos', cocina: 'Fuego, platos y comida', chefs: 'Resbalar, soltar, congelar, volar', velocidad: 'Todo el juego más rápido o más lento' };
function overcooked2CatalogEntry(thing) {
  return OC2_CATALOG.find((x) => x.id === thing);
}
/* Íconos propios: public/img/overcooked2/<id>.png. */
const OC2_ICON_V = 'oc1';
function overcooked2IconSrc(id) {
  const raw = String(id || '').trim();
  return raw ? `/img/overcooked2/${raw}.png?v=${OC2_ICON_V}` : '';
}
function overcooked2Icon(c, cls = 'repo-cat-list-ic') {
  const em = esc((c && c.emoji) || '🍳');
  if (!c || !c.id) return `<span class="${esc(cls)}">${em}</span>`;
  const fallback = `this.outerHTML='<span class=\\'repo-cat-list-em\\'>${em}</span>'`;
  return `<img class="${esc(cls)}" src="${esc(overcooked2IconSrc(c.id))}" alt="" loading="lazy" decoding="async" onerror="${fallback}">`;
}
function overcooked2ErrorText(r) {
  const e = String(r?.error || '');
  if (e === 'not_in_game') return 'entra a un nivel (no funciona en el mapa ni en el menú)';
  if (e === 'not_host') return 'solo funciona en la partida que tú creas (anfitrión)';
  if (e === 'bad_key') return 'reinstala el mod desde Livecoins (Instalar Mod)';
  if (e === 'accion_desconocida') return 'actualiza el mod: cierra el juego y pulsa Instalar Mod';
  if (/fetch|ECONNREFUSED|abort|timeout/i.test(e)) return 'abre el juego (con el mod de Livecoins instalado)';
  return e || 'falló';
}
function ensureOvercooked2Actions() {
  if (!settings.overcooked2Actions) settings.overcooked2Actions = [];
  for (const a of settings.overcooked2Actions) {
    const c = overcooked2CatalogEntry(a.thing);
    if (c) {
      if (!a.label) a.label = c.nombre;
      if (!a.desc) a.desc = c.desc;
      if (c.amount != null && (a.amount == null || a.amount === '')) a.amount = c.amount;
    }
    keepStoredGameQty(a, 1);
  }
  return settings.overcooked2Actions;
}
registerGameActSwap('overcooked2', {
  title: 'Clic para cambiar la acción',
  heading: 'Cambiar acción',
  placeholder: 'Buscar…',
  entries: () => OC2_CATALOG.map((c) => ({ id: c.id, name: c.nombre, desc: c.desc, iconHtml: overcooked2Icon(c) })),
  current: (uid) => ensureOvercooked2Actions().find((x) => x && x.uid === uid)?.thing,
  apply: gameActSwapApply({
    actions: ensureOvercooked2Actions,
    entry: overcooked2CatalogEntry,
    settingsKey: 'overcooked2Actions',
    render: () => renderOvercooked2Actions(),
  }),
});
function overcooked2CardHtml(a) {
  const c = overcooked2CatalogEntry(a.thing);
  const qty = gameQtyShown(a.count);
  let extra = `<label class="mc-qty-row" title="Cuántas veces">Veces
      <input type="number" min="1" max="20" class="pk-count mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(qty)}"></label>`;
  if (c && c.amount != null) {
    extra += `<label class="mc-qty-row" title="Cantidad por vez">${esc(c.amountLabel || 'Cantidad')}
      <input type="number" min="1" max="120" class="pk-amount mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(a.amount ?? c.amount)}"></label>`;
  }
  return gameSurvivalStyleCardHtml(a, {
    settingsKey: 'overcooked2Actions',
    thumbHtml: overcooked2Icon(c || { emoji: '🍳' }, 'mc-act-ic repo-cat-list-ic'),
    nameHtml: gameActSwapNameHtml(a, 'overcooked2'),
    infoExtraHtml: extra,
    cfgOpts: { countValue: qty },
    testClass: 'pk-test',
    delClass: 'pk-del',
  });
}
function renderOvercooked2Catalog(filter) {
  const f = (filter || '').trim().toLowerCase();
  const list = f
    ? OC2_CATALOG.filter((c) => c.nombre.toLowerCase().includes(f) || c.id.toLowerCase().includes(f) || (c.desc || '').toLowerCase().includes(f))
    : OC2_CATALOG;
  renderGameCatalogFold({
    grid: 'overcooked2-catalog',
    stateKey: 'overcooked2',
    filter: f,
    searchId: 'overcooked2-cat-search',
    rerender: renderOvercooked2Catalog,
    closeModalId: 'overcooked2CatalogModal',
    sections: buildCatalogSections(list, {
      sectionKey: 'section',
      order: OC2_SECTION_ORDER,
      labelMap: OC2_SECTION_LABEL,
      iconMap: OC2_SECTION_ICON,
      descMap: OC2_SECTION_DESC,
      searching: !!f,
    }),
    rowHtml: (c) => gameCatListBtnHtml(c.id, c.nombre, overcooked2Icon(c), c.desc || c.nombre),
    onPick: addOvercooked2FromCatalog,
  });
}
function addOvercooked2FromCatalog(thing) {
  const c = overcooked2CatalogEntry(thing);
  if (!c || !settings) return;
  const a = {
    uid: 'pk_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    thing: c.id,
    label: c.nombre,
    desc: c.desc,
    section: c.section,
    trigger: 'gift',
    giftId: '',
    giftName: '',
    giftImage: '',
    count: 1,
    text: '',
    enabled: false,
  };
  if (c.amount != null) a.amount = c.amount;
  ensureOvercooked2Actions().push(a);
  lastGameActionEditAt = Date.now();
  try { recentGameActionEditKeys.add('overcooked2Actions'); } catch {}
  saveSettingsKeysPatch('overcooked2Actions', { flush: true, skipErSync: true });
  renderOvercooked2Actions();
  renderOvercooked2Catalog(document.getElementById('overcooked2-cat-search')?.value || '');
  toast && toast(`Agregado: ${c.nombre}`, 'ok');
}
async function overcooked2StatusApi() {
  const r = await fetch('/api/desktop/overcooked2-status', { credentials: 'same-origin' });
  return r.json();
}
async function overcooked2Post(path, body) {
  const r = await fetch(`/api/desktop/${path}`, {
    method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}),
  });
  return r.json();
}
async function testOvercooked2Action(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  syncGameCardQtyFromDom(a, 'overcooked2Actions');
  const st = await overcooked2StatusApi().catch(() => null);
  if (!st?.http_ok) {
    toast && toast(st?.mod_installed ? 'Abre Overcooked! 2 y entra a un nivel.' : 'Pulsa Instalar Mod con el juego cerrado.', 'warn');
    return;
  }
  const r = await execGameLocal({
    tipo: 'OC2_SPAWN', thing: a.thing, name: 'Prueba', times: gameQtyForExec(a.count), amount: a.amount,
  });
  if (r && r.ok !== false) toast && toast('Enviado a Overcooked! 2.', 'ok');
  else toast && toast(`Overcooked! 2: ${overcooked2ErrorText(r)}`, 'warn');
}
function renderOvercooked2Actions() {
  const wrap = document.getElementById('overcooked2-my-actions');
  if (!wrap) return;
  registerGameActionRenderer('overcooked2Actions', renderOvercooked2Actions);
  const list = ensureOvercooked2Actions();
  wrap.innerHTML = list.map(overcooked2CardHtml).join('') || '<p class="mc-empty">Todavía no hay acciones. Crea una y elige el regalo.</p>';
  const find = (uid) => ensureOvercooked2Actions().find((x) => x.uid === uid);
  wrap.querySelectorAll('.pk-del').forEach((b) => {
    b.onclick = () => {
      ensureOvercooked2Actions();
      removeGameActions('overcooked2Actions', (x) => x.uid !== b.dataset.uid, renderOvercooked2Actions);
    };
  });
  wrap.querySelectorAll('.pk-count').forEach((inp) => {
    bindInstantGameQty(inp, () => find(inp.dataset.uid), 'overcooked2Actions');
  });
  wrap.querySelectorAll('.pk-amount').forEach((inp) => {
    inp.onchange = () => {
      const a = find(inp.dataset.uid);
      if (!a) return;
      const cat = overcooked2CatalogEntry(a.thing);
      a.amount = Math.max(1, Math.min((cat && cat.amountMax) || 120, Number(inp.value) || 1));
      inp.value = a.amount;
      lastGameActionEditAt = Date.now();
      try { recentGameActionEditKeys.add('overcooked2Actions'); } catch {}
      saveSettingsKeysPatch('overcooked2Actions', { skipErSync: true });
    };
  });
  bindGameActionConfigPopovers(wrap, find, renderOvercooked2Actions, { settingsKey: 'overcooked2Actions', rerenderOnSave: true });
  bindGameSurvivalCardExtras(wrap, find, renderOvercooked2Actions, {
    settingsKey: 'overcooked2Actions',
    testClass: 'pk-test',
    onTest: (b) => {
      const a = find(b.dataset.uid);
      if (a) testOvercooked2Action(a);
    },
  });
}
/* Estado del mod: instalado, juego abierto, dentro de un nivel y siendo el anfitrión. Otros mods (TikControl…) se dejan como están. */
async function refreshOvercooked2Status() {
  const el = document.getElementById('overcooked2-status');
  const dirInp = document.getElementById('overcooked2-game-dir');
  const st = await overcooked2StatusApi().catch(() => null);
  if (dirInp && st?.dir && document.activeElement !== dirInp) dirInp.value = st.dir;
  const ver = document.getElementById('overcooked2-mod-ver');
  if (ver && st?.version) ver.textContent = `Versión: ${st.version}`;
  if (!el) return st;
  const parts = [];
  if (!st) parts.push('<span class="mari0-st-warn">Sin respuesta de Livecoins</span>');
  else if (!st.dir) parts.push('<span class="mari0-st-warn">No encontré el juego · elige su carpeta</span>');
  else if (!st.mod_installed) parts.push('<span class="mari0-st-warn">Mod no instalado · cierra el juego y pulsa Instalar Mod</span>');
  else if (!st.http_ok) parts.push('<span class="mari0-st-ok">Mod instalado</span><span class="mari0-st-warn">Abre el juego</span>');
  else if (st.outdated) parts.push('<span class="mari0-st-warn">Mod viejo (' + esc(st.mod_version) + ') · cierra el juego y pulsa Instalar Mod</span>');
  else if (!st.inGame) parts.push('<span class="mari0-st-ok">Juego abierto</span><span class="mari0-st-warn">Entra a un nivel</span>');
  else if (!st.isHost) parts.push('<span class="mari0-st-warn">Estás en la partida de otro · crea tú la partida</span>');
  else parts.push('<span class="mari0-st-ok">Conectado · los regalos entran</span>');
  el.innerHTML = parts.join(' ');
  return st;
}
function setupOvercooked2ModUI() {
  const pick = document.getElementById('overcooked2-pick-dir');
  if (pick && !pick._wired) {
    pick._wired = true;
    pick.onclick = async () => {
      const picker = window.desktopAPI?.pickOvercooked2GameDir || window.desktopAPI?.pickUnturnedGameDir;
      if (!picker) { toast && toast('Solo en la app .exe', 'warn'); return; }
      const dir = await picker();
      if (!dir) return;
      const r = await overcooked2Post('overcooked2-game-dir', { dir }).catch(() => null);
      if (r?.ok) toast && toast('Carpeta de Overcooked! 2 guardada.', 'ok');
      else toast && toast('Esa carpeta no tiene «Overcooked2.exe».', 'warn');
      refreshOvercooked2Status();
    };
  }
  const install = document.getElementById('overcooked2-install');
  if (install && !install._wired) {
    install._wired = true;
    install.onclick = async () => {
      if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
      install.disabled = true;
      setGameModProgressUi('overcooked2', 40, 'Instalando mod de Livecoins…');
      try {
        const r = await overcooked2Post('overcooked2-install-mod', {}).catch(() => null);
        if (r?.ok) {
          setGameModProgressUi('overcooked2', 100, '¡Listo!');
          toast && toast(r.backup ? 'Mod de Livecoins instalado. El de TikControl quedó guardado en _respaldo_tikcontrol.' : 'Mod de Livecoins instalado. Ya puedes abrir el juego.', 'ok');
        } else {
          toast && toast(r?.hint || `No se pudo instalar (${r?.error || 'error'})`, 'warn');
        }
      } finally {
        install.disabled = false;
        setTimeout(() => hideGameModProgressUi('overcooked2'), 900);
        refreshOvercooked2Status();
      }
    };
  }
  const uninstall = document.getElementById('overcooked2-uninstall');
  if (uninstall && !uninstall._wired) {
    uninstall._wired = true;
    uninstall.onclick = async () => {
      const r = await overcooked2Post('overcooked2-uninstall-mod', {}).catch(() => null);
      toast && toast(r?.ok ? 'Mod de Livecoins borrado (los demás mods siguen).' : (r?.hint || 'No se pudo borrar el mod'), r?.ok ? 'ok' : 'warn');
      refreshOvercooked2Status();
    };
  }
  const launch = document.getElementById('overcooked2-launch');
  if (launch && !launch._wired) {
    launch._wired = true;
    launch.onclick = async () => {
      const st = await refreshOvercooked2Status();
      if (st && !st.mod_installed) { toast && toast('Primero pulsa Instalar Mod (con el juego cerrado).', 'warn'); return; }
      const r = await overcooked2Post('overcooked2-launch', {}).catch(() => null);
      toast && toast(r?.ok ? 'Abriendo Overcooked! 2…' : 'No se pudo abrir el juego', r?.ok ? 'ok' : 'warn');
    };
  }
  const steam = document.getElementById('overcooked2-steam');
  if (steam && !steam._wired) {
    steam._wired = true;
    steam.onclick = () => {
      const url = 'https://store.steampowered.com/app/728880/Overcooked_2/';
      if (window.desktopAPI?.openExternal) window.desktopAPI.openExternal(url);
      else window.open(url, '_blank', 'noopener');
    };
  }
  if (!setupOvercooked2ModUI._poll) {
    setupOvercooked2ModUI._poll = setInterval(() => {
      const el = document.getElementById('overcooked2-status');
      if (!el || !el.closest('.view.active') || document.hidden) return; // pestaña cerrada: no consultar
      refreshOvercooked2Status();
    }, 4000);
  }
  refreshOvercooked2Status();
}
async function generateOvercooked2OverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensureOvercooked2Actions(),
    iconUrlFor: (a) => overcooked2IconSrc(a?.thing),
    downloadName: 'overcooked2-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'overcooked2Actions',
  });
}
/* «En contra» = lo que estorba al streamer: quitar tiempo/puntos, fuego, resbalar, congelar, velocidad… */
const OC2_CONTRA = new Set(['removetime', 'removescore', 'resetcombo', 'addorder', 'startfire', 'burnfood', 'breakplates', 'clearcounters', 'slip', 'drop', 'freeze', 'launch', 'speedfast', 'speedslow', 'speedcrazy']);
async function openOvercooked2TableroPro() {
  try { commitOpenGameActionConfig({ quiet: true, skipErSync: true }); } catch {}
  const list = ensureOvercooked2Actions().filter(Boolean);
  if (!list.length) { toast && toast('Agrega acciones del catálogo primero.', 'warn'); return; }
  if (!(await ensureTableroPro())) { toast && toast('No se pudo abrir el generador. Intenta otra vez.', 'warn'); return; }
  const items = list.map((a) => ({ ...tableroItemFromAction(a, overcooked2IconSrc(a.thing)), contra: OC2_CONTRA.has(a.thing) }));
  window.openTableroPro({
    game: 'overcooked2',
    title: 'Overcooked! 2',
    sides: {
      items,
      defaultSide: (it) => (it.contra ? 'b' : 'a'),
      a: { id: 'favor', name: 'A favor', icon: '🍳', desc: 'Ayudan a la cocina: tiempo, puntos, combo, apagar fuegos…', defaults: { label: 'A FAVOR', labelColor: '#4ade80' } },
      b: { id: 'contra', name: 'En contra', icon: '🔥', desc: 'Estorban: fuego, resbalar, congelar, quitar tiempo…', defaults: { label: 'EN CONTRA', labelColor: '#ff4d5e' } },
    },
    boards: [
      { id: 'todas', name: 'Todas', icon: '🎮', desc: 'Todas tus acciones juntas', items, defaults: { label: 'ACCIONES', labelColor: '#e53935', cols: 4 } },
    ],
  });
}
function setupOvercooked2ActionsUI() {
  const genOverlayBtn = document.getElementById('overcooked2-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generateOvercooked2OverlayImage();
  }
  const genProBtn = document.getElementById('overcooked2-gen-pro');
  if (genProBtn && !genProBtn._wired) {
    genProBtn._wired = true;
    genProBtn.onclick = () => openOvercooked2TableroPro();
  }
  try { wireStarterPresetButtons(); } catch {}
  const open = document.getElementById('overcooked2-open-catalog');
  if (open && !open._wired) {
    open._wired = true;
    open.onclick = () => {
      const modal = document.getElementById('overcooked2CatalogModal');
      if (modal) modal.classList.remove('hidden');
      renderOvercooked2Catalog('');
    };
  }
  const toggleAll = document.getElementById('overcooked2-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensureOvercooked2Actions();
      const on = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = on; });
      lastGameActionEditAt = Date.now();
      try { recentGameActionEditKeys.add('overcooked2Actions'); } catch {}
      saveSettingsKeysPatch('overcooked2Actions', { flush: true, skipErSync: true });
      renderOvercooked2Actions();
    };
  }
  renderOvercooked2Actions();
}

