const HILL_SECTION_ORDER = ['base', 'favor', 'contra'];
const HILL_SECTION_LABEL = { base: 'Auto y partida', favor: 'A favor (hacia la meta)', contra: 'En contra (hacia atrás)' };
const HILL_SECTION_ICON = { base: '🚙', favor: '🟢', contra: '🔴' };
const HILL_SECTION_DESC = { base: 'Empujar, gasolina, mejoras, wins y cajas', favor: 'Ayudan a llegar a la meta', contra: 'Mandan el auto para atrás' };
const HILL_METROS = new Set(['subir', 'bajar']);
function hillIsCharacter(thing) {
  const c = hillCatalogEntry(thing);
  return !!c && (c.section === 'favor' || c.section === 'contra') && !['portal', 'teletransportar', 'proteger', 'destruccion', 'desproteger', 'zombi', 'rayo', 'explosion'].includes(thing);
}
function hillDefaultCount(thing) {
  if (HILL_METROS.has(thing)) return 10;
  if (hillIsCharacter(thing)) return 20;
  return 1;
}
function hillCountLabel(thing) {
  return HILL_METROS.has(thing) || hillIsCharacter(thing) ? 'Metros' : 'Veces';
}
function hillCatalogEntry(thing) {
  return HILL_CATALOG.find((x) => x.id === thing);
}
/* Íconos propios: public/img/hill/<id>.png (hechos con los dibujos del juego). */
const HILL_ICON_V = 'hc5';
function hillIconSrc(id) {
  const raw = String(id || '').trim();
  return raw ? `/img/hill/${raw}.png?v=${HILL_ICON_V}` : '';
}
/*
 * Íconos animados (WebP con los cuadros reales del juego, 128 px): public/img/hill/anim/<id>.webp.
 * Se usan en la lista de acciones, el catálogo y «Generar imagen pro». El Editor Pro y los paquetes
 * del editor siguen con el PNG fijo (más grande, mejor para editar).
 */
const HILL_ANIM_V = 'ha3';
// Las que se veían cortadas en el cuadro se quedan con su imagen fija.
const HILL_ANIM_IDS = new Set(['abeja', 'dragonagua', 'fenix', 'fenixgrande', 'goku', 'lulu', 'meteorito', 'nailong', 'nyan', 'pikachu',
  'portal', 'proteger', 'rayo', 'tornado', 'tsunami', 'tsunamisube', 'vaca', 'vegeta', 'zombi']);
function hillAnimSrc(id) {
  const raw = String(id || '').trim();
  return HILL_ANIM_IDS.has(raw) ? `/img/hill/anim/${raw}.webp?v=${HILL_ANIM_V}` : '';
}
/** Animado si existe; si no, el PNG de siempre. */
function hillIconLiveSrc(id) {
  return hillAnimSrc(id) || hillIconSrc(id);
}
function hillIcon(c, cls = 'repo-cat-list-ic') {
  const em = esc((c && c.emoji) || '🚙');
  if (!c || !c.id) return `<span class="${esc(cls)}">${em}</span>`;
  const anim = hillAnimSrc(c.id);
  // Si el animado no carga se usa el PNG; si tampoco, el emoji.
  const fallback = `this.outerHTML='<span class=\\'repo-cat-list-em\\'>${em}</span>'`;
  const onerr = anim ? `if(!this.dataset.png){this.dataset.png=1;this.src='${hillIconSrc(c.id)}';}else{${fallback}}` : fallback;
  return `<img class="${esc(cls)} ${anim ? 'hill-ic-anim' : 'hill-ic-still'}" src="${esc(anim || hillIconSrc(c.id))}" alt="" loading="lazy" decoding="async" onerror="${onerr}">`;
}
function ensureHillActions() {
  if (!settings.hillActions) settings.hillActions = [];
  for (const a of settings.hillActions) {
    const c = hillCatalogEntry(a.thing);
    if (c) {
      if (!a.label) a.label = c.nombre;
      if (!a.desc) a.desc = c.desc;
    }
    keepStoredGameQty(a, hillDefaultCount(a.thing));
  }
  return settings.hillActions;
}
registerGameActSwap('hill', {
  title: 'Clic para cambiar el efecto',
  heading: 'Cambiar efecto',
  placeholder: 'Buscar…',
  entries: () => HILL_CATALOG.map((c) => ({
    id: c.id, name: c.nombre, desc: c.desc, iconHtml: hillIcon(c),
  })),
  current: (uid) => ensureHillActions().find((x) => x && x.uid === uid)?.thing,
  apply: gameActSwapApply({
    actions: ensureHillActions,
    entry: hillCatalogEntry,
    settingsKey: 'hillActions',
    render: () => renderHillActions(),
  }),
});
function hillCardHtml(a) {
  const c = hillCatalogEntry(a.thing);
  const qty = gameQtyShown(a.count);
  return gameSurvivalStyleCardHtml(a, {
    settingsKey: 'hillActions',
    thumbHtml: hillIcon(c || { emoji: '🚙' }, 'mc-act-ic repo-cat-list-ic'),
    nameHtml: gameActSwapNameHtml(a, 'hill'),
    infoExtraHtml: `<label class="mc-qty-row" title="Metros que empuja o cuántas veces">${hillCountLabel(a.thing)}
      <input type="number" min="1" class="hill-count mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(qty)}"></label>`,
    cfgOpts: { countValue: qty },
    testClass: 'hill-test',
    delClass: 'hill-del',
  });
}
function renderHillCatalog(filter) {
  const f = (filter || '').trim().toLowerCase();
  const list = f
    ? HILL_CATALOG.filter((c) => c.nombre.toLowerCase().includes(f) || c.id.includes(f) || (c.desc || '').toLowerCase().includes(f))
    : HILL_CATALOG;
  renderGameCatalogFold({
    grid: 'hill-catalog',
    stateKey: 'hill',
    filter: f,
    searchId: 'hill-cat-search',
    rerender: renderHillCatalog,
    closeModalId: 'hillCatalogModal',
    sections: buildCatalogSections(list, {
      sectionKey: 'section',
      order: HILL_SECTION_ORDER,
      labelMap: HILL_SECTION_LABEL,
      iconMap: HILL_SECTION_ICON,
      descMap: HILL_SECTION_DESC,
      searching: !!f,
    }),
    rowHtml: (c) => gameCatListBtnHtml(c.id, c.nombre, hillIcon(c), c.desc || c.nombre),
    onPick: addHillFromCatalog,
  });
}
function addHillFromCatalog(thing) {
  const c = hillCatalogEntry(thing);
  if (!c || !settings) return;
  ensureHillActions().push({
    uid: 'hill_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    thing: c.id,
    label: c.nombre,
    desc: c.desc,
    section: c.section,
    trigger: 'gift',
    giftId: '',
    giftName: '',
    giftImage: '',
    count: hillDefaultCount(c.id),
    text: '',
    enabled: false,
  });
  lastGameActionEditAt = Date.now();
  try { recentGameActionEditKeys.add('hillActions'); } catch {}
  saveSettingsKeysPatch('hillActions', { flush: true, skipErSync: true });
  renderHillActions();
  renderHillCatalog(document.getElementById('hill-cat-search')?.value || '');
  toast && toast(`Agregado: ${c.nombre}`, 'ok');
}
async function hillBridgeHealthApi() {
  const r = await fetch('/api/desktop/hill-bridge-health', { credentials: 'same-origin' });
  return r.json();
}
async function ensureHillBridgeApi() {
  const r = await fetch('/api/desktop/ensure-hill-bridge', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: '{}' });
  return r.json();
}
async function sendHillConfigApi() {
  const o = hillLaunchOpts();
  try {
    await fetch('/api/desktop/hill-config', {
      method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ meta: o.meta, wins: o.wins, cuenta: o.cuenta, volumen: o.volumen, musica: o.musica, pista: o.pista, carro: o.carro, winsneg: !!o.winsneg, dificultad: hillDifValue(o.dificultad) }),
    });
  } catch {}
}
async function testHillAction(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  syncGameCardQtyFromDom(a, 'hillActions');
  const bridge = await hillBridgeHealthApi().catch(() => null);
  if (!(bridge?.ok && bridge?.health?.running)) {
    toast && toast('Pulsa Ejecutar juego primero.', 'warn');
    return;
  }
  if (!bridge?.health?.gameConnected) {
    toast && toast('Abre el juego con Ejecutar juego.', 'warn');
  }
  const lastR = await execGameLocal({ tipo: 'HILL_SPAWN', thing: a.thing, name: 'Prueba', times: gameQtyForExec(a.count) });
  if (lastR && lastR.ok !== false) toast && toast('Enviado a Hill Climb.', 'ok');
  else if (lastR?.error === 'juego_no_conectado') toast && toast('El juego no está abierto. Pulsa Ejecutar juego.', 'warn');
  else toast && toast(lastR?.error || 'No se pudo enviar', 'warn');
}
function renderHillActions() {
  const wrap = document.getElementById('hill-my-actions');
  if (!wrap) return;
  registerGameActionRenderer('hillActions', renderHillActions);
  const list = ensureHillActions();
  wrap.innerHTML = list.map(hillCardHtml).join('') || '<p class="mc-empty">Todavía no hay acciones. Crea una y elige el regalo.</p>';
  wrap.querySelectorAll('.hill-del').forEach((b) => {
    b.onclick = () => {
      ensureHillActions();
      removeGameActions('hillActions', (x) => x.uid !== b.dataset.uid, renderHillActions);
    };
  });
  wrap.querySelectorAll('.hill-count').forEach((inp) => {
    bindInstantGameQty(inp, () => ensureHillActions().find((x) => x.uid === inp.dataset.uid), 'hillActions');
  });
  const find = (uid) => ensureHillActions().find((x) => x.uid === uid);
  bindGameActionConfigPopovers(wrap, find, renderHillActions, { settingsKey: 'hillActions', rerenderOnSave: true });
  bindGameSurvivalCardExtras(wrap, find, renderHillActions, {
    settingsKey: 'hillActions',
    testClass: 'hill-test',
    onTest: (b) => {
      const a = find(b.dataset.uid);
      if (a) testHillAction(a);
    },
  });
}
