/* Opciones de la partida (se guardan en esta PC) y ruta de HillClimb.exe. */
function hillLaunchOpts() {
  const def = { exe: '', meta: 1000, wins: 10, cuenta: 15, volumen: 80, musica: true, pista: 'colinas', carro: 'clasico', winsneg: false, dificultad: 'normal' };
  try {
    const raw = JSON.parse(localStorage.getItem('lc.hill.opts') || 'null');
    return raw && typeof raw === 'object' ? { ...def, ...raw } : def;
  } catch { return def; }
}
function saveHillLaunchOpts(patchOpts) {
  const o = { ...hillLaunchOpts(), ...patchOpts };
  try { localStorage.setItem('lc.hill.opts', JSON.stringify(o)); } catch {}
  return o;
}
function setupHillOptions() {
  const o = hillLaunchOpts();
  const exeEl = document.getElementById('hill-exe-path');
  const paintExe = (p) => { if (exeEl) { exeEl.textContent = p ? p.split(/[\\/]/).slice(-2).join('\\') : 'Elige HillClimb.exe'; exeEl.title = p || 'Busca Escritorio\\HillClimb Livecoins\\HillClimb.exe'; } };
  paintExe(o.exe);
  if (!o.exe && window.desktopAPI?.hillclimbDefaultExe) {
    window.desktopAPI.hillclimbDefaultExe().then((p) => { if (p) { saveHillLaunchOpts({ exe: p }); paintExe(p); } }).catch(() => {});
  }
  const pick = document.getElementById('hill-pick-exe');
  if (pick && !pick._wired) {
    pick._wired = true;
    pick.onclick = async () => {
      if (!window.desktopAPI?.pickHillclimbExe) { toast && toast('Solo en la app .exe', 'warn'); return; }
      const p = await window.desktopAPI.pickHillclimbExe().catch(() => null);
      if (p) { saveHillLaunchOpts({ exe: p }); paintExe(p); toast && toast('Juego elegido.', 'ok'); }
    };
  }
  const bindNum = (id, key, lo, hi) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.value = String(o[key]);
    if (el._wired) return;
    el._wired = true;
    el.onchange = () => {
      const v = Math.max(lo, Math.min(hi, parseInt(el.value, 10) || hillLaunchOpts()[key]));
      el.value = String(v);
      saveHillLaunchOpts({ [key]: v });
      sendHillConfigApi();
    };
  };
  // selector de pista y carro (al cambiar, el juego reinicia la ronda con lo elegido)
  const pickGrid = (wrapId, infoId, list, key, img) => {
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;
    const info = document.getElementById(infoId);
    const paint = () => {
      const cur = hillLaunchOpts()[key];
      wrap.querySelectorAll('.hill-pick').forEach((b) => b.classList.toggle('is-on', b.dataset.id === cur));
      const it = list.find((x) => x.id === cur) || list[0];
      if (info && it) info.textContent = `${it.nombre} · ${it.desc}`;
    };
    if (!wrap._wired) {
      wrap._wired = true;
      wrap.innerHTML = list.map((it) => `<button type="button" class="hill-pick" data-id="${esc(it.id)}" title="${esc(it.nombre)} · ${esc(it.desc)}">`
        + `<img src="${esc(img(it.id))}" alt="" loading="lazy" decoding="async"><span class="hill-pick-n">${esc(it.corto || it.nombre)}</span></button>`).join('');
      wrap.addEventListener('click', (e) => {
        const b = e.target.closest('.hill-pick');
        if (!b) return;
        saveHillLaunchOpts({ [key]: b.dataset.id });
        paint();
        sendHillConfigApi();
        toast && toast(`${key === 'pista' ? 'Pista' : 'Carro'}: ${b.querySelector('.hill-pick-n')?.textContent || b.dataset.id}`, 'ok');
      });
    }
    paint();
  };
  pickGrid('hill-pistas', 'hill-pista-info', HILL_PISTAS_UI, 'pista', (id) => `/img/hill/pista-${id}.jpg?v=${HILL_ICON_V}`);
  pickGrid('hill-carros', 'hill-carro-info', HILL_CARROS_UI, 'carro', (id) => `/img/hill/carro-${id}.png?v=${HILL_ICON_V}`);
  const difWrap = document.getElementById('hill-dif');
  if (difWrap) {
    const paintDif = () => {
      const cur = hillLaunchOpts().dificultad || 'normal';
      difWrap.querySelectorAll('.hill-dif').forEach((b) => b.classList.toggle('is-on', b.dataset.id === cur));
      const it = HILL_DIF_UI.find((d) => d.id === cur) || HILL_DIF_UI[1];
      const info = document.getElementById('hill-dif-info');
      if (info) info.textContent = it.desc;
    };
    if (!difWrap._wired) {
      difWrap._wired = true;
      difWrap.innerHTML = HILL_DIF_UI.map((d) => `<button type="button" class="hill-dif" data-id="${d.id}" title="${d.desc}"><i>${d.ico}</i>${d.nombre}</button>`).join('');
      difWrap.addEventListener('click', (e) => {
        const b = e.target.closest('.hill-dif');
        if (!b) return;
        saveHillLaunchOpts({ dificultad: b.dataset.id });
        paintDif();
        sendHillConfigApi();
        toast && toast(`Dificultad: ${b.textContent.trim()} · empieza una ronda nueva`, 'ok');
      });
    }
    paintDif();
  }
  bindNum('hill-meta', 'meta', 100, 20000);
  bindNum('hill-wins', 'wins', 1, 999);
  bindNum('hill-cuenta', 'cuenta', 0, 60);
  bindNum('hill-vol', 'volumen', 0, 100);
  const mus = document.getElementById('hill-musica');
  if (mus) {
    mus.checked = !!o.musica;
    if (!mus._wired) {
      mus._wired = true;
      mus.onchange = () => { saveHillLaunchOpts({ musica: !!mus.checked }); sendHillConfigApi(); };
    }
  }
  // Wins negativas: «Quitar win» puede dejar el contador abajo de 0 (ej. -5/10)
  const neg = document.getElementById('hill-winsneg');
  if (neg) {
    neg.checked = !!o.winsneg;
    if (!neg._wired) {
      neg._wired = true;
      neg.onchange = () => {
        saveHillLaunchOpts({ winsneg: !!neg.checked });
        sendHillConfigApi();
        toast && toast(neg.checked ? 'Wins negativas activadas: el contador puede bajar de 0.' : 'Wins negativas apagadas: el contador se queda en 0.', 'ok');
      };
    }
  }
}
function setupHillBridgeBtn() {
  const btn = document.getElementById('hill-bridge');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    btn.disabled = true;
    try {
      const r = await ensureHillBridgeApi();
      if (r && r.ok) await sendHillConfigApi();
      paintBridgeConnectBtn(btn, !!(r && r.ok));
      toast && toast(r && r.ok ? 'Hill Climb conectado. Ahora Ejecutar juego.' : 'No se pudo conectar', r && r.ok ? 'ok' : 'warn');
    } finally { btn.disabled = false; }
  };
}
/* La primera vez baja el juego (GitHub) con barra de progreso; después lo abre directo. */
async function ensureHillInstalled() {
  // Revisa en GitHub si hay un Hill Climb nuevo: si lo hay se borra el viejo y se instala;
  // si no, solo se abre; la primera vez se descarga.
  let st = await fetch('/api/desktop/hill-install-status?check=1', { credentials: 'same-origin' }).then((x) => x.json()).catch(() => null);
  if (st?.upToDate && st.exe) return st.exe;
  // Hay versión nueva: cerrar el juego abierto (si no, Windows no deja reemplazar los archivos).
  if (st?.installed && window.desktopAPI?.closeHillclimb) {
    try { await window.desktopAPI.closeHillclimb(); } catch { /* ignore */ }
  }
  const label = st?.installed ? 'Actualizando Hill Climb…' : 'Descargando Hill Climb (solo la primera vez)…';
  setGameModProgressUi('hill', 2, label);
  const poll = setInterval(async () => {
    const s = await fetch('/api/desktop/hill-install-status', { credentials: 'same-origin' }).then((x) => x.json()).catch(() => null);
    const pr = s?.progress;
    if (!pr) return;
    if (pr.phase === 'extract') setGameModProgressUi('hill', 96, 'Instalando…');
    else if (pr.total) {
      const pct = Math.min(95, Math.round((pr.received / pr.total) * 95));
      setGameModProgressUi('hill', pct, `${label.replace('…', '')} ${pct}% · ${(pr.received / 1048576).toFixed(0)} / ${(pr.total / 1048576).toFixed(0)} MB`);
    }
  }, 600);
  let r = null;
  try {
    r = await fetch('/api/desktop/hill-install', {
      method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ installIfMissing: true }),
    }).then((x) => x.json()).catch(() => null);
  } finally {
    clearInterval(poll);
  }
  if (r?.ok && r.exe) {
    if (r.via === 'en_uso') {
      toast && toast('Hay una versión nueva de Hill Climb: ciérralo y pulsa Ejecutar juego otra vez para actualizar.', 'warn');
    }
    setGameModProgressUi('hill', 100, r.via === 'download' ? '¡Listo! Abriendo…' : 'Abriendo…');
    setTimeout(() => hideGameModProgressUi('hill'), 900);
    return r.exe;
  }
  hideGameModProgressUi('hill');
  // Sin internet o sin el archivo en GitHub: usa una copia local si existe.
  const local = hillLaunchOpts().exe || (await window.desktopAPI?.hillclimbDefaultExe?.().catch(() => '')) || '';
  if (local) return local;
  toast && toast(`No se pudo descargar Hill Climb${r?.error ? ` (${r.error})` : ''}. Revisa tu internet y pulsa Ejecutar juego otra vez.`, 'warn');
  return '';
}
function setupHillLaunchBtn() {
  setupHillOptions();
  const btn = document.getElementById('hill-launch');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    if (!window.desktopAPI?.openHillclimb) {
      toast && toast(window.desktopAPI ? 'Cierra Livecoins y ábrelo otra vez para usar el juego.' : 'Solo en la app .exe', 'warn');
      return;
    }
    btn.disabled = true;
    try {
      await ensureHillBridgeApi().catch(() => {});
      await sendHillConfigApi();
      const exe = await ensureHillInstalled();
      if (!exe) return;
      const r = await window.desktopAPI.openHillclimb({ exe }).catch(() => null);
      if (r && r.ok !== false) toast && toast(r.restarted ? 'Hill Climb se reinició con la versión nueva' : (r.reused ? 'Hill Climb ya está abierto' : 'Hill Climb abierto'), 'ok');
      else toast && toast('No se pudo abrir el juego', 'warn');
    } finally {
      btn.disabled = false;
    }
  };
}
function setupHillStatusPoll() {
  if (setupHillStatusPoll._on) return;
  setupHillStatusPoll._on = true;
  const tick = async () => {
    const el = document.getElementById('hill-status');
    const btn = document.getElementById('hill-bridge');
    if (!el && !btn) return;
    if (!(el || btn).closest(".view.active") || document.hidden) return; // pestaña cerrada: no consultar
    const cur = await hillBridgeHealthApi().catch(() => null);
    const running = !!(cur?.ok && cur?.health?.running);
    const gameOn = !!cur?.health?.gameConnected;
    paintBridgeConnectBtn(btn, running);
    if (el) el.textContent = !running ? 'Pulsa Ejecutar juego.' : (gameOn ? 'Juego abierto. Los regalos entran.' : 'Pulsa Ejecutar juego.');
  };
  setInterval(tick, 4000);
  // Al volver a la pestaña del juego, refrescar ya (no esperar 4 s).
  document.addEventListener('click', (e) => { if (e.target.closest?.('.nav-item, [data-view], [data-game]')) setTimeout(tick, 250); });
  tick();
}
