function starterUid(prefix, i) {
  return prefix + '_' + Date.now().toString(36) + '_' + i + '_' + Math.random().toString(36).slice(2, 6);
}
function stampStarterGift(row, gift) {
  row.trigger = 'gift';
  row.giftId = String(gift.id);
  row.giftName = gift.name;
  row.giftImage = gift.image;
  row.enabled = true;
  return row;
}
function starterRows(prefix, ids, find, shape) {
  const out = [];
  for (let i = 0; i < ids.length && out.length < STARTER_GIFTS.length; i++) {
    const c = find(ids[i]);
    if (!c) continue;
    out.push(shape(c, STARTER_GIFTS[out.length], out.length));
  }
  return out;
}
function starterThingRow(prefix, c, gift, i, count) {
  const row = {
    uid: starterUid(prefix, i),
    thing: c.id,
    label: c.nombre || c.name || c.id,
    desc: c.desc || '',
    section: c.section || '',
    count: count == null ? 1 : count,
    text: '',
  };
  if (c.img) row.img = c.img;
  if (c.params) {
    for (const p of c.params) {
      if (p && p.default != null) row[p.key] = p.default;
    }
  }
  return stampStarterGift(row, gift);
}
function starterListIsBlank(game) {
  const meta = GAME_PRESET_MAP[game];
  if (!meta || !settings) return true;
  const list = Array.isArray(settings[meta.key]) ? settings[meta.key] : [];
  if (game === 'roblox' || game === 'roblox3' || game === 'robloxtk' || game === 'robloxmt') {
    return !list.some((a) => a && String(a.giftId || '').trim());
  }
  return list.length === 0;
}
async function commitStarterPreset(game, title, build, opts) {
  if (!settings) { toast && toast('Espera a que cargue el panel…', 'warn'); return; }
  const meta = GAME_PRESET_MAP[game];
  if (!meta) return;
  const blank = starterListIsBlank(game);
  const o = opts || {};
  const ok = typeof askConfirm === 'function' ? await askConfirm({
    title,
    message: blank
      ? (o.messageBlank || 'Se carga este preset en el perfil vacío, con regalos de 1 a 100 monedas. No borra otros presets.')
      : (o.messageNew || 'Se crea un preset nuevo con acciones listas y regalos de 1 a 100 monedas. Tus presets actuales no se tocan.'),
    confirmText: blank ? 'Cargar preset' : 'Crear preset',
    icon: o.icon || '🎁',
    danger: false,
  }) : true;
  if (!ok) return;
  if (!blank) createMcPreset(game);
  else ensureMcPresetBank(game);
  const bank = ensureMcPresetBank(game);
  const p = bank && bank.presets.find((x) => x && x.id === bank.activeId);
  if (p) p.name = title;
  let actions = [];
  try { actions = await build(); } catch (e) { actions = []; }
  if (!Array.isArray(actions) || !actions.length) {
    toast && toast('No se pudo armar el preset. Ábrelo otra vez en un momento.', 'warn');
    return;
  }
  settings[meta.key] = actions;
  try { syncMcPresetFromActions(game); } catch {}
  markMcPresetDirty(game);
  lastGameActionEditAt = Date.now();
  try { recentGameActionEditKeys.add(meta.key); } catch {}
  saveSettingsKeysPatch(meta.key, { flush: true, skipErSync: true });
  saveGamePresetState(game, { sync: false, skipErSync: true, flush: true });
  try { notifyEditorRapidoActionsChanged(meta.key); } catch {}
  try { meta.render(); } catch {}
  scheduleRefreshMcPresetBar(game);
  toast && toast('Preset «' + title + '» listo: ' + actions.length + ' acciones. Regalos de 1 a 100 monedas.', 'ok');
}
