function starterRobloxSlots(game) {
  const ensure = game === 'roblox' ? ensureRobloxSlots
    : game === 'roblox3' ? ensureRoblox3Slots
    : game === 'robloxtk' ? ensureRobloxtkSlots
    : ensureRobloxmtSlots;
  const list = ensure();
  const n = Math.min(list.length, STARTER_GIFTS.length);
  for (let i = 0; i < n; i++) {
    const a = list[i];
    const g = STARTER_GIFTS[i];
    a.trigger = 'gift';
    a.giftId = String(g.id);
    a.giftName = g.name;
    a.giftImage = g.image;
    a.enabled = true;
    if (!a.count) a.count = 1;
  }
  return list.slice();
}
function loadGameStarterPreset(game) {
  const build = STARTER_PRESET_BUILDERS[game];
  if (!build) return;
  const title = STARTER_PRESET_TITLES[game] || 'Preset inicial';
  return commitStarterPreset(game, title, build);
}
function wireStarterPresetButtons() {
  document.querySelectorAll('[data-starter-preset]').forEach((btn) => {
    if (btn._wired) return;
    btn._wired = true;
    btn.onclick = () => loadGameStarterPreset(btn.getAttribute('data-starter-preset'));
  });
}
wireStarterPresetButtons();

