function hillPresetGiftImg(code) {
  const base = 'https://p16-webcast.tiktokcdn.com/img/';
  return code
    .replace(/^GmaLivaR\//, base + 'maliva/webcast-va/resource/')
    .replace(/^GmaLiva\//, base + 'maliva/webcast-va/')
    .replace(/^GaliSgR\//, base + 'alisg/webcast-sg/resource/')
    .replace(/^GaliSg\//, base + 'alisg/webcast-sg/');
}
async function createHillHeroesPreset() {
  const mk = (row, i, lado) => {
    const c = hillCatalogEntry(row[0]);
    return {
      uid: 'hill_hv_' + Date.now() + '_' + lado + i + '_' + Math.random().toString(36).slice(2, 6),
      thing: row[0],
      label: (lado === 'h' ? '🦸 ' : '😈 ') + ((c && c.nombre) || row[0]),
      desc: (c && c.desc) || '',
      section: (c && c.section) || '',
      trigger: 'gift',
      giftId: row[2],
      giftName: row[3],
      giftImage: hillPresetGiftImg(row[4]),
      count: row[1],
      text: '',
      enabled: true,
    };
  };
  return commitStarterPreset('hillclimb', 'Héroes vs Villanos', () => [
    ...HILL_PRESET_HEROES.map((r, i) => mk(r, i, 'h')),
    ...HILL_PRESET_VILLANOS.map((r, i) => mk(r, i, 'v')),
  ], {
    icon: '🦸',
    messageBlank: 'Se carga Héroes vs Villanos en este perfil vacío: 9 héroes a la META y 9 villanos hacia atrás. Regalos de 1 a 100 monedas, parejos de cada lado.',
    messageNew: 'Se crea un preset nuevo con 18 acciones: 9 héroes a la META y 9 villanos hacia atrás. Regalos de 1 a 100 monedas. Tus presets actuales no se tocan.',
  });
}
