const TBP_TRIG_IMG = {
  like: '/img/trig/like.png?v=2', likeGlobal: '/img/trig/like-global.png?v=2',
  follow: '/img/trig/follow.png?v=2', share: '/img/trig/share.png?v=2',
  subscribe: '/img/trig/subscribe.png?v=2', fan: '/img/trig/subscribe.png?v=2',
  superFan: '/img/trig/superfan.png?v=2', superFanJoin: '/img/trig/superfan-join.png?v=2',
  levelUp: '/img/trig/levelup.png?v=2', join: '/img/trig/firstmsg.png?v=2', firstMessage: '/img/trig/firstmsg.png?v=2',
  chatUser: '/img/trig/chat.png?v=2', chatCommand: '/img/trig/chat.png?v=2', chatAny: '/img/trig/chat.png?v=2',
  emote: '/img/trig/emote.png?v=2', emoteFan: '/img/trig/emote.png?v=2',
  'gift-any': '/img/trig/diamonds.png?v=2', 'gift-diamonds': '/img/trig/diamonds.png?v=2',
};
const TBP_CORNER_TRIG = { like: 'like', follow: 'follow', share: 'share', superfan: 'superFan' };
function tbpTriggerIcon(trigger, cornerType, emoji) {
  let t = String(trigger || '') || TBP_CORNER_TRIG[cornerType] || '';
  if (!TBP_TRIG_IMG[t] && emoji) t = Object.keys(MC_TRIG_ICON).find((k) => MC_TRIG_ICON[k].ic === emoji) || t;
  return TBP_TRIG_IMG[t] || '';
}
async function openTableroFromRows(rows, cap) {
  const list = (Array.isArray(rows) ? rows : []).filter(Boolean);
  if (!list.length) { toast && toast('Agrega acciones con su regalo primero.', 'warn'); return false; }
  if (!(await ensureTableroPro())) { toast && toast('No se pudo abrir el generador. Intenta otra vez.', 'warn'); return false; }
  const items = list.map((r, i) => ({
    key: r.actionUid || `${r.actionName || ''}|${r.giftName || ''}|${i}`,
    img: r.actionSrc || '',
    gift: r.giftSrc || tbpTriggerIcon(r.trigger, r.cornerType, r.giftEmoji),
    giftEmoji: r.giftEmoji || TBP_CORNER_EMOJI[r.cornerType] || '',
    giftName: r.giftName || '',
    name: r.actionName || '',
    qty: Math.max(1, parseInt(r.qty, 10) || 1),
  }));
  const boards = [{ id: 'todas', name: 'Todas', icon: '🎮', desc: 'Todas tus acciones', items, defaults: { label: 'ACCIONES', labelColor: '#a48bff', cols: Math.min(4, items.length) } }];
  // Lado A / Lado B: el streamer elige con los botones A | B de qué lado de la pantalla va cada acción.
  const sides = items.length >= 2 ? {
    items,
    a: { name: 'Lado A', icon: '🅰️', desc: 'Para un lado de la pantalla', defaults: { label: '', labelPos: 'none' } },
    b: { name: 'Lado B', icon: '🅱️', desc: 'Para el otro lado de la pantalla', defaults: { label: '', labelPos: 'none' } },
  } : null;
  window.openTableroPro({ game: cap.game, title: cap.title, boards, sides });
  return true;
}
/** Pone «✨ Generar imagen pro» junto a cada «Generar overlay» de los juegos (una sola vez). */
function attachTableroProButtons() {
  // «Generar overlay» (la mayoría), «Imagen regalos» (Minecraft) e «Imagen vertical/horizontal» (PvZ, Roblox).
  document.querySelectorAll('button[id$="-gen-overlay"], button[id$="-gen-img"], button[id$="-gen-img-v"]').forEach((ov) => {
    const game = ov.id.replace(/-gen-(overlay|img|img-v)$/, '');
    if (game === 'acc' || game === 'hill') return; // Acciones no es un juego; Hill tiene el suyo (Héroes/Villanos)
    if (document.getElementById(`${game}-gen-pro`)) return;
    const b = document.createElement('button');
    b.type = 'button';
    b.id = `${game}-gen-pro`;
    b.className = `${ov.className} tbp-open-btn`;
    b.title = 'Generar imagen pro: tablero animado para OBS o PNG, con tus acciones y regalos';
    b.textContent = '✨ Imagen pro';
    const after = document.getElementById(`${game}-gen-img-h`) || ov;
    after.insertAdjacentElement('afterend', b);
    b.addEventListener('click', async () => {
      const view = ov.closest('section.view, .view');
      const head = view && view.querySelector('.mc-hero-title, .game-title, h1, h2');
      const title = (head && head.textContent.trim().slice(0, 40)) || game;
      tableroProCapture = { game, title };
      b.disabled = true;
      try {
        if (typeof ov.onclick === 'function') await ov.onclick.call(ov, new MouseEvent('click'));
        else { ov.click(); await new Promise((r) => setTimeout(r, 4000)); }
      } catch { /* el juego ya avisa */ } finally {
        tableroProCapture = null;
        b.disabled = false;
      }
    });
  });
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', attachTableroProButtons);
else attachTableroProButtons();

