async function testBottleAction(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  syncGameCardQtyFromDom(a, 'bottleActions');
  const bridge = await bottleBridgeHealthApi().catch(() => null);
  if (!(bridge?.ok && bridge?.health?.running)) {
    toast && toast('Pulsa Ejecutar juego primero.', 'warn');
    return;
  }
  if (!bridge?.health?.gameConnected) {
    toast && toast('Abre el juego con Ejecutar juego.', 'warn');
    return;
  }
  const qty = Math.min(99, gameQtyForExec(a.count));
  const lastR = await execGameLocal({ tipo: 'BOTTLE_SPAWN', thing: a.thing, name: 'Prueba', userId: 'prueba', team: 'A', times: qty });
  if (lastR && lastR.ok !== false) toast && toast('Enviado a Bottle Battle.', 'ok');
  else if (lastR?.error === 'juego_no_conectado') toast && toast('El juego no está abierto. Pulsa Ejecutar juego.', 'warn');
  else toast && toast(lastR?.error || 'No se pudo enviar', 'warn');
}
function renderBottleActions() {
  const wrap = document.getElementById('bottle-my-actions');
  if (!wrap) return;
  registerGameActionRenderer('bottleActions', renderBottleActions);
  const list = ensureBottleActions();
  wrap.innerHTML = list.map(bottleCardHtml).join('') || '<p class="mc-empty">Todavía no hay acciones. Crea una y elige el regalo.</p>';
  wrap.querySelectorAll('.bottle-del').forEach((b) => {
    b.onclick = () => {
      ensureBottleActions();
      removeGameActions('bottleActions', (x) => x.uid !== b.dataset.uid, renderBottleActions);
    };
  });
  wrap.querySelectorAll('.bottle-count').forEach((inp) => {
    bindInstantGameQty(inp, () => ensureBottleActions().find((x) => x.uid === inp.dataset.uid), 'bottleActions');
  });
  const find = (uid) => ensureBottleActions().find((x) => x.uid === uid);
  bindGameActionConfigPopovers(wrap, find, renderBottleActions, { settingsKey: 'bottleActions', rerenderOnSave: true });
  bindGameSurvivalCardExtras(wrap, find, renderBottleActions, {
    settingsKey: 'bottleActions',
    testClass: 'bottle-test',
    onTest: (b) => {
      const a = find(b.dataset.uid);
      if (a) testBottleAction(a);
    },
  });
}
function bottleLaunchOpts() {
  let secs = 180;
  try { secs = Math.max(30, Math.min(3600, parseInt(localStorage.getItem('lc.bottle.secs'), 10) || 180)); } catch {}
  return { secs };
}
function setupBottleOptions() {
  const secs = document.getElementById('bottle-secs');
  if (!secs) return;
  secs.value = String(bottleLaunchOpts().secs);
  if (!secs._wired) {
    secs._wired = true;
    secs.onchange = () => {
      const v = Math.max(30, Math.min(3600, parseInt(secs.value, 10) || 180));
      secs.value = String(v);
      try { localStorage.setItem('lc.bottle.secs', String(v)); } catch {}
    };
  }
}
function setupBottleBridgeBtn() {
  const btn = document.getElementById('bottle-bridge');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    btn.disabled = true;
    try {
      const r = await ensureBottleBridgeApi();
      paintBridgeConnectBtn(btn, !!(r && r.ok));
      const missing = r && (r.error === 'sin_juego' || !(r.health && r.health.installed));
      toast && toast(r && r.ok ? 'Bottle Battle conectado. Ahora Ejecutar juego.' : (missing ? 'Pulsa Ejecutar juego. La primera vez lo descarga.' : 'No se pudo conectar'), r && r.ok ? 'ok' : 'warn');
    } finally { btn.disabled = false; }
  };
}
const BOTTLE_PACK_URL = 'https://github.com/paleteriadeyellow-tech/exe/releases/download/world/BottleBattle.rar';
async function bottleInstallWithProgress(startGame) {
  const status = document.getElementById('bottle-status');
  setGameModProgressUi('bottle', 2, 'Descargando Bottle Battle…');
  const mb = (n) => (n / 1048576).toFixed(0);
  const poll = setInterval(async () => {
    const st = (await bottleBridgeHealthApi().catch(() => null))?.health?.install;
    if (!st) return;
    let pct = 2;
    let label = 'Descargando Bottle Battle…';
    if (st.phase === 'extract') {
      pct = 96;
      label = 'Descomprimiendo…';
    } else if (st.total > 0) {
      pct = Math.max(2, Math.min(95, (st.received / st.total) * 95));
      label = `Descargando… ${Math.round((st.received / st.total) * 100)}% (${mb(st.received)} / ${mb(st.total)} MB)`;
    } else if (st.received > 0) {
      label = `Descargando… ${mb(st.received)} MB`;
    }
    setGameModProgressUi('bottle', pct, label);
    if (status) status.textContent = label;
  }, 700);
  try {
    const r = await startGame();
    clearInterval(poll);
    finishGameModProgressUi('bottle', !!r?.ok, 'Juego listo', 'No se pudo descargar');
    return r;
  } catch (e) {
    clearInterval(poll);
    finishGameModProgressUi('bottle', false, 'Juego listo', 'No se pudo descargar');
    throw e;
  }
}
function setupBottleLaunchBtn() {
  setupBottleOptions();
  const btn = document.getElementById('bottle-launch');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
    btn.disabled = true;
    let ready = null;
    try {
      const cur = await bottleBridgeHealthApi().catch(() => null);
      const needDownload = !(cur && cur.health && cur.health.installed);
      const startGame = () => fetch('/api/desktop/ensure-bottle-bridge', {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ installIfMissing: true, url: BOTTLE_PACK_URL }),
      }).then((x) => x.json()).catch(() => ({ ok: false, error: 'sin_red' }));
      ready = needDownload ? await bottleInstallWithProgress(startGame) : await startGame();
    } finally {
      btn.disabled = false;
    }
    if (!ready || !ready.ok) {
      const err = String((ready && ready.error) || '');
      toast && toast(err && err !== 'no_bridge' && err !== 'sin_juego' ? err : 'No se pudo preparar Bottle Battle', 'warn');
      return;
    }
    try {
      await fetch('/api/desktop/bottle-round', {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ secs: bottleLaunchOpts().secs }),
      });
    } catch { /* la ventana igual se abre */ }
    if (ready.health && ready.health.port && ready.health.port !== 9978 && ready.health.gameConnected) {
      toast && toast('Bottle Battle ya está abierto. Los regalos van a esa ventana.', 'ok');
      return;
    }
    if (window.desktopAPI?.openBottle) {
      const r = await window.desktopAPI.openBottle();
      toast && toast(r && r.ok !== false ? 'Bottle Battle abierto' : 'No se pudo abrir el juego', r && r.ok !== false ? 'ok' : 'warn');
      return;
    }
    if (window.desktopAPI) {
      toast && toast('Cierra Livecoins y ábrelo otra vez para usar la ventana del juego.', 'warn');
      return;
    }
    window.open('http://127.0.0.1:9978/', '_blank', 'noopener,noreferrer');
  };
}
function setupBottleStatusPoll() {
  if (setupBottleStatusPoll._on) return;
  setupBottleStatusPoll._on = true;
  const tick = async () => {
    const el = document.getElementById('bottle-status');
    const btn = document.getElementById('bottle-bridge');
    if (!el && !btn) return;
    if (!(el || btn).closest(".view.active") || document.hidden) return; // pestaña cerrada: no consultar
    const cur = await bottleBridgeHealthApi().catch(() => null);
    if (cur?.health?.install) return;
    const running = !!(cur?.ok && cur?.health?.running);
    const gameOn = !!cur?.health?.gameConnected;
    paintBridgeConnectBtn(btn, running);
    if (el) el.textContent = !running ? 'Pulsa Ejecutar juego.' : (gameOn ? 'Juego abierto. El chat, los likes y los regalos entran.' : 'Pulsa Ejecutar juego.');
  };
  setInterval(tick, 4000);
  // Al volver a la pestaña del juego, refrescar ya (no esperar 4 s).
  document.addEventListener('click', (e) => { if (e.target.closest?.('.nav-item, [data-view], [data-game]')) setTimeout(tick, 250); });
  tick();
}
async function bottleAddTestPlayers() {
  if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  const bridge = await bottleBridgeHealthApi().catch(() => null);
  if (!bridge?.health?.gameConnected) { toast && toast('Primero pulsa Ejecutar juego.', 'warn'); return; }
  const a = await execGameLocal({ tipo: 'BOTTLE_SPAWN', thing: 'join', name: 'Azul', userId: 'prueba_azul', team: 'A', times: 1 }).catch(() => null);
  const b = await execGameLocal({ tipo: 'BOTTLE_SPAWN', thing: 'join', name: 'Rojo', userId: 'prueba_rojo', team: 'B', times: 1 }).catch(() => null);
  const ok = (a && a.ok !== false) || (b && b.ok !== false);
  toast && toast(ok ? 'Jugadores de prueba en las botellas' : 'No se pudieron meter', ok ? 'ok' : 'warn');
}
function setupBottleActionsUI() {
  const testPlayers = document.getElementById('bottle-test-players');
  if (testPlayers && !testPlayers._wired) {
    testPlayers._wired = true;
    testPlayers.onclick = async () => {
      testPlayers.disabled = true;
      try { await bottleAddTestPlayers(); } finally { testPlayers.disabled = false; }
    };
  }
  const open = document.getElementById('bottle-open-catalog');
  if (open && !open._wired) {
    open._wired = true;
    open.onclick = () => {
      const modal = document.getElementById('bottleCatalogModal');
      if (modal) modal.classList.remove('hidden');
      renderBottleCatalog('');
    };
  }
  const toggleAll = document.getElementById('bottle-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensureBottleActions();
      const on = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = on; });
      lastGameActionEditAt = Date.now();
      try { recentGameActionEditKeys.add('bottleActions'); } catch {}
      saveSettingsKeysPatch('bottleActions', { flush: true, skipErSync: true });
      renderBottleActions();
    };
  }
  const genOverlayBtn = document.getElementById('bottle-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generateBottleOverlayImage();
  }
  renderBottleActions();
}
async function generateBottleOverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensureBottleActions(),
    iconUrlFor: (a) => bottleIconSrc(a?.thing),
    downloadName: 'bottle-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'bottleActions',
  });
}

