const PVZGE_SECTION_ORDER = ['sun', 'plant', 'zombie'];
const PVZGE_SECTION_LABEL = { sun: 'Soles', plant: 'Plantas', zombie: 'Zombis' };
const PVZGE_SECTION_ICON = { sun: '☀️', plant: '🌱', zombie: '🧟' };
const PVZGE_SECTION_DESC = { sun: 'Suma soles', plant: 'Aparecen en el césped', zombie: 'Entran por la derecha' };
function pvzgeDefaultCount(thing) { return thing === 'sun' ? 100 : 1; }
function pvzgeCountLabel(thing) {
  if (thing === 'sun') return 'Soles';
  if (String(thing || '').startsWith('zombie:')) return 'Zombis';
  return 'Plantas';
}
function pvzgeCatalogEntry(thing) { return PVZGE_CATALOG.find((x) => x.id === thing); }
function pvzgeIcon(c, cls = 'repo-cat-list-ic') {
  const id = String((c && c.id) || '').split(':').pop().replace(/[^a-z0-9_]/gi, '');
  const em = (c && c.emoji) || '🌻';
  if (!id) return `<span class="${cls}">${em}</span>`;
  return `<img class="${cls}" src="/img/pvzge/${id}.png?v=pz6" alt="" loading="lazy" decoding="async" onerror="this.outerHTML='<span class=\\'repo-cat-list-em\\'>${em}</span>'">`;
}
function ensurePvzgeActions() {
  if (!settings.pvzgeActions) settings.pvzgeActions = [];
  for (const a of settings.pvzgeActions) {
    const c = pvzgeCatalogEntry(a.thing);
    if (c) {
      if (!a.label) a.label = c.nombre;
      if (!a.desc) a.desc = c.desc;
    }
    keepStoredGameQty(a, pvzgeDefaultCount(a.thing));
  }
  return settings.pvzgeActions;
}
registerGameActSwap('pvzge', {
  title: 'Clic para cambiar el efecto',
  heading: 'Cambiar efecto',
  placeholder: 'Buscar…',
  entries: () => PVZGE_CATALOG.map((c) => ({
    id: c.id, name: c.nombre, desc: c.desc, iconHtml: pvzgeIcon(c),
  })),
  current: (uid) => ensurePvzgeActions().find((x) => x && x.uid === uid)?.thing,
  apply: gameActSwapApply({
    actions: ensurePvzgeActions,
    entry: pvzgeCatalogEntry,
    settingsKey: 'pvzgeActions',
    render: () => renderPvzgeActions(),
  }),
});
function pvzgeCardHtml(a) {
  const c = pvzgeCatalogEntry(a.thing);
  const qty = gameQtyShown(a.count);
  return gameSurvivalStyleCardHtml(a, {
    settingsKey: 'pvzgeActions',
    thumbHtml: pvzgeIcon(c || { emoji: '🌻' }, 'mc-act-ic repo-cat-list-ic'),
    nameHtml: gameActSwapNameHtml(a, 'pvzge'),
    infoExtraHtml: `<label class="mc-qty-row" title="Cantidad">${pvzgeCountLabel(a.thing)}
      <input type="number" min="1" class="pvzge-count mc-qty-n" data-uid="${esc(a.uid)}" value="${esc(qty)}"></label>`,
    cfgOpts: { countValue: qty },
    testClass: 'pvzge-test',
    delClass: 'pvzge-del',
  });
}
function renderPvzgeCatalog(filter) {
  const f = (filter || '').trim().toLowerCase();
  const list = f
    ? PVZGE_CATALOG.filter((c) => c.nombre.toLowerCase().includes(f) || c.id.includes(f) || (c.desc || '').toLowerCase().includes(f))
    : PVZGE_CATALOG;
  renderGameCatalogFold({
    grid: 'pvzge-catalog',
    stateKey: 'pvzge',
    filter: f,
    searchId: 'pvzge-cat-search',
    rerender: renderPvzgeCatalog,
    closeModalId: 'pvzgeCatalogModal',
    sections: buildCatalogSections(list, {
      sectionKey: 'section',
      order: PVZGE_SECTION_ORDER,
      labelMap: PVZGE_SECTION_LABEL,
      iconMap: PVZGE_SECTION_ICON,
      descMap: PVZGE_SECTION_DESC,
      searching: !!f,
    }),
    rowHtml: (c) => gameCatListBtnHtml(c.id, c.nombre, pvzgeIcon(c), c.desc || c.nombre),
    onPick: addPvzgeFromCatalog,
  });
}
function addPvzgeFromCatalog(thing) {
  const c = pvzgeCatalogEntry(thing);
  if (!c || !settings) return;
  ensurePvzgeActions().push({
    uid: 'pvzge_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
    thing: c.id,
    label: c.nombre,
    desc: c.desc,
    section: c.section,
    trigger: 'gift',
    giftId: '',
    giftName: '',
    giftImage: '',
    count: pvzgeDefaultCount(c.id),
    text: '',
    enabled: false,
  });
  lastGameActionEditAt = Date.now();
  try { recentGameActionEditKeys.add('pvzgeActions'); } catch {}
  saveSettingsKeysPatch('pvzgeActions', { flush: true, skipErSync: true });
  renderPvzgeActions();
  renderPvzgeCatalog(document.getElementById('pvzge-cat-search')?.value || '');
  toast && toast(`Agregado: ${c.nombre}`, 'ok');
}
async function pvzgeBridgeHealthApi() {
  const r = await fetch('/api/desktop/pvzge-bridge-health', { credentials: 'same-origin' });
  return r.json();
}
async function ensurePvzgeBridgeApi() {
  const r = await fetch('/api/desktop/ensure-pvzge-bridge', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: '{}' });
  return r.json();
}
async function testPvzgeAction(a) {
  if (!a?.thing || !IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return; }
  syncGameCardQtyFromDom(a, 'pvzgeActions');
  const bridge = await pvzgeBridgeHealthApi().catch(() => null);
  if (!(bridge?.ok && bridge?.health?.running)) {
    toast && toast('Pulsa Ejecutar juego primero.', 'warn');
    return;
  }
  if (!bridge?.health?.gameConnected) {
    toast && toast('Entra a un nivel dentro del juego.', 'warn');
  }
  const lastR = await execGameLocal({ tipo: 'GARDEN_SPAWN', thing: a.thing, name: 'Prueba', times: gameQtyForExec(a.count) });
  if (lastR && lastR.ok !== false) toast && toast('Enviado a PvZ2.', 'ok');
  else if (lastR?.error === 'juego_no_conectado') toast && toast('Entra a un nivel. El menú no recibe acciones.', 'warn');
  else toast && toast(lastR?.error || 'No se pudo enviar', 'warn');
}
function renderPvzgeActions() {
  const wrap = document.getElementById('pvzge-my-actions');
  if (!wrap) return;
  registerGameActionRenderer('pvzgeActions', renderPvzgeActions);
  const list = ensurePvzgeActions();
  wrap.innerHTML = list.map(pvzgeCardHtml).join('') || '<p class="mc-empty">Todavía no hay acciones. Crea una y elige el regalo.</p>';
  wrap.querySelectorAll('.pvzge-del').forEach((b) => {
    b.onclick = () => {
      ensurePvzgeActions();
      removeGameActions('pvzgeActions', (x) => x.uid !== b.dataset.uid, renderPvzgeActions);
    };
  });
  wrap.querySelectorAll('.pvzge-count').forEach((inp) => {
    bindInstantGameQty(inp, () => ensurePvzgeActions().find((x) => x.uid === inp.dataset.uid), 'pvzgeActions');
  });
  const find = (uid) => ensurePvzgeActions().find((x) => x.uid === uid);
  bindGameActionConfigPopovers(wrap, find, renderPvzgeActions, { settingsKey: 'pvzgeActions', rerenderOnSave: true });
  bindGameSurvivalCardExtras(wrap, find, renderPvzgeActions, {
    settingsKey: 'pvzgeActions',
    testClass: 'pvzge-test',
    onTest: (b) => {
      const a = find(b.dataset.uid);
      if (a) testPvzgeAction(a);
    },
  });
}
function setupPvzgeBridgeBtn() {
  const btn = document.getElementById('pvzge-bridge');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    btn.disabled = true;
    try {
      const r = await ensurePvzgeBridgeApi();
      paintBridgeConnectBtn(btn, !!(r && r.ok));
      toast && toast(r && r.ok ? 'PvZ2 conectado. Ahora Ejecutar juego.' : 'No se pudo conectar', r && r.ok ? 'ok' : 'warn');
    } finally { btn.disabled = false; }
  };
}
function pvzgeMb(bytes) {
  return Math.round((Number(bytes) || 0) / (1024 * 1024));
}
let pvzgeDownloadJob = null;
async function pvzgeDownloadGame() {
  if (pvzgeDownloadJob) return pvzgeDownloadJob;
  if (!IS_DESKTOP) { toast && toast('Solo en la app .exe', 'warn'); return ''; }
  const btn = document.getElementById('pvzge-download');
  if (btn) btn.disabled = true;
  setGameModProgressUi('pvzge', 1, 'Conectando…');
  const poll = setInterval(async () => {
    const p = await fetch('/api/desktop/pvzge-install-progress', { credentials: 'same-origin' })
      .then((r) => r.json()).catch(() => null);
    if (!p) return;
    if (p.phase === 'download') {
      const pct = p.total ? (p.received / p.total) * 90 : 5;
      const of = p.total ? ` de ${pvzgeMb(p.total)} MB` : '';
      setGameModProgressUi('pvzge', pct, `Descargando… ${pvzgeMb(p.received)}${of}`);
    } else if (p.phase === 'extract') {
      setGameModProgressUi('pvzge', 94, 'Descomprimiendo… (puede tardar un poco)');
    }
  }, 700);
  pvzgeDownloadJob = (async () => {
    try {
      const r = await fetch('/api/desktop/pvzge-install', {
        method: 'POST', credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' }, body: '{}',
      });
      const data = await r.json().catch(() => ({}));
      clearInterval(poll);
      finishGameModProgressUi('pvzge', !!data.ok, 'Juego descargado', 'No se pudo descargar');
      if (!data.ok) {
        toast && toast(data.error || 'No se pudo descargar el juego.', 'warn');
        return '';
      }
      toast && toast('PvZ2 descargado. Abriendo…', 'ok');
      return data.dir || '';
    } catch {
      clearInterval(poll);
      finishGameModProgressUi('pvzge', false, 'Juego descargado', 'No se pudo descargar');
      toast && toast('No se pudo descargar el juego.', 'warn');
      return '';
    } finally {
      if (btn) btn.disabled = false;
      pvzgeDownloadJob = null;
    }
  })();
  return pvzgeDownloadJob;
}
function setupPvzgeDownloadBtn() {
  const btn = document.getElementById('pvzge-download');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    const health = await pvzgeBridgeHealthApi().catch(() => null);
    if (health?.health?.hasGame && !(await appConfirm({ title: 'Ya tienes el juego', message: '¿Descargarlo otra vez?', confirmText: 'Descargar', icon: '⬇️', danger: false }))) return;
    await pvzgeDownloadGame();
  };
}
async function pvzgeEnsureDir() {
  const health = await pvzgeBridgeHealthApi().catch(() => null);
  if (health?.health?.hasGame && health?.health?.gameDir) return health.health.gameDir;
  toast && toast('Descargando PvZ2 (1.2 GB, solo la primera vez)…', 'ok');
  return pvzgeDownloadGame();
}
function setupPvzgePickBtn() {
  const btn = document.getElementById('pvzge-pick');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    if (!window.desktopAPI?.pickPvzgeDir) { toast && toast('Solo en la app .exe', 'warn'); return; }
    const picked = await window.desktopAPI.pickPvzgeDir();
    if (!picked) return;
    const r = await fetch('/api/desktop/pvzge-dir', {
      method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ dir: picked }),
    });
    const data = await r.json().catch(() => ({}));
    toast && toast(data.ok ? 'Carpeta del juego guardada.' : 'Elige la carpeta que tiene index.html.', data.ok ? 'ok' : 'warn');
  };
}
function setupPvzgeLaunchBtn() {
  const btn = document.getElementById('pvzge-launch');
  if (!btn || btn._wired) return;
  btn._wired = true;
  btn.onclick = async () => {
    if (btn.disabled) return;
    btn.disabled = true;
    let dir = '';
    try {
      await ensurePvzgeBridgeApi().catch(() => {});
      dir = await pvzgeEnsureDir();
    } finally { btn.disabled = false; }
    if (!dir) return;
    await ensurePvzgeBridgeApi().catch(() => {});
    if (window.desktopAPI?.openPvzge) {
      const r = await window.desktopAPI.openPvzge();
      toast && toast(r && r.ok !== false ? 'PvZ2 abierto. Entra a un nivel.' : 'No se pudo abrir el juego', r && r.ok !== false ? 'ok' : 'warn');
      return;
    }
    if (window.desktopAPI) {
      toast && toast('Cierra Livecoins y ábrelo otra vez para usar la ventana del juego.', 'warn');
      return;
    }
    window.open('http://127.0.0.1:9976/', '_blank', 'noopener,noreferrer');
  };
}
function setupPvzgeStatusPoll() {
  if (setupPvzgeStatusPoll._on) return;
  setupPvzgeStatusPoll._on = true;
  const tick = async () => {
    const el = document.getElementById('pvzge-status');
    const btn = document.getElementById('pvzge-bridge');
    if (!el && !btn) return;
    if (!(el || btn).closest(".view.active") || document.hidden) return; // pestaña cerrada: no consultar
    const cur = await pvzgeBridgeHealthApi().catch(() => null);
    const running = !!(cur?.ok && cur?.health?.running);
    const gameOn = !!cur?.health?.gameConnected;
    const hasGame = !!cur?.health?.hasGame;
    paintBridgeConnectBtn(btn, running);
    if (el) {
      el.textContent = !hasGame
        ? 'Pulsa Ejecutar juego. La primera vez lo descarga solo.'
        : (!running ? 'Pulsa Ejecutar juego.' : (gameOn ? 'En un nivel. Los regalos entran.' : 'Abre el juego y entra a un nivel.'));
    }
  };
  setInterval(tick, 4000);
  // Al volver a la pestaña del juego, refrescar ya (no esperar 4 s).
  document.addEventListener('click', (e) => { if (e.target.closest?.('.nav-item, [data-view], [data-game]')) setTimeout(tick, 250); });
  tick();
}
function setupPvzgeActionsUI() {
  const open = document.getElementById('pvzge-open-catalog');
  if (open && !open._wired) {
    open._wired = true;
    open.onclick = (e) => {
      e.preventDefault();
      openGameCatalogModal({ prefix: 'pvzge', modalId: 'pvzgeCatalogModal', render: renderPvzgeCatalog });
    };
  }
  const toggleAll = document.getElementById('pvzge-toggle-all');
  if (toggleAll && !toggleAll._wired) {
    toggleAll._wired = true;
    toggleAll.onclick = () => {
      const list = ensurePvzgeActions();
      const on = list.some((a) => a.enabled === false);
      list.forEach((a) => { a.enabled = on; });
      lastGameActionEditAt = Date.now();
      try { recentGameActionEditKeys.add('pvzgeActions'); } catch {}
      saveSettingsKeysPatch('pvzgeActions', { flush: true, skipErSync: true });
      renderPvzgeActions();
    };
  }
  const genOverlayBtn = document.getElementById('pvzge-gen-overlay');
  if (genOverlayBtn && !genOverlayBtn._wired) {
    genOverlayBtn._wired = true;
    genOverlayBtn.onclick = () => generatePvzgeOverlayImage();
  }
  renderPvzgeActions();
}

function pvzgeOverlayIconUrl(a) {
  const id = String((a && a.thing) || '').split(':').pop().replace(/[^a-z0-9_]/gi, '');
  return id ? `/img/pvzge/${id}.png?v=pz6` : '';
}

async function generatePvzgeOverlayImage() {
  return generateGameActionsOverlayImage({
    ensureList: () => ensurePvzgeActions(),
    iconUrlFor: pvzgeOverlayIconUrl,
    downloadName: 'pvzge-overlay.png',
    emptyToast: 'Agrega acciones del catálogo primero.',
    settingsKey: 'pvzgeActions',
  });
}

try { if (typeof initGameCatalogModals === 'function') initGameCatalogModals(); } catch (e) { console.warn('initGameCatalogModals', e); }
window.__lcDashboardGamesReady = true;
try { window.dispatchEvent(new Event('lc-dashboard-games-ready')); } catch {}
